// src/data/eventsAi.js
// 612 event cards drafted by Claude (plans/ai-output/event-cards, reviewed), as draws of the event deck:
// shown only to a player whose people has this card's art theme (peoples.js), in this age once the
// player has the techs for its year, once a game, at a low weight beside the hand-written events.
// Effects are capped at the largest the hand-written events use. Hebrew: i18n/locales/data/he.eventsAi.js.
import { getAgeIndex } from './ages';
import { ageIdOfYear, eventTechsNeeded } from './events';

export const AI_CARD_WEIGHT = 4; // hand-written draws weigh 8 to 30
const CARDS = [{"id":"ai_levant_stamped_electrum","ageId":"classical","year":-610,"theme":"levant","title":"Lumps With a Lion","description":"Your goldsmiths propose stamping electrum from the Pactolus with a lion's head, so merchants trust the weight without a scale.","options":[{"label":"Strike royal stamped coins","effects":{"gold":-60,"techPoints":30,"controlBonus":5}},{"label":"Keep weighing metal by the scale","effects":{"gold":40}}]},{"id":"ai_levant_cimmerian_riders","ageId":"classical","year":-696,"theme":"levant","title":"Riders From the North","description":"Cimmerian horsemen pour across the Halys and ride toward Gordion, burning villages as they come.","options":[{"label":"Pay the riders to pass by","effects":{"gold":-120,"controlBonus":5}},{"label":"Man the citadel walls","effects":{"hr":-40,"defenseBonus":0.1}}]},{"id":"ai_levant_erebuni_captives","ageId":"classical","year":-782,"theme":"levant","title":"A Fortress at Erebuni","description":"You have raised a new fortress on the Ararat plain, and thousands of captives from your campaigns await your word.","options":[{"label":"Settle the captives around the fortress","effects":{"hr":-50,"defenseBonus":0.1,"controlPenalty":5}},{"label":"Return them to their valleys","effects":{"gold":-30}}]},{"id":"ai_levant_median_army_reform","ageId":"classical","year":-615,"theme":"levant","title":"Spears, Bows and Horses","description":"Your levies fight as mixed clan bands. Your officers urge you to split them into separate units of spearmen, archers and cavalry before marching on Assyria.","options":[{"label":"Divide the army by arms","effects":{"gold":-100,"militaryStrengthBonus":50}},{"label":"Keep the clan war bands","effects":{"controlBonus":5}}]},{"id":"ai_levant_marib_sluices","ageId":"classical","year":-700,"theme":"levant","title":"The Great Dam Cracks","description":"Floods in the Wadi Dhana have scoured the dam's sluices. Without repair, the fields of the two oases will go dry.","options":[{"label":"Rebuild the sluices in cut stone","effects":{"gold":-150,"hr":-30,"controlBonus":10}},{"label":"Patch it with earth and hope","effects":{"gold":-20,"controlPenalty":5}}]},{"id":"ai_levant_tribute_to_assyria","ageId":"classical","year":-738,"theme":"levant","title":"The Assyrian Demand","description":"Tiglath-Pileser's army stands in Syria, and his envoys demand camels and tribute from the queen of the Arabs.","options":[{"label":"Send camels and gold","effects":{"gold":-100}},{"label":"Withdraw deep into the desert","effects":{"hr":-20,"defenseBonus":0.05}}]},{"id":"ai_levant_roman_annexation","ageId":"classical","year":106,"theme":"levant","title":"Rome Takes Arabia","description":"Trajan has annexed the Nabataean kingdom, and a Roman detachment marches south to garrison Hegra and its caravan road.","options":[{"label":"Open the gates to the garrison","effects":{"gold":60,"controlPenalty":10}},{"label":"Shelter Nabataean loyalists","effects":{"hr":-30,"militaryStrengthBonus":20}}]},{"id":"ai_levant_asiatic_vespers","ageId":"classical","year":-88,"theme":"levant","title":"Letters to Every City","description":"Your armies hold Asia. Your advisors propose secret orders to the cities to fall on every Roman and Italian on the same day.","options":[{"label":"Send the orders to kill","effects":{"militaryStrengthBonus":40,"controlBonus":10}},{"label":"Seize their goods, spare their lives","effects":{"gold":120,"controlPenalty":5}}]},{"id":"ai_westafrica_looted_terracottas","ageId":"information","year":1998,"theme":"westafrica","title":"Terracottas on Foreign Markets","description":"Diggers are stripping ancient Nok sites at night, and the clay heads turn up in European auction houses. Your village elders demand action.","options":[{"label":"Post armed guards at the sites","effects":{"gold":-100,"controlBonus":5}},{"label":"Press foreign museums for return","effects":{"gold":-50}},{"label":"Sell legal export permits","effects":{"gold":120,"controlPenalty":6}}]},{"id":"ai_westafrica_gsm_licences","ageId":"information","year":2001,"theme":"westafrica","title":"The Mobile Phone Licences","description":"Telecom giants bid for the right to build mobile networks, Ayo. A high price fills the treasury, but cheap licences could put a phone in every market.","options":[{"label":"Auction to the highest bidder","effects":{"gold":200,"controlPenalty":5}},{"label":"Grant cheap licences for wide coverage","effects":{"gold":-50,"techPoints":60}}]},{"id":"ai_westafrica_home_video_boom","ageId":"information","year":1992,"theme":"westafrica","title":"The Home Video Boom","description":"Cheap cameras and video cassettes have turned Ile-Ife's actors into stars, but pirated copies sell faster than the originals.","options":[{"label":"Fund local studios","effects":{"gold":-80,"techPoints":20,"controlBonus":5}},{"label":"Raid the pirate markets","effects":{"gold":-60,"controlPenalty":4}},{"label":"Tax the trade and look away","effects":{"gold":70,"techPoints":-10}}]},{"id":"ai_westafrica_offshore_oil_find","ageId":"information","year":2007,"theme":"westafrica","title":"Oil Beneath the Sea","description":"Drillers strike a large oil field off the coast, and the capital fills with consultants. How fast you pump will shape a generation.","options":[{"label":"Pump as fast as possible","effects":{"oil":50,"gold":100,"controlPenalty":8}},{"label":"Pass a law to save revenues","effects":{"oil":50,"gold":-40}}]},{"id":"ai_westafrica_cobalt_rush","ageId":"information","year":2008,"theme":"westafrica","title":"The Cobalt Rush","description":"The world's phones and batteries need cobalt, and diggers with shovels crowd the pits near Kolwezi. Foreign companies offer to take over.","options":[{"label":"Sell concessions to foreign miners","effects":{"copper":50,"gold":150,"controlPenalty":10}},{"label":"Organize the diggers into cooperatives","effects":{"copper":50,"gold":-80,"controlBonus":6}}]},{"id":"ai_westafrica_diamond_certification","ageId":"information","year":2003,"theme":"westafrica","title":"Certifying the Diamonds","description":"A new international scheme demands that every rough diamond carry a certificate of origin. Lunda diggers have long sold theirs across the border.","options":[{"label":"Join the certification scheme","effects":{"gold":-80}},{"label":"Quietly tolerate the smugglers","effects":{"gold":150,"controlPenalty":8}}]},{"id":"ai_westafrica_ebola_outbreak","ageId":"information","year":2018,"theme":"westafrica","title":"Ebola Returns","description":"Ebola breaks out in the eastern provinces, Lueji. A new vaccine exists, but health teams face distrust and armed groups on the roads.","options":[{"label":"Send vaccination teams with escorts","effects":{"gold":-150,"techPoints":20,"hr":-30}},{"label":"Seal the roads out of the region","effects":{"gold":-40,"controlPenalty":6}}]},{"id":"ai_westafrica_ceasefire_demobilization","ageId":"information","year":2002,"theme":"westafrica","title":"After the Ceasefire","description":"The long civil war is over, Ngola Kiluanje, and tens of thousands of rebel fighters wait in camps. Each one needs a future.","options":[{"label":"Absorb them into the army","effects":{"hr":60,"gold":-150}},{"label":"Pay them to go home","effects":{"gold":-200,"controlBonus":10}},{"label":"Disband the camps without pay","effects":{"gold":50,"controlPenalty":12}}]},{"id":"ai_europe_siege_of_candia","ageId":"gunpowder","year":1648,"theme":"europe","title":"The Long Siege","description":"Ottoman armies have landed on Crete and dug trenches before the great walled port near Knossos. Engineers beg for powder and stone; merchants beg for peace.","options":[{"label":"Pour silver into the bastions","effects":{"gold":-150,"defenseBonus":0.1}},{"label":"Seek terms from the Sultan","effects":{"controlPenalty":8}}]},{"id":"ai_europe_iron_mountain_union","ageId":"gunpowder","year":1625,"theme":"europe","title":"The Iron Mountain Guilds","description":"The quarrelling ironmasters of the Styrian ore mountain near Noreia are going bankrupt. Your treasurers propose merging them into one crown-backed company.","options":[{"label":"Merge them under crown oversight","effects":{"gold":-100,"iron":50}},{"label":"Let the old guilds compete","effects":{"iron":40,"controlPenalty":4}}]},{"id":"ai_europe_bursting_bottles","ageId":"gunpowder","year":1729,"theme":"europe","title":"Wine That Bursts","description":"Cellars around Durocortorum now sell wine that foams in the glass, but many bottles explode in the heat. Glassmakers promise thicker bottles at a high price.","options":[{"label":"Fund stronger glassworks","effects":{"gold":-80,"techPoints":25}},{"label":"Tax the foaming wine trade","effects":{"gold":70,"controlPenalty":3}}]},{"id":"ai_europe_portuguese_succession","ageId":"gunpowder","year":1580,"theme":"europe","title":"A Crown Without Heir","description":"The old king has died childless, and the King of Spain claims the throne with gold and soldiers. A royal bastard rallies the commons against him.","options":[{"label":"Accept the Spanish crown","effects":{"gold":120,"controlPenalty":10}},{"label":"Back the pretender's army","effects":{"gold":-90,"militaryStrengthBonus":8,"controlBonus":5}}]},{"id":"ai_europe_allied_fleet_kerch","ageId":"gunpowder","year":1855,"theme":"europe","title":"Fleets in the Strait","description":"British and French warships are heading for the strait at Panticapaeum to cut supplies to the besieged Crimean fortress. The garrison cannot hold everything.","options":[{"label":"Burn the depots and withdraw","effects":{"gold":-60,"controlPenalty":6}},{"label":"Reinforce the shore batteries","effects":{"hr":-80,"defenseBonus":0.1}}]},{"id":"ai_europe_dutch_timber_trade","ageId":"gunpowder","year":1620,"theme":"europe","title":"Dutch Ships for Timber","description":"Dutch skippers crowd the fjords of the Rygir, paying well for sawn planks and masts. Water-powered sawmills spread, and the forests thin quickly.","options":[{"label":"License the sawmills and tax them","effects":{"gold":110,"controlPenalty":4}},{"label":"Reserve the oaks for your navy","effects":{"gold":-40,"militaryStrengthBonus":6}}]},{"id":"ai_europe_mountain_serf_revolt","ageId":"gunpowder","year":1784,"theme":"europe","title":"The Miners Rise","description":"Serfs of the gold-mining mountains of Dacia have risen against their lords, burning manors and demanding freedom. The nobles demand troops; the peasants demand justice.","options":[{"label":"Crush the rising by force","effects":{"hr":-60,"controlBonus":8}},{"label":"Ease the labor dues","effects":{"gold":-90,"controlBonus":5}}]},{"id":"ai_europe_foreign_excavator","ageId":"gunpowder","year":1876,"theme":"europe","title":"A Rich Man Digs","description":"A wealthy German merchant asks to dig the shaft graves at Mycenae, promising golden treasures. Your archaeologists fear he will strip the site and boast abroad.","options":[{"label":"Grant the permit under supervision","effects":{"techPoints":35,"gold":-30}},{"label":"Refuse and dig yourselves","effects":{"gold":-100,"techPoints":20}}]},{"id":"ai_japan_buddha_from_baekje","ageId":"kingdoms","year":552,"theme":"japan","title":"A Gilded Buddha Arrives","description":"Envoys from Baekje present a gilded statue and sutras, urging you to honor the foreign Buddha. Clans loyal to the old kami warn of divine anger.","options":[{"label":"Build temples and welcome the monks","effects":{"gold":-80,"techPoints":30,"controlPenalty":6}},{"label":"Cast the statue into the canal","effects":{"controlBonus":6}}]},{"id":"ai_japan_land_census_reform","ageId":"kingdoms","year":646,"theme":"japan","title":"All Land to the Throne","description":"Your ministers propose a Chinese-style reform: every rice field registered, owned by the throne and allotted by census. The great clans would lose their private estates.","options":[{"label":"Order the census and redistribute fields","effects":{"gold":-60,"hr":-20,"controlBonus":12}},{"label":"Leave the clans their estates","effects":{"gold":40,"controlPenalty":8}}]},{"id":"ai_japan_envoys_to_tang","ageId":"kingdoms","year":630,"theme":"japan","title":"Ships to the Tang Court","description":"Scholars and monks beg passage to Chang'an to study law, writing and medicine. The crossing is perilous and many ships never return.","options":[{"label":"Fit out the envoy ships","effects":{"gold":-100,"hr":-15,"techPoints":40}},{"label":"Learn from Korean refugees instead","effects":{"gold":-30,"techPoints":12}}]},{"id":"ai_japan_ambush_at_the_river","ageId":"kingdoms","year":789,"theme":"japan","title":"Ambush on the Kitakami","description":"An imperial army fords the Kitakami River to burn your villages. Your scouts say part of it can be trapped against the water.","options":[{"label":"Strike them at the riverbank","effects":{"hr":-40,"militaryStrengthBonus":0.1}},{"label":"Withdraw into the hills","effects":{"gold":-30,"defenseBonus":0.06,"controlPenalty":5}}]},{"id":"ai_japan_palisade_of_isawa","ageId":"kingdoms","year":801,"theme":"japan","title":"The Shogun Approaches","description":"A new general of the court marches north with a larger army than any before. Isawa's elders debate walls or a bargain.","options":[{"label":"Raise a palisade around Isawa","effects":{"gold":-90,"defenseBonus":0.1}},{"label":"Trade horses for imperial iron","effects":{"iron":40,"controlPenalty":7}}]},{"id":"ai_japan_gold_of_mutsu","ageId":"kingdoms","year":749,"theme":"japan","title":"Gold in the Northern Streams","description":"Gold has been found in the rivers of your lands, and the court wants it for a great bronze Buddha. Its agents offer rich trade goods.","options":[{"label":"Sell gold and horses to the court","effects":{"gold":120,"controlPenalty":8}},{"label":"Hide the streams and keep your herds","effects":{"gold":-30,"militaryStrengthBonus":0.08}}]},{"id":"ai_japan_mongol_fleet","ageId":"kingdoms","year":1274,"theme":"japan","title":"Mongol Sails at Hakata","description":"The Mongol khan, having demanded submission, lands an army at Hakata Bay. Even after a storm scatters it, he will surely return.","options":[{"label":"Build a stone wall along the bay","effects":{"gold":-120,"hr":-20,"defenseBonus":0.1}},{"label":"Receive the khan's envoys","effects":{"controlPenalty":10}}]},{"id":"ai_japan_kangi_famine","ageId":"kingdoms","year":1231,"theme":"japan","title":"The Cold Summer","description":"A cold, wet summer ruins the rice harvest and starving families sell themselves into servitude. Your granaries cannot feed everyone.","options":[{"label":"Open the granaries to all","effects":{"gold":-80,"controlBonus":8}},{"label":"Feed only soldiers and officials","effects":{"hr":-50,"gold":30,"controlPenalty":6}}]},{"id":"ai_pacific_kuk_world_heritage","ageId":"information","year":2008,"theme":"pacific","title":"Ancient Fields Win Recognition","description":"The old drainage ditches of Kuk swamp are named a World Heritage site. Visitors and scholars want the ground protected, but local families still plant gardens there.","options":[{"label":"Fence off the ancient fields","effects":{"gold":-80,"controlPenalty":5}},{"label":"Let the families keep planting","effects":{"controlBonus":6}}]},{"id":"ai_pacific_mine_tailings_river","ageId":"information","year":1996,"theme":"pacific","title":"Poison in the River","description":"Waste from a great copper mine has choked the river downstream, and villagers are suing the company in a foreign court. The mine pays much of your budget.","options":[{"label":"Keep the mine running at full output","effects":{"copper":50,"gold":100,"controlPenalty":10}},{"label":"Force a settlement and cleanup fund","effects":{"gold":-200,"copper":-50,"controlBonus":8}}]},{"id":"ai_pacific_nan_madol_in_danger","ageId":"information","year":2016,"theme":"pacific","title":"Ruins in Danger","description":"The stone islets of Nan Madol are listed as World Heritage in danger. Mangroves clog the canals and the basalt walls are slipping into the sea.","options":[{"label":"Fund foreign experts to clear the canals","effects":{"gold":-100,"techPoints":20}},{"label":"Leave the site to the local chiefs","effects":{"controlBonus":5}}]},{"id":"ai_pacific_compact_renegotiation","ageId":"information","year":2003,"theme":"pacific","title":"The Compact Comes Due","description":"The free association compact with the United States is up for renewal. Washington offers years of grants, but wants close oversight of how every dollar is spent.","options":[{"label":"Sign and accept the oversight","effects":{"gold":200,"controlPenalty":8}},{"label":"Hold out for better terms","effects":{"gold":-50,"controlBonus":6}}]},{"id":"ai_pacific_marine_relocation","ageId":"information","year":2006,"theme":"pacific","title":"The Marines Are Coming","description":"Thousands of Marines will move to the island from Okinawa. The base brings money and jobs, but it needs ancestral land and old village sites.","options":[{"label":"Welcome the buildup","effects":{"gold":200,"defenseBonus":0.1,"controlPenalty":10}},{"label":"Demand the ancestral lands back first","effects":{"controlBonus":8}}]},{"id":"ai_pacific_typhoon_strikes_guam","ageId":"information","year":2023,"theme":"pacific","title":"The Typhoon Passes Over","description":"A super typhoon has torn through the island, snapping power poles and cutting water to most homes. Crews can patch the old grid fast or rebuild it stronger.","options":[{"label":"Rebuild with buried, hardened lines","effects":{"gold":-180,"techPoints":30,"controlPenalty":4}},{"label":"Patch everything as fast as possible","effects":{"gold":-60,"hr":-30}}]},{"id":"ai_pacific_parliament_seized","ageId":"information","year":2000,"theme":"pacific","title":"Gunmen in Parliament","description":"Armed men hold the prime minister and his cabinet hostage inside parliament. The chiefs are divided, and the army waits to see which way you lean.","options":[{"label":"Let the army take control","effects":{"militaryStrengthBonus":0.1}},{"label":"Demand a return to the constitution","effects":{"controlPenalty":10}}]},{"id":"ai_pacific_rising_tide_mussau","ageId":"information","year":2015,"theme":"pacific","title":"The Sea Comes Inland","description":"King tides now wash over the low shores where the first potters once lived, salting the gardens and wells. Elders refuse to leave their ancestors behind.","options":[{"label":"Build a seawall along the shore","effects":{"gold":-150,"defenseBonus":0.05}},{"label":"Move the village to higher ground","effects":{"gold":-60,"hr":-40,"controlPenalty":6}}]},{"id":"ai_americas_pyramid_of_the_sun","ageId":"classical","year":200,"theme":"americas","title":"Raising the Pyramid","description":"Your architects propose piling millions of baskets of earth and stone into a vast pyramid along the great avenue, a work that would take a generation of labor.","options":[{"label":"Summon every district to build","effects":{"hr":-60,"controlBonus":10}},{"label":"Build modestly and keep farmers in fields","effects":{"gold":60,"controlPenalty":4}}]},{"id":"ai_americas_entrada_at_mutal","ageId":"classical","year":378,"theme":"americas","title":"The Arrival at Mutal","description":"Your general Siyaj K'ak' stands ready to march on the Maya city of Mutal. Its king could be replaced by a lord loyal to you.","options":[{"label":"Send the warriors and crown your own","effects":{"hr":-50,"militaryStrengthBonus":40}},{"label":"Offer obsidian trade and marriage instead","effects":{"gold":-60}}]},{"id":"ai_americas_conquest_slabs","ageId":"classical","year":-200,"theme":"americas","title":"Stones of Conquest","description":"Your priests wish to carve the names of subdued valley towns onto slabs set in a new building on the mountaintop, for all visitors to read.","options":[{"label":"Carve every conquered name","effects":{"gold":-50,"controlBonus":8}},{"label":"Honor the towns as allies instead","effects":{"controlPenalty":5}}]},{"id":"ai_americas_marked_adobe","ageId":"classical","year":300,"theme":"americas","title":"Bricks by the Million","description":"Each lineage owes adobe bricks for the great huaca and stamps them with its own mark. Some lineages now fall short of their quota.","options":[{"label":"Punish the lagging lineages","effects":{"controlBonus":6,"hr":-30}},{"label":"Accept copper ornaments instead of bricks","effects":{"copper":40}}]},{"id":"ai_americas_obsidian_from_the_west","ageId":"classical","year":100,"theme":"americas","title":"Obsidian from the West","description":"Traders bring word of black glass from mountains far to the west. Fetching it means long journeys, but it would grace your burial mounds.","options":[{"label":"Send a trading party west","effects":{"gold":-70,"techPoints":15}},{"label":"Trade only in Great Lakes copper","effects":{"copper":50}}]},{"id":"ai_americas_gila_canals","ageId":"classical","year":300,"theme":"americas","title":"Digging from the Gila","description":"Elders propose a longer canal from the Gila River to water new fields, but digging it would pull hands from the harvest.","options":[{"label":"Dig the new canal","effects":{"hr":-40,"gold":80}},{"label":"Repair the old canals only","effects":{"controlBonus":4,"techPoints":-10}}]},{"id":"ai_americas_raised_fields","ageId":"classical","year":400,"theme":"americas","title":"Fields Above the Frost","description":"Farmers near the lake show how raised beds between water channels shield crops from frost. Building them widely would need labor gangs from every ayllu.","options":[{"label":"Order raised fields across the shore","effects":{"hr":-50,"gold":70,"techPoints":20}},{"label":"Let each village decide","effects":{"controlPenalty":3,"gold":20}}]},{"id":"ai_americas_mounds_above_flood","ageId":"classical","year":450,"theme":"americas","title":"Mounds Above the Flood","description":"The rainy season floods ever more of the island. Your people could raise great earthen mounds for homes and burials, but the work is endless.","options":[{"label":"Raise new mounds for the villages","effects":{"hr":-40,"defenseBonus":0.1}},{"label":"Move villages to higher ground","effects":{"controlPenalty":6,"gold":30}}]},{"id":"ai_westafrica_portuguese_envoys_kabasa","ageId":"gunpowder","year":1560,"theme":"westafrica","title":"Envoys From Portugal","description":"Paulo Dias de Novais has reached your court with priests and gifts, asking for trade and the right to preach. Your rival Kongo already deals with Lisbon.","options":[{"label":"Welcome them and seek their guns","effects":{"iron":40,"controlPenalty":6}},{"label":"Detain the envoys as hostages","effects":{"gold":60}}]},{"id":"ai_westafrica_imbangala_war_bands","ageId":"gunpowder","year":1618,"theme":"westafrica","title":"The Imbangala Offer","description":"Fierce Imbangala war bands camp near Kabasa, offering their spears to whoever pays most. The Portuguese at Luanda are bidding too.","options":[{"label":"Hire them before Luanda does","effects":{"gold":-120,"militaryStrengthBonus":0.1,"controlPenalty":5}},{"label":"Fortify the capital instead","effects":{"hr":-40,"defenseBonus":0.1}}]},{"id":"ai_westafrica_kasanje_gun_caravan","ageId":"gunpowder","year":1750,"theme":"westafrica","title":"Guns From Kasanje","description":"Caravans from Kasanje reach Musumba bearing muskets, cloth and gunpowder. They want ivory and captives in return, and your tributary chiefs want a share.","options":[{"label":"Monopolize the trade at court","effects":{"gold":100,"controlPenalty":8}},{"label":"Let chiefs trade for themselves","effects":{"iron":50,"controlBonus":6,"gold":-40}}]},{"id":"ai_westafrica_nyamwezi_traders_arrive","ageId":"gunpowder","year":1856,"theme":"westafrica","title":"Traders From the East","description":"Nyamwezi caravans led by men like Msiri push into Luba lands with guns, hungry for copper and ivory. Some already meddle in Katanga's chiefdoms.","options":[{"label":"Trade copper for their muskets","effects":{"copper":-50,"militaryStrengthBonus":0.08}},{"label":"Close the routes to them","effects":{"gold":-60,"defenseBonus":0.08}}]},{"id":"ai_westafrica_asante_tribute_demand","ageId":"gunpowder","year":1722,"theme":"westafrica","title":"Asante Demands Tribute","description":"The rising Asante under Opoku Ware demand that Bono Manso submit and pay tribute in gold. Refusal means war with the strongest army in the forest.","options":[{"label":"Submit and pay the gold","effects":{"gold":-150,"controlPenalty":10}},{"label":"Refuse and raise the levies","effects":{"hr":-90,"defenseBonus":0.1}}]},{"id":"ai_westafrica_gold_for_muskets","ageId":"gunpowder","year":1650,"theme":"westafrica","title":"Gold for Muskets","description":"Dyula merchants and coastal brokers say the Dutch at Elmina now sell muskets freely. Your gold fields could buy many, if you send the gold south.","options":[{"label":"Send gold to the coast","effects":{"gold":-100,"militaryStrengthBonus":0.1}},{"label":"Keep trading north with Dyula","effects":{"gold":80,"techPoints":15}}]},{"id":"ai_westafrica_oyo_refugees_modakeke","ageId":"gunpowder","year":1835,"theme":"westafrica","title":"Refugees From Oyo","description":"With Old Oyo collapsing, thousands of Oyo refugees seek shelter beside Ile-Ife. They bring hands and warriors, but your people resent the strangers.","options":[{"label":"Settle them in their own quarter","effects":{"hr":60,"controlPenalty":10}},{"label":"Take only the skilled craftsmen","effects":{"hr":25,"techPoints":20}}]},{"id":"ai_westafrica_zazzau_slave_raids","ageId":"gunpowder","year":1810,"theme":"westafrica","title":"Raiders From Zazzau","description":"After the Sokoto jihad, horsemen of the new Zazzau emirate raid south for captives. They offer peace if your villages pay yearly tribute.","options":[{"label":"Retreat to fortified hilltops","effects":{"gold":-50,"defenseBonus":0.1}},{"label":"Pay the yearly tribute","effects":{"gold":-100,"hr":-30}}]},{"id":"ai_monsoon_eel_channels","ageId":"stone","year":-4600,"theme":"monsoon","title":"Channels in the Lava","description":"The lava flows near Budj Bim hold wetlands full of short-finned eels. Your people could cut stone channels and weirs to trap them, but the work is long.","options":[{"label":"Cut new channels through the basalt","effects":{"hr":-25,"gold":60,"controlBonus":5}},{"label":"Fish the wetlands as your mothers did","effects":{"gold":20,"techPoints":-5}}]},{"id":"ai_monsoon_smoked_eel_trade","ageId":"stone","year":-3000,"theme":"monsoon","title":"Smoke in the Trees","description":"The autumn run fills every trap, more than the clans can eat. Smoked in hollow trees, the eels could travel far to neighbours who want them.","options":[{"label":"Smoke the surplus and trade it away","effects":{"gold":50,"hr":-10}},{"label":"Feast the clans and gather them close","effects":{"gold":-20,"controlBonus":8}}]},{"id":"ai_monsoon_rising_sea","ageId":"stone","year":-4000,"theme":"monsoon","title":"The Sea Comes Inland","description":"The warm age has raised the sea above any memory, and salt water creeps over the low plains where your camps once stood.","options":[{"label":"Move the camps to higher ground","effects":{"gold":-30,"defenseBonus":0.05}},{"label":"Stay and harvest the new mangrove shore","effects":{"gold":40,"controlPenalty":5}}]},{"id":"ai_monsoon_rice_from_north","ageId":"stone","year":-2200,"theme":"monsoon","title":"Rice From the North","description":"Strangers coming down the rivers plant rice in flooded fields and raise pigs. Your foragers watch them clear the forest your people have always hunted.","options":[{"label":"Learn their fields and their rice","effects":{"techPoints":15,"gold":-30}},{"label":"Trade game and shells for their grain","effects":{"gold":30,"controlPenalty":3}},{"label":"Drive them from your hunting grounds","effects":{"militaryStrengthBonus":10,"hr":-20}}]},{"id":"ai_monsoon_outrigger_landing","ageId":"stone","year":-2200,"theme":"monsoon","title":"Canoes From the North","description":"Outrigger canoes arrive on the Luzon shore carrying families, red-slipped pots and a new tongue. They ask to settle beside your fishing camps.","options":[{"label":"Welcome them and share the bay","effects":{"hr":25,"techPoints":10,"controlPenalty":5}},{"label":"Let them land only to trade","effects":{"gold":30}}]},{"id":"ai_monsoon_shell_middens","ageId":"stone","year":-4500,"theme":"monsoon","title":"Mountains of Shells","description":"Your coastal camps have eaten clams for generations, and the shell heaps now rise like hills. The elders bury the dead within them, but the beds grow thin.","options":[{"label":"Move upriver to new shellfish beds","effects":{"gold":-20,"hr":15,"controlPenalty":4}},{"label":"Stay by the ancestors and hunt more","effects":{"controlBonus":6,"gold":-30}}]},{"id":"ai_monsoon_polished_adzes","ageId":"stone","year":-2050,"theme":"monsoon","title":"The Polished Adze","description":"Craftsmen at Phong Chau grind stone adzes smooth and carve fine rings of soft stone. Villages up and down the river want them.","options":[{"label":"Send the best stone to the toolmakers","effects":{"techPoints":15,"militaryStrengthBonus":5,"gold":-30}},{"label":"Carve rings and ornaments for trade","effects":{"gold":50,"techPoints":-5}}]},{"id":"ai_monsoon_sumatran_foragers","ageId":"stone","year":-4800,"theme":"monsoon","title":"Pebble Tools by the Strait","description":"Your bands on the Sumatran coast live on shellfish and forest game, chipping river pebbles into tools. Some urge moving inland where the forest is richer.","options":[{"label":"Follow the rivers into the forest","effects":{"hr":20,"gold":-20,"controlPenalty":4}},{"label":"Hold the coast and its shell beds","effects":{"gold":30,"defenseBonus":0.05,"hr":-10}}]},{"id":"ai_steppe_botai_horse_milk","ageId":"stone","year":-3500,"theme":"steppe","title":"Mares at the Pen","description":"Your hunters have penned wild horses beside their pit houses, and some women now milk the mares into clay pots.","options":[{"label":"Keep the herds penned for milk and meat","effects":{"gold":-30,"hr":25}},{"label":"Hunt them as before, freely","effects":{"gold":40,"techPoints":-5}},{"label":"Break a few to carry riders","effects":{"gold":-50,"militaryStrengthBonus":20}}]},{"id":"ai_steppe_kurgan_wagons","ageId":"stone","year":-3000,"theme":"steppe","title":"Mounds and Wagons","description":"Your herders roll heavy ox wagons across the open steppe and heap great earth mounds over their chiefs.","options":[{"label":"Raise a grand kurgan for the dead chief","effects":{"gold":-60,"controlBonus":10}},{"label":"Send the wagons farther with the herds","effects":{"hr":30,"controlPenalty":6}}]},{"id":"ai_steppe_murghab_canals","ageId":"stone","year":-2200,"theme":"steppe","title":"Water from the Murghab","description":"The river delta feeding your walled town is shifting, and the canals that water its fields silt up each season.","options":[{"label":"Dig new canals with every hand","effects":{"gold":-80,"hr":-15,"defenseBonus":0.05}},{"label":"Move fields to the new channel","effects":{"gold":30,"controlPenalty":5}}]},{"id":"ai_steppe_sarazm_turquoise","ageId":"stone","year":-3200,"theme":"steppe","title":"Turquoise and Copper","description":"Your village on the Zeravshan sits between the mountain mines and the farmers of the south, who pay well for turquoise and copper.","options":[{"label":"Work the mines for southern traders","effects":{"copper":50,"hr":-10}},{"label":"Trade only for goods you need","effects":{"gold":-20}}]},{"id":"ai_steppe_delta_fishers","ageId":"stone","year":-4500,"theme":"steppe","title":"Fishers of the Delta","description":"Your people live by fishing and hunting in the reed marshes of the Amu Darya delta, while neighbors to the south sow grain.","options":[{"label":"Learn to sow grain like the south","effects":{"techPoints":15,"gold":-30}},{"label":"Keep to the reeds and the nets","effects":{"gold":30,"techPoints":-5}}]},{"id":"ai_steppe_altai_newcomers","ageId":"stone","year":-2900,"theme":"steppe","title":"Strangers with Cattle","description":"Herders from the far west have crossed into the Altai valleys with cattle, sheep and copper tools, settling the pastures your hunters roam.","options":[{"label":"Welcome them and learn their herding","effects":{"hr":20,"controlPenalty":5}},{"label":"Drive them from the best valleys","effects":{"militaryStrengthBonus":10,"hr":-20}}]},{"id":"ai_steppe_spoked_chariots","ageId":"stone","year":-2050,"theme":"steppe","title":"Furnaces and Chariots","description":"Every house in your ringed fort has its own copper furnace, and your smiths now build light carts on spoked wheels.","options":[{"label":"Smelt copper for fighting chariots","effects":{"copper":-50,"militaryStrengthBonus":25}},{"label":"Trade the copper to distant herders","effects":{"gold":70}},{"label":"Strengthen the ring walls instead","effects":{"gold":-40,"defenseBonus":0.1}}]},{"id":"ai_steppe_millet_highlands","ageId":"stone","year":-3000,"theme":"steppe","title":"Millet on the Plateau","description":"Farmers from the eastern lowlands have brought millet up into the high river valleys, where your people have only hunted and gathered.","options":[{"label":"Clear terraces for the new crop","effects":{"gold":-40,"hr":20}},{"label":"Trade game and hides for their grain","effects":{"gold":25,"controlPenalty":3}}]},{"id":"ai_mesopotamia_looters_at_the_tell","ageId":"information","year":2014,"theme":"mesopotamia","title":"Looters at the Tell","description":"War has emptied the countryside, and night diggers now riddle the ancient palace mound with pits, selling what they find to dealers abroad.","options":[{"label":"Send armed guards to the ruins","effects":{"gold":-100,"hr":-30,"controlBonus":5}},{"label":"Tax the dealers and look away","effects":{"gold":70,"controlPenalty":5}}]},{"id":"ai_mesopotamia_guard_the_museum","ageId":"information","year":2003,"theme":"mesopotamia","title":"Mobs at the Museum","description":"The old regime has fallen and crowds roam the streets. Looters gather at the museum doors while others eye the oil ministry. You can protect only one.","options":[{"label":"Post troops at the museum","effects":{"hr":-40,"controlBonus":5}},{"label":"Secure the oil ministry first","effects":{"oil":50,"controlPenalty":8}}]},{"id":"ai_mesopotamia_oil_for_food","ageId":"information","year":1996,"theme":"mesopotamia","title":"Oil for Food","description":"Sanctions have hollowed out your markets and hospitals. Foreign powers offer to let you sell oil again, but only under their inspectors and their accounts.","options":[{"label":"Accept foreign oversight of sales","effects":{"gold":150,"controlPenalty":5}},{"label":"Refuse and smuggle oil overland","effects":{"oil":-40,"gold":60}}]},{"id":"ai_mesopotamia_centrifuge_bargain","ageId":"information","year":2015,"theme":"mesopotamia","title":"The Centrifuge Bargain","description":"After years of sanctions, the great powers offer relief if you dismantle most of your enrichment halls and open them to inspectors.","options":[{"label":"Sign the deal and lift sanctions","effects":{"gold":180,"techPoints":-20}},{"label":"Keep the centrifuges spinning","effects":{"techPoints":60,"gold":-150,"defenseBonus":0.05}}]},{"id":"ai_mesopotamia_fort_and_reclamation","ageId":"information","year":2005,"theme":"mesopotamia","title":"Towers Before the Fort","description":"The old fort is named a world heritage site, yet developers want to fill the shallow sea before it with land for towers and marinas.","options":[{"label":"Protect the coastline around the fort","effects":{"gold":-100}},{"label":"Approve the land reclamation","effects":{"gold":200,"controlPenalty":4}}]},{"id":"ai_mesopotamia_island_banking_hub","ageId":"modern","year":1975,"theme":"mesopotamia","title":"An Island of Banks","description":"Your oil wells are running thin. Bankers propose turning the island into the Gulf's financial harbor, with light rules and foreign capital pouring in.","options":[{"label":"Open the gates to foreign capital","effects":{"gold":200,"controlPenalty":6}},{"label":"Train local engineers and diversify slowly","effects":{"gold":-80,"techPoints":40}}]},{"id":"ai_mesopotamia_euphrates_drought","ageId":"information","year":2008,"theme":"mesopotamia","title":"The River Runs Low","description":"A third dry year withers the Euphrates valley, and dams upstream hold back what rain there was. Farmers are abandoning their fields for the cities.","options":[{"label":"Fund deep wells and feed subsidies","effects":{"gold":-150,"controlBonus":6}},{"label":"Let the farmers move to the cities","effects":{"gold":40,"hr":30,"controlPenalty":10}}]},{"id":"ai_mesopotamia_reflood_the_marshes","ageId":"information","year":2003,"theme":"mesopotamia","title":"Breaking the Dikes","description":"The southern marshes were drained a decade ago and their people scattered. Now villagers are tearing open the dikes, asking you to let the water return.","options":[{"label":"Help them reflood the marshes","effects":{"gold":-100,"hr":40,"controlBonus":5}},{"label":"Keep the drained land for farms and oil","effects":{"oil":50,"gold":40,"controlPenalty":7}}]},{"id":"ai_monsoon_bronze_drums","ageId":"classical","year":-400,"theme":"monsoon","title":"Drums of Bronze","description":"Your smiths at Phong Chau can cast great bronze drums, their faces ringed with birds and boatmen, to be beaten at rites and buried with chiefs.","options":[{"label":"Melt copper stores for sacred drums","effects":{"copper":-50,"controlBonus":8}},{"label":"Cast spearheads and axes instead","effects":{"copper":-40,"militaryStrengthBonus":25,"controlPenalty":4}}]},{"id":"ai_monsoon_kaundinya_marriage","ageId":"classical","year":60,"theme":"monsoon","title":"The Brahmin from the Sea","description":"A foreign Brahmin named Kaundinya has landed with a ship and armed men. He offers to wed you and rule beside you, bringing Indian rites and letters.","options":[{"label":"Marry him and adopt his rites","effects":{"techPoints":40,"controlPenalty":8}},{"label":"Drive his ship back to sea","effects":{"hr":-30,"controlBonus":5}}]},{"id":"ai_monsoon_lam_ap_revolt","ageId":"classical","year":192,"theme":"monsoon","title":"Revolt Against Han","description":"In Xianglin, at the empire's southern edge, Khu Lien urges your people to kill the Han magistrate and proclaim a kingdom of their own.","options":[{"label":"Rise and seize the commandery","effects":{"hr":-50,"controlBonus":12,"militaryStrengthBonus":20}},{"label":"Pay tribute and bide your time","effects":{"gold":-80}}]},{"id":"ai_monsoon_pyu_monks","ageId":"classical","year":450,"theme":"monsoon","title":"Monks at the Gate","description":"Buddhist monks arrive at Sri Ksetra carrying Pali texts and ask for land to build monasteries within your great brick walls.","options":[{"label":"Grant land and fund stupas","effects":{"gold":-90,"techPoints":35,"controlBonus":5}},{"label":"Keep faith with the old spirits","effects":{"gold":40}}]},{"id":"ai_monsoon_gomati_canal","ageId":"classical","year":450,"theme":"monsoon","title":"The Gomati Canal","description":"Your engineers propose digging a canal over eleven kilometers long to tame the floods near the coast, a work of thousands of laborers in twenty-one days.","options":[{"label":"Dig it and gift cows to Brahmins","effects":{"gold":-120,"hr":-30,"controlBonus":10}},{"label":"Leave the river to the monsoon","effects":{"gold":30,"controlPenalty":6}}]},{"id":"ai_monsoon_yupa_pillars","ageId":"classical","year":400,"theme":"monsoon","title":"Pillars of Sacrifice","description":"Brahmins at Muara Kaman ask you to raise stone yupa posts recording your gift of twenty thousand cows, proclaiming your lineage in Sanskrit.","options":[{"label":"Give the cows and raise the stones","effects":{"gold":-150,"controlBonus":10,"techPoints":15}},{"label":"Make a modest offering","effects":{"gold":-30,"controlPenalty":4}}]},{"id":"ai_monsoon_wu_envoys","ageId":"classical","year":245,"theme":"monsoon","title":"Envoys from Wu","description":"Chinese envoys Kang Tai and Zhu Ying reach your capital, recording your customs and urging your people to dress in the manner of their court.","options":[{"label":"Host them and send tribute","effects":{"gold":-80}},{"label":"Adopt their customs of dress","effects":{"techPoints":20,"controlPenalty":5}},{"label":"Receive them coolly","effects":{"controlBonus":5}}]},{"id":"ai_levant_short_alphabet","ageId":"bronze","year":-1400,"theme":"levant","title":"A Short Alphabet","description":"Scribes in Ugarit press a cuneiform alphabet of only thirty signs into clay, far easier to learn than the Akkadian your diplomats still use.","options":[{"label":"Teach the new script to merchants","effects":{"gold":-50,"techPoints":30}},{"label":"Keep Akkadian for all royal business","effects":{"techPoints":-10}}]},{"id":"ai_levant_assyrian_merchant_quarter","ageId":"bronze","year":-1900,"theme":"levant","title":"Merchants from Assur","description":"Donkey caravans from Assur bring tin and textiles to the merchant quarter below your mound, asking for fixed tolls and royal protection.","options":[{"label":"Grant a charter for a share of goods","effects":{"gold":80,"controlPenalty":5}},{"label":"Tax every caravan heavily","effects":{"gold":120}},{"label":"Close the market to foreigners","effects":{"gold":-60,"controlBonus":5}}]},{"id":"ai_levant_fall_of_hattusa","ageId":"bronze","year":-1750,"theme":"levant","title":"The Fall of Hattusa","description":"Your troops have taken Hattusa by night after a long siege. It could become a second seat of power, or a warning to every rival.","options":[{"label":"Raze it and curse the ground","effects":{"controlBonus":10,"gold":-40}},{"label":"Garrison and rebuild the city","effects":{"gold":-100,"defenseBonus":0.08}}]},{"id":"ai_levant_ships_off_the_coast","ageId":"bronze","year":-1185,"theme":"levant","title":"Ships off the Coast","description":"Enemy ships burn your coastal villages while your troops serve the Hittite king in Hatti and your fleet is far away in Lukka.","options":[{"label":"Recall the army from Hittite service","effects":{"defenseBonus":0.1}},{"label":"Shut the gates and wait","effects":{"hr":-30,"defenseBonus":0.05}},{"label":"Send to Alashiya for help","effects":{"gold":-50}}]},{"id":"ai_levant_copper_for_the_gulf","ageId":"bronze","year":-1950,"theme":"levant","title":"Copper for the Gulf","description":"Ships from the cities of Mesopotamia wait at your harbors for smelted copper, but the mountain furnaces are devouring scrub and timber.","options":[{"label":"Fire every furnace for export","effects":{"copper":50,"controlPenalty":5}},{"label":"Limit smelting to spare the wood","effects":{"copper":40,"gold":-30,"controlBonus":3}}]},{"id":"ai_levant_taming_wadi_floods","ageId":"bronze","year":-850,"theme":"levant","title":"Taming the Wadi Floods","description":"Seasonal floods roar down the wadi. Your engineers propose stone sluices and earthen dams to spread the water over the fields of Maryab.","options":[{"label":"Build the dams with conscripted labor","effects":{"hr":-40,"controlBonus":8}},{"label":"Let the clans keep their own channels","effects":{"gold":30,"controlPenalty":5}}]},{"id":"ai_levant_fortress_on_the_rock","ageId":"bronze","year":-840,"theme":"levant","title":"A Fortress on the Rock","description":"Assyrian armies have marched to the shores of Lake Van. Your builders could raise massive limestone walls on the great rock of Tushpa.","options":[{"label":"Quarry the stone and build","effects":{"gold":-120,"defenseBonus":0.1}},{"label":"Send tribute to Assyria","effects":{"gold":-60,"controlPenalty":5}}]},{"id":"ai_levant_gold_in_the_rivers","ageId":"bronze","year":-1200,"theme":"levant","title":"Gold in the Rivers","description":"Mountain streams carry gold dust, which your people catch on sheepskins laid in the current. The bronze smiths want the same hands at their forges.","options":[{"label":"Send workers to the rivers","effects":{"gold":90,"techPoints":-10}},{"label":"Keep them at the forges","effects":{"techPoints":20,"gold":-20}}]},{"id":"ai_mesopotamia_mari_canal","ageId":"stone","year":-2900,"theme":"mesopotamia","title":"The Canal of Mari","description":"Your builders raise Mari beside the Euphrates and propose a long canal to bring river boats to its gates and water to its fields.","options":[{"label":"Dig the canal with every hand","effects":{"hr":-30,"gold":-60,"controlBonus":8}},{"label":"Trust the river as it flows","effects":{"gold":30}}]},{"id":"ai_mesopotamia_river_tolls","ageId":"stone","year":-2500,"theme":"mesopotamia","title":"Tolls on the Euphrates","description":"Boats laden with timber and stone pass your people on their way to the cities of the south. Your elders ask whether to tax them.","options":[{"label":"Take a share of every cargo","effects":{"gold":80}},{"label":"Let them pass and win friends","effects":{"gold":-20}}]},{"id":"ai_mesopotamia_kingship_kish","ageId":"stone","year":-2700,"theme":"mesopotamia","title":"Kingship Descends to Kish","description":"The priests proclaim that the gods have granted kingship to Kish. Other cities now look to your lugal as judge in their quarrels.","options":[{"label":"Judge the quarrels of the cities","effects":{"controlPenalty":5}},{"label":"Guard Kish and ignore its rivals","effects":{"defenseBonus":0.08}}]},{"id":"ai_mesopotamia_standing_army","ageId":"stone","year":-2300,"theme":"mesopotamia","title":"Men Who Eat Daily","description":"Your inscriptions boast of thousands of soldiers who eat bread before you every day. Feeding them drains the granaries of Akkad.","options":[{"label":"Keep the standing army fed","effects":{"gold":-100,"militaryStrengthBonus":30}},{"label":"Send half home to the fields","effects":{"gold":40,"controlPenalty":4}}]},{"id":"ai_mesopotamia_proto_elamite_tablets","ageId":"stone","year":-3100,"theme":"mesopotamia","title":"Signs on Clay","description":"Your scribes begin marking clay tablets with their own signs, unlike those of the lowland cities, to count grain, sheep and workers.","options":[{"label":"Train scribes in our own signs","effects":{"techPoints":20,"gold":-40}},{"label":"Borrow the lowland way of writing","effects":{"controlPenalty":5}}]},{"id":"ai_mesopotamia_highland_copper","ageId":"stone","year":-3000,"theme":"mesopotamia","title":"Copper of the Highlands","description":"Traders from the plains climb to Anshan seeking copper and fine stone from your mountains, offering grain and cloth in return.","options":[{"label":"Open the mines to the traders","effects":{"copper":50,"gold":50,"controlPenalty":4}},{"label":"Keep the metal for our own smiths","effects":{"copper":40}}]},{"id":"ai_mesopotamia_burial_mounds","ageId":"stone","year":-2200,"theme":"mesopotamia","title":"Fields of Mounds","description":"Your people raise thousands of stone burial mounds across the island. The work honors the dead but takes men from the boats and palms.","options":[{"label":"Raise great mounds for the elders","effects":{"hr":-20,"controlBonus":10}},{"label":"Keep burials small and simple","effects":{"hr":15,"controlPenalty":3}}]},{"id":"ai_mesopotamia_ships_of_magan","ageId":"stone","year":-2300,"theme":"mesopotamia","title":"Ships from Magan","description":"Boats bring copper from Magan and carnelian from Meluhha to your harbor, bound for the quays of Akkad. Merchants ask you to guard the sea lanes.","options":[{"label":"Arm boats to guard the gulf","effects":{"gold":-50,"defenseBonus":0.1}},{"label":"Tax the cargo and stay neutral","effects":{"gold":70,"copper":20}}]},{"id":"ai_monsoon_lac_lords_tribute","ageId":"bronze","year":-1500,"theme":"monsoon","title":"The Lac Lords' Tribute","description":"The Lac lords who govern the flooded rice fields of the Red River valley question why their harvest should feed your court at all.","options":[{"label":"Demand a fixed share of every harvest","effects":{"gold":90,"controlPenalty":8}},{"label":"Grant them bronze gifts for their loyalty","effects":{"copper":-40,"controlBonus":7}}]},{"id":"ai_monsoon_sandstone_molds","ageId":"bronze","year":-1300,"theme":"monsoon","title":"Molds of Sandstone","description":"Casters at Phong Chau now pour bronze axes and spearheads into reusable stone molds, but the copper and tin they need must come from distant hills.","options":[{"label":"Send porters to the upland mines","effects":{"gold":-70,"copper":50,"techPoints":15}},{"label":"Recast old tools instead","effects":{"techPoints":10}}]},{"id":"ai_monsoon_mekong_copper_hills","ageId":"bronze","year":-1400,"theme":"monsoon","title":"Copper by the Mekong","description":"Villagers report green-stained rock in the hills near the Mekong, where outsiders already dig and smelt copper in small clay furnaces.","options":[{"label":"Claim the hills by force","effects":{"hr":-50,"copper":50}},{"label":"Trade rice and salt for ingots","effects":{"gold":-60,"copper":40}}]},{"id":"ai_monsoon_green_stone_north","ageId":"bronze","year":-1900,"theme":"monsoon","title":"Green Stone from the North","description":"Outrigger canoes arrive from the islands to the north carrying polished green nephrite, and their crews want a place to settle on your shore.","options":[{"label":"Welcome them and their stone","effects":{"techPoints":20,"controlPenalty":6}},{"label":"Trade at the beach, then send them on","effects":{"gold":40}}]},{"id":"ai_monsoon_burial_jars","ageId":"bronze","year":-900,"theme":"monsoon","title":"Jars for the Dead","description":"Coastal families now bury their dead in great clay jars on the dunes, and the potters demand more firewood and labor than the villages can spare.","options":[{"label":"Fund the potters from your stores","effects":{"gold":-60,"controlBonus":8}},{"label":"Limit jars to chiefly families","effects":{"gold":30,"controlPenalty":6}}]},{"id":"ai_monsoon_failed_rains","ageId":"bronze","year":-1500,"theme":"monsoon","title":"The Rains Fail","description":"The monsoon has barely touched the dry plains this year, and the millet in the fields is withering before it can head.","options":[{"label":"Open the granaries to all","effects":{"gold":-90,"controlBonus":6}},{"label":"Raid the wetter river valleys","effects":{"hr":-40,"gold":50}}]},{"id":"ai_monsoon_mounds_above_flood","ageId":"bronze","year":-1200,"theme":"monsoon","title":"Mounds Above the Flood","description":"Each monsoon the lower Mekong swells across the plain, and elders argue whether to raise the villages on earthen mounds or move to higher ground.","options":[{"label":"Raise mounds and ring them with ditches","effects":{"hr":-30,"gold":-40,"defenseBonus":0.1}},{"label":"Move the villages to the hills","effects":{"gold":-50,"controlPenalty":5}}]},{"id":"ai_maghreb_oil_strike","ageId":"modern","year":1959,"theme":"maghreb","title":"Oil Beneath the Sand","description":"Foreign drillers strike oil deep in your desert. Concessions could make you rich overnight, but the companies demand generous terms.","options":[{"label":"Grant concessions to foreign firms","effects":{"oil":50,"gold":100,"controlPenalty":8}},{"label":"Found a national oil company","effects":{"gold":-120,"oil":50,"techPoints":20}}]},{"id":"ai_maghreb_italian_landing","ageId":"modern","year":1911,"theme":"maghreb","title":"Italian Warships Offshore","description":"An Italian fleet lands troops on the coast and claims the land as a colony. The tribes of the Green Mountain look to you.","options":[{"label":"Arm the tribes for guerrilla war","effects":{"hr":-60,"gold":-80,"defenseBonus":0.1}},{"label":"Negotiate terms with Rome","effects":{"gold":60,"controlPenalty":10}}]},{"id":"ai_maghreb_night_uprising","ageId":"modern","year":1954,"theme":"maghreb","title":"Revolt in the Mountains","description":"Nationalist fighters strike across the country in a single night, and the colonial army answers with mass arrests.","options":[{"label":"Back the uprising openly","effects":{"hr":-100,"militaryStrengthBonus":80}},{"label":"Seek reforms through the assembly","effects":{"controlPenalty":6}}]},{"id":"ai_maghreb_rif_republic","ageId":"modern","year":1921,"theme":"maghreb","title":"Republic of the Rif","description":"Rif tribesmen rout a Spanish army at Annual, and their leaders talk of a republic of their own in the mountains.","options":[{"label":"Ally with the Rif rebels","effects":{"militaryStrengthBonus":60,"gold":-50,"controlPenalty":8}},{"label":"Side with France and Spain","effects":{"gold":80,"hr":-50,"controlBonus":6}}]},{"id":"ai_maghreb_iron_railway","ageId":"modern","year":1963,"theme":"maghreb","title":"Iron Mountain Railway","description":"A foreign consortium opens an iron mine in the northern desert and a long railway to the sea. They want a long lease and few taxes.","options":[{"label":"Lease the mine to the consortium","effects":{"iron":50,"gold":60,"controlPenalty":5}},{"label":"Demand a state share","effects":{"iron":50,"gold":100}}]},{"id":"ai_maghreb_sahel_drought","ageId":"modern","year":1973,"theme":"maghreb","title":"The Rains Fail","description":"Years of drought kill the herds and drive the nomads into the towns, where markets and wells are overwhelmed.","options":[{"label":"Appeal for foreign food aid","effects":{"gold":80,"controlPenalty":5}},{"label":"Open the state granaries","effects":{"gold":-120,"controlBonus":8}}]},{"id":"ai_maghreb_mosque_rebuilt","ageId":"modern","year":1907,"theme":"maghreb","title":"Rebuilding the Great Mosque","description":"Masons propose raising a new mud mosque on the ruins of the old one, while colonial officials eye the gathering crowds warily.","options":[{"label":"Fund the rebuilding","effects":{"gold":-100,"controlBonus":10}},{"label":"Spend the money on roads","effects":{"gold":-60,"techPoints":15,"controlPenalty":4}}]},{"id":"ai_maghreb_pickup_war","ageId":"modern","year":1987,"theme":"maghreb","title":"The Pickup Truck War","description":"Your fighters in light trucks with mounted guns face a northern neighbor's armored columns across the desert.","options":[{"label":"Strike fast across the dunes","effects":{"militaryStrengthBonus":100,"hr":-60}},{"label":"Seek French air cover","effects":{"gold":-50,"defenseBonus":0.1}}]},{"id":"ai_korea_dolmen_capstone","ageId":"bronze","year":-1200,"theme":"korea","title":"The Great Capstone","description":"Your elders want a dolmen for the late chieftain, crowned with a capstone so heavy that hundreds must haul it on log rollers.","options":[{"label":"Quarry and haul the giant stone","effects":{"gold":-70,"hr":-20,"controlBonus":8}},{"label":"Bury him in a modest stone cist","effects":{"gold":30,"controlPenalty":4}}]},{"id":"ai_korea_flooded_paddies","ageId":"bronze","year":-900,"theme":"korea","title":"Water for the Rice","description":"Farmers in the Geum River valley have learned to grow rice in flooded, banked fields, but the channels and dikes need the labor of every household.","options":[{"label":"Order the digging of paddies and channels","effects":{"gold":-80,"techPoints":20,"controlBonus":4}},{"label":"Keep to the old millet fields","effects":{"gold":40,"controlPenalty":3}}]},{"id":"ai_korea_lute_daggers","ageId":"bronze","year":-850,"theme":"korea","title":"The Lute-Shaped Daggers","description":"Casters in Wanggeom-seong pour bronze into stone molds, making the lute-shaped daggers prized from Liaodong to the southern valleys.","options":[{"label":"Arm your warriors with them","effects":{"copper":-50,"militaryStrengthBonus":0.1}},{"label":"Send them as gifts to rival chiefs","effects":{"copper":-40}}]},{"id":"ai_korea_village_moat","ageId":"bronze","year":-900,"theme":"korea","title":"Ditch and Palisade","description":"Raids on granaries grow bolder each harvest, and the people of Buyeo ask for a deep ditch and a wooden palisade around the village.","options":[{"label":"Dig the ditch and raise the stakes","effects":{"hr":-30,"defenseBonus":0.1}},{"label":"Flee to the hilltop when raiders come","effects":{"gold":20,"controlPenalty":5}}]},{"id":"ai_korea_heavenly_rite","ageId":"bronze","year":-1100,"theme":"korea","title":"Son of Heaven","description":"Shamans proclaim that your line descends from the sky, and they demand a great rite with bronze ornaments and offerings to prove it.","options":[{"label":"Hold the grand sky rite","effects":{"gold":-60,"copper":-20,"controlBonus":10}},{"label":"Refuse the costly ceremony","effects":{"gold":40,"controlPenalty":6}}]},{"id":"ai_korea_northern_horses","ageId":"bronze","year":-1000,"theme":"korea","title":"Horses from the North","description":"Herders from the northern grasslands arrive with sturdy horses and ask for grain, though your scouts warn they also eye your fields.","options":[{"label":"Trade grain for horses","effects":{"gold":-90,"militaryStrengthBonus":0.1}},{"label":"Turn them back at the river","effects":{"defenseBonus":0.05}}]},{"id":"ai_korea_tin_shortage","ageId":"bronze","year":-850,"theme":"korea","title":"The Missing Tin","description":"Your bronze casters have copper but almost no tin, and the nearest sources lie far to the north beyond hostile chiefdoms.","options":[{"label":"Send a trading party north","effects":{"gold":-80,"copper":50}},{"label":"Melt down old ornaments and blades","effects":{"copper":30,"controlPenalty":4}}]},{"id":"ai_korea_crowded_longhouses","ageId":"bronze","year":-1100,"theme":"korea","title":"Crowded Longhouses","description":"Your great longhouses now shelter several families each, and the young ask to leave and clear new land in the hills.","options":[{"label":"Send families to found new hamlets","effects":{"hr":-25,"gold":70}},{"label":"Build more longhouses at home","effects":{"gold":-30,"controlBonus":5}}]},{"id":"ai_eastafrica_almeida_at_kilwa","ageId":"gunpowder","year":1505,"theme":"eastafrica","title":"Portuguese Sails Off Kilwa","description":"Francisco de Almeida's fleet anchors before Kilwa and demands tribute to the king of Portugal. His cannon outrange anything on your walls.","options":[{"label":"Pay tribute and keep the city","effects":{"gold":-120,"controlPenalty":5}},{"label":"Refuse and man the walls","effects":{"hr":-80,"defenseBonus":0.1}},{"label":"Abandon the town to the mainland","effects":{"gold":-60,"controlPenalty":10}}]},{"id":"ai_eastafrica_mir_ali_bey_alliance","ageId":"gunpowder","year":1585,"theme":"eastafrica","title":"The Ottoman Corsair Arrives","description":"The Ottoman captain Mir Ali Bey sails down the Somali coast promising to drive out the Portuguese. He asks your ports for men, ships and supplies.","options":[{"label":"Join the Ottoman cause","effects":{"hr":-60,"militaryStrengthBonus":0.1}},{"label":"Trade with him, but stay neutral","effects":{"gold":70}}]},{"id":"ai_eastafrica_mavura_vassal_treaty","ageId":"gunpowder","year":1629,"theme":"eastafrica","title":"A Crown Bought With Muskets","description":"A claimant backed by Portuguese guns offers to take the Mutapa throne and open the gold fields to their traders. Refusing means war with the prazo lords.","options":[{"label":"Accept Portuguese overlordship","effects":{"gold":-100,"controlPenalty":10,"militaryStrengthBonus":0.05}},{"label":"Rally the chiefs against them","effects":{"hr":-90,"controlBonus":8}}]},{"id":"ai_eastafrica_radama_british_treaty","ageId":"gunpowder","year":1817,"theme":"eastafrica","title":"Muskets for the Slave Trade","description":"British envoys from Mauritius offer arms, gold and instructors if you end the export of slaves from your lands. The slave traders at court are furious.","options":[{"label":"Sign and modernize the army","effects":{"militaryStrengthBonus":0.1,"techPoints":30,"controlPenalty":6}},{"label":"Keep the trade and its profits","effects":{"gold":120}}]},{"id":"ai_eastafrica_cape_fort_cattle","ageId":"gunpowder","year":1652,"theme":"eastafrica","title":"Strangers Build a Fort","description":"Dutch company men raise a fort at Table Bay and want your cattle for copper and tobacco. You know their language better than anyone on the shore.","options":[{"label":"Serve as their interpreter and broker","effects":{"copper":50,"controlPenalty":5}},{"label":"Drive the herds away from them","effects":{"gold":-40,"controlBonus":6}}]},{"id":"ai_eastafrica_general_commando","ageId":"gunpowder","year":1774,"theme":"eastafrica","title":"The Commando Rides North","description":"Colonial farmers raise a great armed commando to clear your bands from the hunting grounds of the northern frontier. Your arrows cannot match their guns.","options":[{"label":"Retreat into the dry interior","effects":{"hr":-40,"controlPenalty":8}},{"label":"Raid their herds in the mountains","effects":{"hr":-70,"militaryStrengthBonus":0.05,"defenseBonus":0.05}}]},{"id":"ai_eastafrica_baker_at_masindi","ageId":"gunpowder","year":1872,"theme":"eastafrica","title":"Baker Raises a Flag","description":"The Egyptian Khedive's agent Samuel Baker plants a flag at Masindi and declares your kingdom annexed. His soldiers are few, but well armed.","options":[{"label":"Burn the capital and attack","effects":{"gold":-80,"hr":-50,"controlBonus":10}},{"label":"Negotiate and wait him out","effects":{"controlPenalty":6}}]},{"id":"ai_eastafrica_failing_furrows","ageId":"gunpowder","year":1700,"theme":"eastafrica","title":"The Furrows Run Dry","description":"The streams feeding your stone irrigation channels are shrinking, and terraces lie bare. Herders from the plains eye the empty fields.","options":[{"label":"Rebuild the channels higher upslope","effects":{"gold":-90,"hr":-30,"techPoints":25}},{"label":"Turn to cattle and trade with herders","effects":{"gold":50,"controlPenalty":7}}]},{"id":"ai_steppe_fall_of_astrakhan","ageId":"gunpowder","year":1556,"theme":"steppe","title":"Muscovy Takes the Volga","description":"Tsar Ivan's armies have seized the old khanate at the Volga mouth, and Russian boats now control the river trade your merchants depend on.","options":[{"label":"Accept Russian tolls and keep trading","effects":{"gold":60,"controlPenalty":8}},{"label":"Seek Crimean and Ottoman support","effects":{"gold":-80,"militaryStrengthBonus":0.05}}]},{"id":"ai_japan_rice_riots","ageId":"modern","year":1918,"theme":"japan","title":"Rice Riots Spread","description":"Rice prices have doubled while merchants hoard grain, and fishermen's wives have started riots that now spread from town to town.","options":[{"label":"Open state rice stores at low prices","effects":{"gold":-120,"controlBonus":8}},{"label":"Send troops to restore order","effects":{"controlPenalty":10}}]},{"id":"ai_japan_great_earthquake","ageId":"modern","year":1923,"theme":"japan","title":"The Great Earthquake","description":"A massive earthquake has struck at midday, and cooking fires have turned the wooden quarters of your city into a firestorm.","options":[{"label":"Rebuild with wide, fireproof avenues","effects":{"gold":-250,"defenseBonus":0.1}},{"label":"Rebuild quickly along the old streets","effects":{"gold":-80,"controlPenalty":5}}]},{"id":"ai_japan_northern_famine","ageId":"modern","year":1934,"theme":"japan","title":"Cold Summer Famine","description":"A cold summer has ruined the northern rice harvest, and starving farm families are selling their daughters to brokers from the cities.","options":[{"label":"Fund relief work and food shipments","effects":{"gold":-150,"controlBonus":10}},{"label":"Enlist the hungry sons into the army","effects":{"militaryStrengthBonus":60,"controlPenalty":8}}]},{"id":"ai_japan_war_loans","ageId":"modern","year":1904,"theme":"japan","title":"Paying for War","description":"War with Russia has begun, and your treasury cannot sustain it for more than a few months without new money.","options":[{"label":"Borrow from London and New York bankers","effects":{"gold":200}},{"label":"Raise heavy war taxes at home","effects":{"gold":150,"controlPenalty":12}}]},{"id":"ai_japan_zaibatsu_breakup","ageId":"modern","year":1947,"theme":"japan","title":"Breaking the Zaibatsu","description":"The occupation authorities demand that you dissolve the great family conglomerates that built your war economy.","options":[{"label":"Dissolve them as demanded","effects":{"gold":-100}},{"label":"Quietly let them regroup under banks","effects":{"gold":120}}]},{"id":"ai_japan_bullet_train_north","ageId":"modern","year":1971,"theme":"japan","title":"The Bullet Train North","description":"Engineers propose extending the high speed line through the northern mountains to your city, at enormous cost in tunnels and viaducts.","options":[{"label":"Fund the line through the mountains","effects":{"gold":-300,"techPoints":80,"controlBonus":5}},{"label":"Postpone it for another decade","effects":{"gold":50,"controlPenalty":6}}]},{"id":"ai_japan_oil_shock","ageId":"modern","year":1973,"theme":"japan","title":"The Oil Shock","description":"Arab producers have cut oil exports, and your factories, which run almost entirely on imported oil, face sudden shortages and soaring prices.","options":[{"label":"Buy oil at any price","effects":{"oil":50,"gold":-250}},{"label":"Ration energy and invest in efficiency","effects":{"techPoints":40,"gold":-100,"controlPenalty":5}}]},{"id":"ai_japan_poisoned_bay","ageId":"modern","year":1968,"theme":"japan","title":"The Poisoned Bay","description":"Doctors confirm that mercury from a chemical plant has poisoned fishing villages for years, and victims now protest outside the company gates.","options":[{"label":"Close the outflow and compensate victims","effects":{"gold":-200,"controlBonus":8}},{"label":"Protect the company and dispute the findings","effects":{"gold":80,"controlPenalty":10}}]},{"id":"ai_maghreb_great_man_made_river","ageId":"information","year":1996,"theme":"maghreb","title":"Water Under the Sand","description":"Engineers can pump the fossil aquifers beneath the Fezzan north to the coast through giant pipes. The water is ancient and will not return once drawn.","options":[{"label":"Build the pipeline to the coast","effects":{"gold":-280,"controlBonus":10,"techPoints":40}},{"label":"Keep the water for desert farms","effects":{"gold":-90,"hr":40,"controlPenalty":5}},{"label":"Leave the aquifers untouched","effects":{"gold":60,"controlPenalty":8}}]},{"id":"ai_eastafrica_pirates_off_the_horn","ageId":"information","year":2009,"theme":"eastafrica","title":"Pirates Off the Horn","description":"Fishermen turned raiders seize freighters off your coast and hold their crews for ransom. Foreign navies gather, and your own ports quietly profit from the trade.","options":[{"label":"Fund coastal patrols and courts","effects":{"gold":-150,"defenseBonus":0.1}},{"label":"Bargain with the clan elders","effects":{"gold":-60,"controlPenalty":5}},{"label":"Tax the ransom money quietly","effects":{"gold":120}}]},{"id":"ai_americas_caral_land_traffickers","ageId":"information","year":2020,"theme":"americas","title":"Squatters by the Pyramids","description":"Land traffickers fence off fields around Caral's ancient pyramids, and the archaeologists who guard the site receive death threats.","options":[{"label":"Send police to clear the land","effects":{"gold":-80,"hr":-20,"controlBonus":6}},{"label":"Buy out the claims quietly","effects":{"gold":-150,"techPoints":20}},{"label":"Leave it to the slow courts","effects":{"gold":30,"controlPenalty":5}}]},{"id":"ai_americas_lithium_salt_flats","ageId":"information","year":2023,"theme":"americas","title":"The White Gold Contract","description":"Foreign firms bid to extract lithium from your salt flats, offering capital and know-how you lack but demanding a large share of the brine.","options":[{"label":"Sign with the foreign consortium","effects":{"gold":200,"controlPenalty":6}},{"label":"Keep extraction in state hands","effects":{"gold":-150,"techPoints":40,"controlBonus":5}}]},{"id":"ai_americas_supermarket_near_pyramids","ageId":"information","year":2004,"theme":"americas","title":"A Supermarket by the Pyramids","description":"A retail chain has a permit to build a store within sight of the Pyramid of the Sun, and protesters camp at the gates.","options":[{"label":"Let construction proceed","effects":{"gold":120,"controlPenalty":5}},{"label":"Revoke the permit","effects":{"gold":-80,"controlBonus":4}}]},{"id":"ai_americas_earthquake_leogane","ageId":"information","year":2010,"theme":"americas","title":"The Earth Splits","description":"A magnitude 7 earthquake levels towns around Jaragua. Aid planes jam the only airport while survivors dig through rubble by hand.","options":[{"label":"Let foreign troops run the relief","effects":{"controlPenalty":8}},{"label":"Direct relief through your own officials","effects":{"gold":-200,"hr":-40,"controlBonus":5}}]},{"id":"ai_americas_after_hurricane_maria","ageId":"information","year":2017,"theme":"americas","title":"After Hurricane Maria","description":"A Category 5 storm has torn the roofs off nearly every house on the island. You can rebuild as before, or pay to rebuild against the next storm.","options":[{"label":"Rebuild to resilient standards","effects":{"gold":-250,"defenseBonus":0.1}},{"label":"Restore homes quickly and cheaply","effects":{"gold":-80,"controlBonus":4}},{"label":"Sell passports to fund recovery","effects":{"gold":200}}]},{"id":"ai_americas_nunavut_civil_service","ageId":"information","year":1999,"theme":"americas","title":"A Territory of Our Own","description":"Nunavut is born and its new government must staff the ministries, but few trained civil servants speak Inuktitut.","options":[{"label":"Require Inuktitut in the civil service","effects":{"controlBonus":8,"techPoints":-20}},{"label":"Hire experienced officials from the south","effects":{"gold":-100,"techPoints":30,"controlPenalty":5}}]},{"id":"ai_americas_chaco_drilling_buffer","ageId":"information","year":2023,"theme":"americas","title":"Drilling Near the Great Houses","description":"Oil and gas firms seek leases near Chaco's great houses. Pueblo leaders demand a ten-mile buffer, while some Navajo allottees want the royalties.","options":[{"label":"Impose the ten-mile buffer","effects":{"oil":-40,"gold":-50,"controlBonus":4}},{"label":"Approve the leases","effects":{"oil":50,"gold":60,"controlPenalty":6}}]},{"id":"ai_americas_chips_in_the_desert","ageId":"information","year":2021,"theme":"americas","title":"Chips in the Desert","description":"A chipmaker offers to build a giant fab near your desert city, if you guarantee water from a river already running dry.","options":[{"label":"Grant the water rights","effects":{"techPoints":80,"gold":-100,"controlPenalty":4}},{"label":"Protect farms and homes first","effects":{"controlBonus":4}}]},{"id":"ai_israelite_jebusite_stronghold","ageId":"bronze","year":-1000,"theme":"israelite","title":"The Jebusite Stronghold","description":"The Jebusites mock you from their hilltop fortress, boasting that even the blind and lame could hold it. Your men whisper of a water shaft leading inside.","options":[{"label":"Send fighters up the water shaft","effects":{"hr":-40,"controlBonus":8}},{"label":"Besiege and offer the Jebusites terms","effects":{"gold":-80}}]},{"id":"ai_israelite_ark_to_jerusalem","ageId":"bronze","year":-995,"theme":"israelite","title":"Bringing Up the Ark","description":"The Ark of the Covenant rests in a village house at Kiriath-jearim. Bringing it to your new capital would bind the tribes to Jerusalem, but the priests fear mishandling it.","options":[{"label":"Lead a grand procession with music","effects":{"gold":-90,"controlBonus":10}},{"label":"Leave the Ark where it rests","effects":{"gold":30,"controlPenalty":5}}]},{"id":"ai_israelite_cedars_of_tyre","ageId":"bronze","year":-980,"theme":"israelite","title":"Cedars from Tyre","description":"Hiram, king of Tyre, offers cedar logs, carpenters and masons to build you a palace. Phoenician craftsmen are the finest anywhere, but their friendship comes at a price in grain and oil.","options":[{"label":"Accept and pay Tyre in produce","effects":{"gold":-100,"techPoints":10}},{"label":"Build with local stone and labor","effects":{"hr":-30,"gold":-30}}]},{"id":"ai_israelite_philistine_smiths","ageId":"bronze","year":-1010,"theme":"israelite","title":"No Smith in Israel","description":"The Philistines guard the secret of ironworking, and your farmers must go down to them to sharpen every plowshare and axe. Your soldiers fight with few iron weapons.","options":[{"label":"Keep paying Philistine smiths","effects":{"gold":-60,"iron":30}},{"label":"Train Israelite smiths at great cost","effects":{"gold":-100,"techPoints":20,"iron":15}},{"label":"Raid the Philistine forges","effects":{"hr":-40,"iron":50,"militaryStrengthBonus":0.05}}]},{"id":"ai_israelite_royal_census","ageId":"bronze","year":-975,"theme":"israelite","title":"Counting the People","description":"You wish to count every fighting man from Dan to Beersheba, but your commander Joab objects. A census would make taxes and levies precise, yet prophets warn that numbering the people invites disaster.","options":[{"label":"Order the count to proceed","effects":{"gold":120,"controlPenalty":8}},{"label":"Halt the census and offer sacrifices","effects":{"gold":-50,"controlBonus":5}}]},{"id":"ai_israelite_absalom_revolt","ageId":"bronze","year":-980,"theme":"israelite","title":"Absalom at Hebron","description":"Your son Absalom has stolen the hearts of the people at the city gate and been proclaimed king in Hebron. His army marches on Jerusalem.","options":[{"label":"Abandon Jerusalem and regroup beyond Jordan","effects":{"controlPenalty":10,"hr":40}},{"label":"Hold the city walls against him","effects":{"hr":-60,"defenseBonus":0.1}}]},{"id":"ai_israelite_stepped_stone_terraces","ageId":"bronze","year":-990,"theme":"israelite","title":"Filling the Millo","description":"The steep eastern slope of the City of David crumbles with every winter rain. Masons propose massive stone terraces to support new buildings and strengthen the citadel.","options":[{"label":"Build the great stepped terraces","effects":{"gold":-120,"defenseBonus":0.1}},{"label":"Patch the old retaining walls","effects":{"gold":-40,"controlPenalty":3}}]},{"id":"ai_israelite_arabah_copper","ageId":"bronze","year":-960,"theme":"israelite","title":"Furnaces of the Arabah","description":"Smelting furnaces burn day and night in the copper valleys of the Arabah, south of the Dead Sea. Whoever controls them controls the bronze of the region.","options":[{"label":"Garrison the mines in Edom","effects":{"hr":-50,"copper":50,"controlPenalty":4}},{"label":"Buy ingots from the desert smelters","effects":{"gold":-70,"copper":40}}]},{"id":"ai_israelite_masoretic_codex","ageId":"kingdoms","year":930,"theme":"israelite","title":"The Masoretes' Great Codex","description":"The scribes of Tiberias have fixed every vowel and accent of scripture in one master codex. They ask you to fund faithful copies for every synagogue.","options":[{"label":"Pay for copies in every province","effects":{"gold":-90,"techPoints":30}},{"label":"Keep one codex, guarded in Jerusalem","effects":{"gold":-20,"controlBonus":5,"techPoints":5}}]},{"id":"ai_israelite_persian_march","ageId":"kingdoms","year":614,"theme":"israelite","title":"The Persians at the Gates","description":"A Sasanian army sweeps toward Jerusalem, and Jews of Galilee are marching with it against Byzantine rule. You must choose a side before the walls are breached.","options":[{"label":"Join the Persian advance","effects":{"hr":-50,"militaryStrengthBonus":0.08}},{"label":"Stay loyal to the emperor","effects":{"hr":-30,"defenseBonus":0.06,"controlPenalty":10}}]},{"id":"ai_israelite_karaite_schism","ageId":"kingdoms","year":767,"theme":"israelite","title":"Scripture Alone","description":"Followers of Anan ben David reject the oral law of the rabbis and read only the written Torah. The academies demand you silence them.","options":[{"label":"Back the rabbinic academies","effects":{"controlBonus":8}},{"label":"Tolerate both schools","effects":{"controlPenalty":6,"techPoints":15}}]},{"id":"ai_israelite_radhanite_charters","ageId":"kingdoms","year":870,"theme":"israelite","title":"The Radhanite Road","description":"Jewish merchants who trade from the Frankish lands to China seek your protection for their caravans and ships. Their routes bring silk, spices and envy.","options":[{"label":"Grant them broad charters","effects":{"gold":120,"controlPenalty":5}},{"label":"Tax every cargo heavily","effects":{"gold":60}}]},{"id":"ai_israelite_crusader_siege","ageId":"kingdoms","year":1099,"theme":"israelite","title":"The Franks Besiege Jerusalem","description":"A crusader army has encamped beneath the walls with siege towers. Defenders and scholars alike wait for your command.","options":[{"label":"Man the walls to the last","effects":{"hr":-80,"defenseBonus":0.1}},{"label":"Send scrolls and families to Egypt","effects":{"hr":-20,"controlPenalty":12,"techPoints":10}}]},{"id":"ai_israelite_resettle_jerusalem","ageId":"kingdoms","year":1192,"theme":"israelite","title":"Return to the City","description":"After Saladin retook Jerusalem, Jews were again permitted to settle there. Families from Ashkelon and the Maghreb await your help to make the journey.","options":[{"label":"Fund settlers and their homes","effects":{"hr":-40,"gold":-50,"controlBonus":10}},{"label":"Fund only a synagogue and yeshiva","effects":{"gold":-70}}]},{"id":"ai_israelite_maimonidean_controversy","ageId":"kingdoms","year":1232,"theme":"israelite","title":"The Guide for the Perplexed","description":"Maimonides' philosophy divides your sages: some call it the crown of wisdom, others heresy fit for burning. Both camps want your verdict.","options":[{"label":"Endorse the study of philosophy","effects":{"techPoints":35,"controlPenalty":8}},{"label":"Ban the books in your lands","effects":{"controlBonus":6,"techPoints":-20}}]},{"id":"ai_israelite_sephardi_exiles","ageId":"kingdoms","year":1492,"theme":"israelite","title":"Exiles From Sepharad","description":"Spain has expelled its Jews, and ships crowded with scholars, physicians and penniless families seek a harbor. Taking them in will strain your treasury.","options":[{"label":"Welcome all who come","effects":{"hr":60,"gold":-110,"techPoints":20}},{"label":"Admit only the skilled and wealthy","effects":{"gold":40,"hr":20}}]},{"id":"ai_levant_hejaz_railway_station","ageId":"modern","year":1908,"theme":"levant","title":"The Railway Reaches Hegra","description":"The Hejaz Railway now runs past the rock-cut tombs of Hegra, bringing pilgrims, soldiers and trade. The Bedouin who once earned their living guarding the caravans watch it with anger.","options":[{"label":"Build a fortified depot and garrison","effects":{"gold":-120,"controlBonus":8}},{"label":"Pay the tribes to protect the line","effects":{"gold":-60,"controlPenalty":5}}]},{"id":"ai_levant_van_under_siege","ageId":"modern","year":1915,"theme":"levant","title":"Van Under Siege","description":"As war engulfs the eastern front, the Armenian quarter beneath the old citadel of Van barricades itself against Ottoman forces. The city's fate will echo far beyond its walls.","options":[{"label":"Arm the city's defenders","effects":{"gold":-80,"defenseBonus":0.1,"controlPenalty":6}},{"label":"Send troops to break the siege","effects":{"hr":-60,"militaryStrengthBonus":40}},{"label":"Stay out of the fighting","effects":{"controlPenalty":10}}]},{"id":"ai_levant_ras_shamra_tablets","ageId":"modern","year":1929,"theme":"levant","title":"Tablets at Ras Shamra","description":"A farmer's plow struck a buried tomb, and now a French mission is unearthing clay tablets in an unknown alphabet. Scholars across the world are clamoring for access.","options":[{"label":"Fund the excavation and keep the finds","effects":{"gold":-60,"techPoints":30}},{"label":"Let the foreign mission take the tablets","effects":{"gold":40,"controlPenalty":4}}]},{"id":"ai_levant_midas_mound_opened","ageId":"modern","year":1957,"theme":"levant","title":"Opening the Great Tumulus","description":"American archaeologists have tunneled into the great burial mound at Gordion and found an intact wooden tomb chamber. Tourists, scholars and looters all take notice.","options":[{"label":"Build a museum at the site","effects":{"gold":-90,"techPoints":25,"controlBonus":4}},{"label":"Sell exhibition rights abroad","effects":{"gold":100,"controlPenalty":5}}]},{"id":"ai_levant_sinop_listening_post","ageId":"modern","year":1955,"theme":"levant","title":"Ears on the Black Sea","description":"Your allies ask to build a listening station on the Sinop headland to track Soviet missile tests across the sea. The rent is generous, but Moscow is watching.","options":[{"label":"Lease the headland to your allies","effects":{"gold":120,"defenseBonus":0.08,"controlPenalty":5}},{"label":"Refuse foreign troops on your soil","effects":{"controlBonus":6}}]},{"id":"ai_levant_gabala_radar","ageId":"modern","year":1985,"theme":"levant","title":"The Radar at Gabala","description":"Engineers from Moscow are raising a vast early-warning radar in the hills near Gabala. It promises jobs and protection, but locals fear for their orchards and their health.","options":[{"label":"Welcome the station and its workers","effects":{"defenseBonus":0.1,"techPoints":20,"controlPenalty":5}},{"label":"Demand compensation for the villages","effects":{"gold":80}}]},{"id":"ai_levant_marib_oil_strike","ageId":"modern","year":1984,"theme":"levant","title":"Oil Beneath Marib","description":"An American company has struck oil in the desert basin near Marib, where the old Sabaean capital lies in ruins. The tribes of the region expect their share.","options":[{"label":"Grant the foreign company a concession","effects":{"oil":50,"controlPenalty":6}},{"label":"Share revenues with the local tribes","effects":{"oil":50,"gold":-50,"controlBonus":7}}]},{"id":"ai_levant_marib_dam_rebuilt","ageId":"modern","year":1984,"theme":"levant","title":"A New Marib Dam","description":"A Gulf ruler offers to fund a modern dam near the ruins of the ancient Marib Dam, reviving the fields of old Saba. His generosity will come with expectations.","options":[{"label":"Accept the gift and its strings","effects":{"hr":40,"gold":60}},{"label":"Build it from your own treasury","effects":{"gold":-200,"hr":40,"controlBonus":8}}]},{"id":"ai_westafrica_terracotta_workshops","ageId":"bronze","year":-900,"theme":"westafrica","title":"The Clay Sculptors","description":"Potters in Nok are shaping large clay figures with elaborate hair and pierced eyes. Elders want them for shrines and graves, but firing them consumes much fuel and labor.","options":[{"label":"Fund the workshops for the shrines","effects":{"gold":-70,"controlBonus":6}},{"label":"Keep the potters making household wares","effects":{"gold":40,"controlPenalty":3}}]},{"id":"ai_westafrica_pearl_millet_fields","ageId":"bronze","year":-1700,"theme":"westafrica","title":"The New Grain","description":"Villagers at the forest edge have begun sowing pearl millet beside their yams and oil palms. Clearing more land feeds more mouths, but it strips the woods your hunters rely on.","options":[{"label":"Clear the woodland for millet","effects":{"hr":40,"controlPenalty":4}},{"label":"Keep the old balance of forest and field","effects":{"gold":-30,"controlBonus":4}}]},{"id":"ai_westafrica_first_furnaces","ageId":"bronze","year":-850,"theme":"westafrica","title":"Fire That Melts Stone","description":"Smiths claim that red stone heated in clay furnaces yields a hard grey metal. The trials burn whole groves of charcoal and most attempts fail.","options":[{"label":"Give the smiths charcoal and laborers","effects":{"gold":-90,"iron":30,"techPoints":20}},{"label":"Forbid the waste of good timber","effects":{"gold":40,"techPoints":-10}}]},{"id":"ai_westafrica_forest_yam_clearing","ageId":"bronze","year":-1200,"theme":"westafrica","title":"The Sacred Grove","description":"Farmers at the forest edge want to burn a grove for new yam mounds. The priests say spirits dwell there and will turn against the village.","options":[{"label":"Let the farmers burn the grove","effects":{"hr":30,"controlPenalty":6}},{"label":"Declare the grove untouchable","effects":{"gold":-40,"controlBonus":7}}]},{"id":"ai_westafrica_lake_fishing_dispute","ageId":"bronze","year":-1100,"theme":"westafrica","title":"Quarrel Over the Marshes","description":"Two clans claim the same fish-rich marshes. Each brings dried fish as tribute and asks you to drive the other off.","options":[{"label":"Split the waters between them","effects":{"gold":-30}},{"label":"Favor the stronger clan","effects":{"militaryStrengthBonus":0.05,"controlPenalty":5}},{"label":"Claim the marshes for yourself","effects":{"gold":60,"controlPenalty":8}}]},{"id":"ai_westafrica_savanna_drought","ageId":"bronze","year":-1300,"theme":"westafrica","title":"The Rains Fail","description":"For a second year the rains have come late and the river runs thin. Families are leaving for the forest valleys, taking their strength with them.","options":[{"label":"Open the granaries to the villages","effects":{"gold":-80,"controlBonus":6}},{"label":"Let the families go to the valleys","effects":{"hr":-40,"gold":20}}]},{"id":"ai_westafrica_salt_traders","ageId":"bronze","year":-1000,"theme":"westafrica","title":"Salt From the Coast","description":"Traders arrive in your village with blocks of salt from the coastal pans. They want a fixed market and safe passage, and they ask a share of every exchange.","options":[{"label":"Grant a protected market","effects":{"gold":70,"controlPenalty":4}},{"label":"Tax each salt load heavily","effects":{"gold":100}},{"label":"Send your own carriers to the coast","effects":{"hr":-30,"gold":50,"defenseBonus":0.05}}]},{"id":"ai_westafrica_newcomers_from_north","ageId":"bronze","year":-1000,"theme":"westafrica","title":"Newcomers With Pots","description":"Bands of farmers speaking a related tongue arrive from the north, carrying pottery and yam cuttings. Your hunters fear for their grounds.","options":[{"label":"Welcome them and share land","effects":{"hr":40,"techPoints":10,"controlPenalty":5}},{"label":"Turn them back at the river","effects":{"militaryStrengthBonus":0.05}}]},{"id":"ai_mesopotamia_foothill_oil_strike","ageId":"modern","year":1908,"theme":"mesopotamia","title":"Oil in the Foothills","description":"After years of dry wells, a foreign drilling crew strikes a gusher in the hills of your southwest. They want a long concession to pump and ship it.","options":[{"label":"Grant the foreign concession","effects":{"gold":150,"controlPenalty":10}},{"label":"Fund your own drillers","effects":{"gold":-120,"oil":50,"techPoints":20}}]},{"id":"ai_mesopotamia_northern_gusher_pipeline","ageId":"modern","year":1927,"theme":"mesopotamia","title":"The Northern Gusher","description":"A well near the old fire pits of the north erupts, flooding the plain with crude for days. Investors offer to build a pipeline to the Mediterranean in exchange for a share.","options":[{"label":"Accept the foreign consortium","effects":{"gold":100,"oil":50}},{"label":"Build a smaller pipeline yourself","effects":{"gold":-150,"oil":50}}]},{"id":"ai_mesopotamia_first_gulf_oil","ageId":"modern","year":1932,"theme":"mesopotamia","title":"First Oil of the Gulf","description":"Drillers on your island hit oil beneath the central hill, the first find on the Arab shore of the Gulf. Your advisers argue over how fast to pump.","options":[{"label":"Pump fast and spend freely","effects":{"gold":200,"controlPenalty":6}},{"label":"Save revenue for schools and clinics","effects":{"gold":-50,"techPoints":40,"controlBonus":6}}]},{"id":"ai_mesopotamia_pearl_market_collapse","ageId":"modern","year":1934,"theme":"mesopotamia","title":"The Pearl Market Collapses","description":"Cheap cultured pearls from Japan and the world slump have crushed prices, and your pearling fleets sit idle with their divers deep in debt.","options":[{"label":"Subsidize the pearling fleets","effects":{"gold":-100,"controlBonus":5}},{"label":"Send divers to the oil fields","effects":{"hr":-20,"techPoints":30,"controlPenalty":5}}]},{"id":"ai_mesopotamia_statue_at_tell_hariri","ageId":"modern","year":1933,"theme":"mesopotamia","title":"A Statue in the Sand","description":"Tribesmen digging a grave on a mound by the Euphrates uncover an ancient headless statue. Foreign archaeologists ask for a permit to excavate the whole site.","options":[{"label":"Grant the foreign permit","effects":{"techPoints":20,"controlPenalty":5}},{"label":"Keep finds in a national museum","effects":{"gold":-60,"controlBonus":8}}]},{"id":"ai_mesopotamia_oil_nationalization","ageId":"modern","year":1951,"theme":"mesopotamia","title":"Whose Oil Is It","description":"Crowds and parliament demand that the foreign oil company be seized. Its government threatens a blockade of your exports if you dare.","options":[{"label":"Nationalize the oil industry","effects":{"oil":50,"gold":-150}},{"label":"Renegotiate a better royalty","effects":{"gold":80,"controlPenalty":10}}]},{"id":"ai_mesopotamia_euphrates_dam","ageId":"modern","year":1973,"theme":"mesopotamia","title":"Damming the Euphrates","description":"Soviet engineers are ready to close a great dam on the Euphrates, promising power and irrigation. The reservoir will drown dozens of villages and ancient mounds.","options":[{"label":"Close the dam and relocate villagers","effects":{"gold":-250,"techPoints":60,"controlPenalty":6}},{"label":"Delay to rescue the ancient sites","effects":{"gold":-80}}]},{"id":"ai_mesopotamia_war_over_shatt","ageId":"modern","year":1980,"theme":"mesopotamia","title":"War Over the Waterway","description":"Your neighbor across the shared river mouth is in revolutionary chaos, and your generals say one swift strike could seize the waterway and its oil province.","options":[{"label":"Launch the invasion","effects":{"gold":-300,"militaryStrengthBonus":300,"hr":-100}},{"label":"Seek a border settlement","effects":{"controlPenalty":8}}]},{"id":"ai_europe_knossos_excavation","ageId":"modern","year":1900,"theme":"europe","title":"The Mound at Knossos","description":"A British archaeologist has bought land over the Kephala mound and asks permission to dig for the palace of legend.","options":[{"label":"Grant the permit freely","effects":{"techPoints":40,"gold":-30}},{"label":"Demand that finds stay on Crete","effects":{"techPoints":25,"controlBonus":5}},{"label":"Refuse foreign diggers","effects":{"controlBonus":6,"techPoints":-10}}]},{"id":"ai_europe_numantia_dig","ageId":"modern","year":1905,"theme":"europe","title":"Who Digs Numantia","description":"A German scholar has begun uncovering the Roman siege camps around Numantia, and Spanish patriots demand the ruins be studied by Spaniards.","options":[{"label":"Let the foreign team continue","effects":{"techPoints":50,"controlPenalty":5}},{"label":"Fund a Spanish commission","effects":{"gold":-80,"techPoints":30,"controlBonus":5}}]},{"id":"ai_europe_maiden_castle_dig","ageId":"modern","year":1934,"theme":"europe","title":"Digging Through the Slump","description":"Archaeologists want to excavate the great ramparts of Maiden Castle, and hundreds of local men idled by the Depression are asking for the work.","options":[{"label":"Hire the unemployed as diggers","effects":{"gold":-50,"hr":20,"techPoints":20}},{"label":"Leave the earthworks to farmers","effects":{"gold":40,"controlPenalty":4}}]},{"id":"ai_europe_berlin_blockade","ageId":"modern","year":1948,"theme":"europe","title":"The City Cut Off","description":"Soviet forces have closed every road and rail line into West Berlin, leaving two million people with weeks of food and coal.","options":[{"label":"Back the allied airlift","effects":{"gold":-120}},{"label":"Accept Soviet terms for the city","effects":{"gold":40,"controlPenalty":10}}]},{"id":"ai_europe_budapest_uprising","ageId":"modern","year":1956,"theme":"europe","title":"Students in the Streets","description":"Students and workers have toppled a giant statue of Stalin and demand free elections and the withdrawal of Soviet troops.","options":[{"label":"Side with the reformers","effects":{"controlPenalty":15}},{"label":"Call in the tanks","effects":{"controlBonus":10,"hr":-30}}]},{"id":"ai_europe_north_sea_oil","ageId":"modern","year":1969,"theme":"europe","title":"Oil Off the Coast","description":"Drillers in the North Sea have struck a vast oil field, and foreign companies are crowding into the harbors of Rogaland.","options":[{"label":"Found a state oil company","effects":{"gold":-150,"oil":50}},{"label":"License the foreign firms","effects":{"gold":150,"oil":50,"controlPenalty":5}}]},{"id":"ai_europe_navan_quarry","ageId":"modern","year":1985,"theme":"europe","title":"The Quarry Advances","description":"A limestone quarry beside Emain Macha seeks to expand toward the ancient mound, and campaigners warn the royal site will be lost.","options":[{"label":"Approve the expansion","effects":{"gold":80,"controlPenalty":8}},{"label":"Halt the quarry and protect the site","effects":{"gold":-60,"controlBonus":6,"techPoints":10}}]},{"id":"ai_europe_chernobyl_reactor","ageId":"modern","year":1986,"theme":"europe","title":"Fire at the Reactor","description":"A reactor at Chernobyl has exploded, and a radioactive cloud drifts over villages and fields while officials wait for orders.","options":[{"label":"Evacuate widely and admit the truth","effects":{"gold":-200,"hr":-30}},{"label":"Downplay it and keep parades running","effects":{"controlPenalty":12,"hr":-60}}]},{"id":"ai_pacific_sweet_potato_arrives","ageId":"gunpowder","year":1650,"theme":"pacific","title":"The Sweet Potato Arrives","description":"A new tuber passed from valley to valley grows on cold, high slopes where taro fails. Your elders debate whether to remake the old gardens around it.","options":[{"label":"Plant mounded fields on every slope","effects":{"hr":60,"gold":-40}},{"label":"Keep the ancestral taro gardens","effects":{"controlBonus":5,"hr":-10}}]},{"id":"ai_pacific_great_pig_exchange","ageId":"gunpowder","year":1750,"theme":"pacific","title":"The Great Pig Exchange","description":"Neighboring clans expect you to host a ceremonial exchange of pigs and shells. Generosity buys alliances, but your herds are thin after a dry season.","options":[{"label":"Give lavishly before all the clans","effects":{"gold":-80}},{"label":"Hold back and keep the herds","effects":{"gold":40,"controlPenalty":5}}]},{"id":"ai_pacific_manila_galleon_stop","ageId":"gunpowder","year":1570,"theme":"pacific","title":"The Galleon Drops Anchor","description":"A great Spanish ship bound from Acapulco to Manila anchors offshore, its crew desperate for water and fresh food. They offer iron for provisions.","options":[{"label":"Trade food for iron","effects":{"iron":40,"controlPenalty":5}},{"label":"Keep canoes away from the strangers","effects":{"defenseBonus":0.05,"gold":-20}}]},{"id":"ai_pacific_mission_on_guam","ageId":"gunpowder","year":1671,"theme":"pacific","title":"Priests and Soldiers","description":"Spanish missionaries baptize children and preach against the old ways, guarded by soldiers. Some chiefs urge war, others see power in the new faith.","options":[{"label":"Accept the mission and its schools","effects":{"techPoints":30,"controlPenalty":8}},{"label":"Join the chiefs rising in arms","effects":{"militaryStrengthBonus":0.1,"hr":-40}}]},{"id":"ai_pacific_whalers_in_harbor","ageId":"gunpowder","year":1845,"theme":"pacific","title":"Whalers in the Harbor","description":"American whaling ships crowd your lagoon, paying in cloth, tools and tobacco for yams and water. Their sailors bring drink, quarrels and sickness ashore.","options":[{"label":"Provision every ship that comes","effects":{"gold":80,"hr":-30}},{"label":"Limit landings to one harbor","effects":{"gold":20,"controlBonus":5}},{"label":"Close the lagoon to whalers","effects":{"gold":-30,"defenseBonus":0.08}}]},{"id":"ai_pacific_labor_recruiters","ageId":"gunpowder","year":1883,"theme":"pacific","title":"The Labor Recruiters","description":"Recruiting ships seek young men for plantations in Queensland and Samoa, offering axes and rifles to their kin. Not all who leave return.","options":[{"label":"Let the young men sign on","effects":{"iron":50,"hr":-40}},{"label":"Drive the recruiting ships away","effects":{"defenseBonus":0.05}}]},{"id":"ai_pacific_shipwrecked_musketeers","ageId":"gunpowder","year":1808,"theme":"pacific","title":"Muskets from a Wreck","description":"Castaway sailors with muskets salvaged from a wrecked brig offer to fight for Bau. Firearms could crush your rivals, but the foreigners demand wives and honors.","options":[{"label":"Hire the musketeers for war","effects":{"militaryStrengthBonus":0.12,"gold":-60}},{"label":"Send them to a rival chief","effects":{}}]},{"id":"ai_pacific_cession_to_britain","ageId":"gunpowder","year":1874,"theme":"pacific","title":"The Offer of Cession","description":"Foreign debts, unruly settlers and rival chiefs strain your new kingdom. British envoys propose that you cede Fiji to their Queen in exchange for order.","options":[{"label":"Cede the islands to Britain","effects":{"gold":150,"controlPenalty":12}},{"label":"Keep the crown and the debts","effects":{"gold":-100,"controlBonus":8}}]},{"id":"ai_monsoon_strangers_seek_gold","ageId":"gunpowder","year":1521,"theme":"monsoon","title":"Strangers Seeking Gold","description":"Battered foreign ships have arrived, and their men stare at the gold ornaments your people wear. They offer iron blades and cloth for the metal.","options":[{"label":"Trade gold for their iron","effects":{"gold":-60,"iron":50}},{"label":"Feast them and send them away","effects":{"gold":-20}},{"label":"Hide the gold, refuse trade","effects":{"controlBonus":5}}]},{"id":"ai_monsoon_company_pepper_monopoly","ageId":"gunpowder","year":1659,"theme":"monsoon","title":"The Company Wants Pepper","description":"The Dutch East India Company demands sole right to buy your pepper at its own price. Its warships wait in the Musi River.","options":[{"label":"Grant the monopoly","effects":{"gold":80,"controlPenalty":10}},{"label":"Refuse and fortify the river","effects":{"gold":-100,"defenseBonus":0.1}}]},{"id":"ai_monsoon_march_on_batavia","ageId":"gunpowder","year":1628,"theme":"monsoon","title":"March on Batavia","description":"The Dutch fort at Batavia defies your claim over all Java. Your generals ask for a great army and rice barges to besiege it.","options":[{"label":"Send the army and barges","effects":{"hr":-90,"gold":-80,"militaryStrengthBonus":12}},{"label":"Tolerate the fort, tax its trade","effects":{"gold":60,"controlPenalty":6}}]},{"id":"ai_monsoon_hue_ends_panduranga","ageId":"gunpowder","year":1832,"theme":"monsoon","title":"Hue Ends the Autonomy","description":"The court at Hue has abolished the last Cham principality and sends mandarins to rule Panduranga directly. Many Cham speak of flight to Cambodia.","options":[{"label":"Submit and keep the temples","effects":{"gold":-50,"controlBonus":8}},{"label":"Lead the people to Cambodia","effects":{"hr":-60}},{"label":"Rise in revolt","effects":{"hr":-80,"militaryStrengthBonus":8,"controlPenalty":10}}]},{"id":"ai_monsoon_toungoo_at_the_gates","ageId":"gunpowder","year":1542,"theme":"monsoon","title":"Toungoo at the Gates","description":"The Toungoo king besieges Prome beside the old Pyu walls. Allies from Ava promise help, but their army is slow.","options":[{"label":"Hold the walls and wait","effects":{"gold":-70,"defenseBonus":0.1}},{"label":"Open the gates for terms","effects":{"gold":-40,"controlPenalty":8}}]},{"id":"ai_monsoon_restore_great_stupa","ageId":"gunpowder","year":1853,"theme":"monsoon","title":"Restore the Great Stupa","description":"The ancient stupa of Nakhon Pathom lies overgrown in the jungle. The king wishes to encase it in a vast new chedi, a work of many years.","options":[{"label":"Fund the great chedi","effects":{"gold":-130,"controlBonus":12}},{"label":"Clear and repair it modestly","effects":{"gold":-40,"controlBonus":4}}]},{"id":"ai_monsoon_settlers_at_eel_traps","ageId":"gunpowder","year":1842,"theme":"monsoon","title":"Sheep on the Eel Country","description":"Squatters have driven flocks onto the stone channels and eel traps your ancestors built. Young men want to raid the stations; elders fear the troopers.","options":[{"label":"Raid the stations' flocks","effects":{"hr":-40,"militaryStrengthBonus":8,"controlPenalty":6}},{"label":"Retreat to the stony rises","effects":{"defenseBonus":0.1,"gold":-30}},{"label":"Seek work and rations","effects":{"gold":30,"controlPenalty":10}}]},{"id":"ai_europe_phocaean_walls","ageId":"classical","year":-560,"theme":"europe","title":"Silver for the Phocaeans","description":"Greek traders from Phocaea refuse your offer to settle in your land. Fearing the Medes at home, they ask for silver to wall their own city instead.","options":[{"label":"Pay for their walls in silver","effects":{"gold":-120}},{"label":"Insist they settle along your river","effects":{"techPoints":25,"controlPenalty":5}},{"label":"Keep your silver at home","effects":{"gold":40}}]},{"id":"ai_europe_cimbri_at_noreia","ageId":"classical","year":-113,"theme":"europe","title":"Wanderers at Noreia","description":"A vast host of Cimbri wanders toward Noreia. Roman envoys order them away, while a Roman consul waits in the passes with his legions.","options":[{"label":"Trust Rome to fight for you","effects":{"controlPenalty":5}},{"label":"Pay the Cimbri to move on","effects":{"gold":-100,"hr":20}},{"label":"Arm the ironworkers and hold the walls","effects":{"iron":-50,"defenseBonus":0.1,"hr":-30}}]},{"id":"ai_europe_roman_envoys_piracy","ageId":"classical","year":-230,"theme":"europe","title":"Roman Envoys at Court","description":"Roman envoys demand that you stop Illyrian ships from plundering Italian merchants. Your captains call raiding their ancient right, and the younger envoy speaks to you insolently.","options":[{"label":"Curb only the royal fleet's raids","effects":{"gold":-40}},{"label":"Ban all raiding at sea","effects":{"gold":-100,"controlPenalty":8}},{"label":"Let the captains sail as they please","effects":{"gold":120}}]},{"id":"ai_europe_friend_of_rome","ageId":"classical","year":-140,"theme":"europe","title":"Friend of the Roman People","description":"You have trapped the consul Servilianus and his army in a gorge. He offers peace: your lands recognized and you named a friend of Rome, if his men may leave.","options":[{"label":"Accept and let the army go","effects":{}},{"label":"Destroy the trapped army","effects":{"militaryStrengthBonus":50,"hr":-40}}]},{"id":"ai_europe_siege_ring","ageId":"classical","year":-133,"theme":"europe","title":"The Ring Around Numantia","description":"Scipio has sealed Numantia inside walls, towers and camps. Hunger grows, and the council debates sending riders through the lines to beg the Arevaci towns for aid.","options":[{"label":"Send Retogenes's riders out by night","effects":{"hr":-10,"defenseBonus":0.05}},{"label":"Ration the grain and hold the walls","effects":{"gold":-60,"defenseBonus":0.1,"controlPenalty":6}},{"label":"Seek terms from Scipio","effects":{"controlPenalty":12,"hr":30}}]},{"id":"ai_europe_scorched_earth","ageId":"classical","year":-52,"theme":"europe","title":"Burn the Granaries","description":"To starve Caesar's legions, you would burn every Biturigan town and farm in their path. The Bituriges beg you to spare Avaricum, their finest city.","options":[{"label":"Burn them all, Avaricum too","effects":{"gold":-80,"militaryStrengthBonus":40,"controlPenalty":8}},{"label":"Spare Avaricum and defend it","effects":{"defenseBonus":0.08,"controlBonus":6}}]},{"id":"ai_europe_fugitive_caratacus","ageId":"classical","year":51,"theme":"europe","title":"A Fugitive King","description":"Caratacus, beaten by the Romans in the west, seeks shelter among your Brigantes. Rome watches to see whether its client queen keeps faith.","options":[{"label":"Chain him and hand him to Rome","effects":{"gold":60,"controlPenalty":10}},{"label":"Shelter him and defy Rome","effects":{"hr":40,"controlBonus":5}}]},{"id":"ai_europe_uproot_vines","ageId":"classical","year":-60,"theme":"europe","title":"Uproot the Vines","description":"Your high priest Decaeneus urges you to tear up the vineyards so the Dacians stay sober and obedient. Nobles and wine merchants grumble at the thought.","options":[{"label":"Order the vines uprooted","effects":{"gold":-90,"controlBonus":10,"militaryStrengthBonus":20}},{"label":"Tax the wine instead","effects":{"gold":80,"controlPenalty":5}}]},{"id":"ai_americas_empty_nets","ageId":"bronze","year":-1800,"theme":"americas","title":"The Nets Come Up Empty","description":"Warm waters off the coast have driven away the anchovy shoals, and the fishing villages ask Caral for cotton and squash on credit.","options":[{"label":"Open the city stores to the coast","effects":{"gold":-70,"controlBonus":5}},{"label":"Keep the stores for Caral alone","effects":{"gold":30,"controlPenalty":6}},{"label":"Send the fishers inland to farm","effects":{"hr":-20,"techPoints":10}}]},{"id":"ai_americas_shicra_foundations","ageId":"bronze","year":-1950,"theme":"americas","title":"Bags of Stone","description":"Your builders propose raising the next platform on shicra, reed bags packed with stones that shift and settle when the earth shakes.","options":[{"label":"Weave thousands of shicra bags","effects":{"gold":-60,"defenseBonus":0.08}},{"label":"Build quickly with loose rubble fill","effects":{"gold":30,"controlPenalty":4}}]},{"id":"ai_americas_magnetite_mirrors","ageId":"bronze","year":-1150,"theme":"americas","title":"Mirrors for the Gulf","description":"Craftsmen in your valley polish magnetite into small mirrors, and traders from the Gulf coast offer shells and fine goods for every one they can carry.","options":[{"label":"Expand the mirror workshops","effects":{"gold":80,"hr":-20}},{"label":"Keep the mirrors for our own chiefs","effects":{"gold":-30,"controlBonus":6}},{"label":"Demand jade in exchange","effects":{"gold":50}}]},{"id":"ai_americas_burning_the_forest","ageId":"bronze","year":-900,"theme":"americas","title":"Burning the Forest","description":"Settlers on the Petén ridges want to burn wide tracts of forest for maize, though the elders warn the thin soil tires after a few harvests.","options":[{"label":"Clear wide fields for maize","effects":{"hr":40,"gold":-40}},{"label":"Clear slowly and leave land fallow","effects":{"techPoints":15,"hr":-10}}]},{"id":"ai_americas_copper_from_north","ageId":"bronze","year":-1500,"theme":"americas","title":"Copper from the North","description":"Traders speak of pure copper lying in the ground by the great northern lakes, a long journey by canoe and foot from your mounds.","options":[{"label":"Send traders north with stone beads","effects":{"gold":-50,"copper":50}},{"label":"Rely on local chert and stone","effects":{"gold":30}}]},{"id":"ai_americas_soapstone_lamps","ageId":"bronze","year":-850,"theme":"americas","title":"Lamps Against the Dark","description":"A colder age grips the Arctic, and your hunters ask whether to carve soapstone lamps and winter on the sea ice or follow the caribou.","options":[{"label":"Carve lamps and hunt seals on ice","effects":{"gold":-40,"oil":40,"controlBonus":4}},{"label":"Follow the caribou herds south","effects":{"hr":-20,"gold":30}}]},{"id":"ai_americas_fields_above_frost","ageId":"bronze","year":-1000,"theme":"americas","title":"Fields Above the Frost","description":"Farmers by Lake Titicaca find that crops on raised beds between water channels survive the killing night frosts of the high plain.","options":[{"label":"Dig canals and raised beds","effects":{"hr":-40,"gold":70}},{"label":"Herd llamas on the puna instead","effects":{"gold":40,"controlPenalty":3}}]},{"id":"ai_americas_seeds_from_south","ageId":"bronze","year":-1500,"theme":"americas","title":"Seeds from the South","description":"Wanderers from the south bring a strange grass with fat ears of grain, but it demands water and settled fields in your dry canyons.","options":[{"label":"Plant maize along the washes","effects":{"techPoints":20,"hr":-20}},{"label":"Keep gathering wild seeds and game","effects":{"gold":30}}]},{"id":"ai_korea_gold_collection_drive","ageId":"information","year":1998,"theme":"korea","title":"The Gold Collection Drive","description":"The currency has collapsed and foreign lenders demand harsh reforms. Ordinary families offer their wedding rings and heirlooms to help repay the national debt.","options":[{"label":"Accept the lenders' terms in full","effects":{"gold":200,"controlPenalty":8}},{"label":"Rally the public gold drive","effects":{"gold":90,"controlBonus":6}}]},{"id":"ai_korea_arduous_march","ageId":"information","year":1996,"theme":"korea","title":"The Arduous March","description":"Floods and the loss of old allies have emptied the granaries. Hunger spreads through the villages while the army still eats first.","options":[{"label":"Accept foreign food aid and monitors","effects":{"hr":60,"controlPenalty":7}},{"label":"Keep the army first, ration the rest","effects":{"hr":-110,"militaryStrengthBonus":0.08}}]},{"id":"ai_korea_broadband_for_all","ageId":"information","year":1999,"theme":"korea","title":"Fiber to Every Home","description":"Internet cafes are packed every night and engineers say the city could be wired faster than any in the world, if the state pays for it.","options":[{"label":"Fund fiber lines to every apartment","effects":{"gold":-250,"techPoints":90}},{"label":"Leave it to the telecom firms","effects":{"gold":50,"techPoints":25,"controlPenalty":4}}]},{"id":"ai_korea_summit_in_the_north","ageId":"information","year":2000,"theme":"korea","title":"A Summit Across the Border","description":"An invitation arrives to meet the northern leader face to face. Critics whisper that the meeting will cost far more than anyone admits.","options":[{"label":"Fly north and offer engagement","effects":{"gold":-150}},{"label":"Decline and strengthen the border","effects":{"defenseBonus":0.08}}]},{"id":"ai_korea_underground_test","ageId":"information","year":2006,"theme":"korea","title":"The Mountain Test Site","description":"Your scientists report the device is ready beneath the mountain. A test would prove your strength but bring sanctions from every major power.","options":[{"label":"Order the detonation","effects":{"militaryStrengthBonus":0.1,"gold":-80}},{"label":"Hold it back as a bargaining chip","effects":{"controlPenalty":5}}]},{"id":"ai_korea_joint_industrial_zone","ageId":"information","year":2004,"theme":"korea","title":"Factories for Southern Firms","description":"Southern companies offer to build factories near the border and pay wages in hard currency. Your workers would see how the other side lives.","options":[{"label":"Open the zone to southern firms","effects":{"gold":150,"controlPenalty":8}},{"label":"Keep the gates shut","effects":{"controlBonus":6,"gold":-60}}]},{"id":"ai_korea_ancient_capital_ruins","ageId":"information","year":2015,"theme":"korea","title":"Ruins of the Old Capital","description":"Archaeologists have uncovered palace foundations beneath the town, and world heritage status is within reach. Developers want the same land for hotels.","options":[{"label":"Protect and restore the excavations","effects":{"gold":-120,"techPoints":15}},{"label":"Approve the resort development","effects":{"gold":120,"controlPenalty":5}}]},{"id":"ai_korea_whose_ancient_kingdom","ageId":"information","year":2004,"theme":"korea","title":"Whose Ancient Kingdom?","description":"Scholars in a powerful neighbor now teach that your ancestors' kingdoms were their own provinces. Your people demand an answer.","options":[{"label":"Lodge a formal public protest","effects":{"controlBonus":6}},{"label":"Quietly fund your own historians","effects":{"gold":-80,"techPoints":30}}]},{"id":"ai_korea_memory_chip_wager","ageId":"information","year":1992,"theme":"korea","title":"The Memory Chip Wager","description":"Your chaebol leaders believe they can overtake the world's chipmakers, but only with cheap state loans and years of losses.","options":[{"label":"Back the chip fabs with state loans","effects":{"gold":-300,"techPoints":110}},{"label":"License foreign designs instead","effects":{"gold":-80,"techPoints":40}}]},{"id":"ai_pacific_sokehs_rebellion","ageId":"modern","year":1910,"theme":"pacific","title":"The Sokehs Rebellion","description":"German officials force the men of Sokehs into unpaid road labor, and after a beating the workers kill the district officer. Warships are already on their way.","options":[{"label":"Help crush the rebels","effects":{"militaryStrengthBonus":60,"controlBonus":8,"hr":-30}},{"label":"Press for fair labor terms","effects":{"gold":-80,"controlPenalty":5}}]},{"id":"ai_pacific_highland_first_contact","ageId":"modern","year":1933,"theme":"pacific","title":"Strangers Over the Ridge","description":"An Australian patrol hunting for gold walks into the Wahgi Valley, a land outsiders believed empty. They carry shells and steel axes to trade.","options":[{"label":"Trade with the prospectors","effects":{"gold":120,"iron":40,"controlPenalty":6}},{"label":"Warn them off the valley","effects":{"defenseBonus":0.05,"gold":-40,"hr":-15}}]},{"id":"ai_pacific_guam_occupation","ageId":"modern","year":1941,"theme":"pacific","title":"The Island Falls","description":"Japanese planes bomb Guam hours after Pearl Harbor, and two days later troops land and the small American garrison surrenders. The Chamorro people must live under the new occupiers.","options":[{"label":"Shelter hidden American sailors","effects":{"defenseBonus":0.1,"hr":-40}},{"label":"Keep heads down and endure","effects":{"gold":50,"controlPenalty":8}}]},{"id":"ai_pacific_wahgi_coffee","ageId":"modern","year":1955,"theme":"pacific","title":"The Coffee Boom","description":"Planters in the Wahgi Valley pay well for coffee, and clans are clearing garden land to grow their own bushes. Food gardens shrink as the cash comes in.","options":[{"label":"Plant coffee on clan land","effects":{"gold":150,"hr":-20}},{"label":"Keep the sweet potato gardens","effects":{"hr":25,"gold":-30}}]},{"id":"ai_pacific_fiji_independence","ageId":"modern","year":1970,"theme":"pacific","title":"A Flag of Our Own","description":"Britain is ready to grant Fiji independence, but chiefs, Indo-Fijian leaders and London argue over who will hold power. Your word as high chief carries weight.","options":[{"label":"Accept a shared constitution","effects":{"gold":-50}},{"label":"Insist on chiefly guarantees","effects":{"controlBonus":10}}]},{"id":"ai_pacific_kuk_ditches","ageId":"modern","year":1972,"theme":"pacific","title":"Ditches Beneath the Swamp","description":"Archaeologists digging at the Kuk tea station find ancient drainage channels that may be among the oldest farming works on Earth. The planters want the land back.","options":[{"label":"Let the excavation continue","effects":{"techPoints":40,"gold":-40}},{"label":"Drain it for tea","effects":{"gold":100,"techPoints":-20}}]},{"id":"ai_pacific_lapita_homeland_dig","ageId":"modern","year":1985,"theme":"pacific","title":"The Potters' Stilt Village","description":"Foreign scholars ask to excavate the old stilt village on Mussau, where stamped Lapita pottery lies in the lagoon mud. Villagers fear disturbing ancestral ground.","options":[{"label":"Grant the dig permit","effects":{"techPoints":50,"controlPenalty":4}},{"label":"Protect the ancestral site","effects":{"controlBonus":5,"techPoints":-15}}]},{"id":"ai_pacific_fiji_coup","ageId":"modern","year":1987,"theme":"pacific","title":"Soldiers in Parliament","description":"An army officer storms Parliament and overthrows the newly elected government, claiming to defend Fijian chiefly rule. Bau must decide where it stands.","options":[{"label":"Back the coup leaders","effects":{"controlBonus":10}},{"label":"Call for restoring the constitution","effects":{"controlPenalty":8}}]},{"id":"ai_steppe_khagan_chooses_faith","ageId":"kingdoms","year":740,"theme":"steppe","title":"The Khagan Chooses a Faith","description":"Christian envoys from Constantinople and Muslim envoys from the Caliphate each press you to adopt their faith. Rabbis among your merchants offer a third path that binds you to neither empire.","options":[{"label":"Embrace Judaism and stand apart","effects":{"controlBonus":8}},{"label":"Accept baptism and Byzantine friendship","effects":{"controlPenalty":10}},{"label":"Keep the old sky god","effects":{"techPoints":-15,"controlBonus":4}}]},{"id":"ai_steppe_volga_river_tithe","ageId":"kingdoms","year":922,"theme":"steppe","title":"Tithe on the Volga","description":"Rus boats laden with furs and slaves pass Atil on their way to the Caspian. Your customs men can take a tenth of every cargo, but the Rus grow restless at the price.","options":[{"label":"Collect the full tenth","effects":{"gold":150}},{"label":"Lower the toll to keep peace","effects":{"gold":40}},{"label":"Garrison the river with troops","effects":{"gold":-80,"hr":-40,"defenseBonus":0.1}}]},{"id":"ai_steppe_smiths_of_the_rouran","ageId":"kingdoms","year":551,"theme":"steppe","title":"Smiths No Longer","description":"The Rouran khagan scorned your request for a royal bride, calling your people his blacksmith slaves. Your forges have armed many warriors, and the Western Wei offer a princess of their own.","options":[{"label":"Rise in revolt against the Rouran","effects":{"iron":-50,"hr":-70,"militaryStrengthBonus":12}},{"label":"Marry into the Wei court first","effects":{"gold":-60}},{"label":"Swallow the insult and keep forging","effects":{"iron":50,"controlPenalty":8}}]},{"id":"ai_steppe_silk_embassy_west","ageId":"kingdoms","year":568,"theme":"steppe","title":"Silk for Constantinople","description":"Persia burned your merchants' silk rather than let it pass west. Your trader Maniakh proposes carrying it around Persia, straight to the Roman emperor, by the long northern road.","options":[{"label":"Send Maniakh to Constantinople","effects":{"gold":-90}},{"label":"Bargain again with the Persians","effects":{"gold":50,"controlPenalty":5}}]},{"id":"ai_steppe_paper_mills_samarkand","ageId":"kingdoms","year":795,"theme":"steppe","title":"The Paper Makers","description":"Craftsmen in the city have learned to make paper from rags and flax, cheaper than parchment or papyrus. Scribes from Baghdad already ask for more than the mills can make.","options":[{"label":"Build mills along the canals","effects":{"gold":-100,"techPoints":45}},{"label":"Keep the craft a guarded secret","effects":{"gold":80}}]},{"id":"ai_steppe_river_eats_kath","ageId":"kingdoms","year":990,"theme":"steppe","title":"The River Eats Kath","description":"The shifting Oxus has swallowed whole quarters of your old capital, and the citadel walls now lean over the water. Rival Gurganj, safely across the river to the northwest, grows richer every year.","options":[{"label":"Build dikes to hold the river","effects":{"gold":-120,"hr":-30,"defenseBonus":0.08}},{"label":"Move the court to safer ground","effects":{"gold":-60,"controlPenalty":10}}]},{"id":"ai_steppe_tang_princess_bride","ageId":"kingdoms","year":641,"theme":"steppe","title":"A Princess From Chang'an","description":"After your armies pressed on the Tang frontier, the emperor agrees to send Princess Wencheng as a bride. Her retinue brings Buddhist monks, artisans and Chinese ways your nobles distrust.","options":[{"label":"Welcome her with full honors","effects":{"techPoints":30,"controlPenalty":6}},{"label":"Accept the bride, dismiss the monks","effects":{"controlBonus":5}},{"label":"Refuse and keep raiding","effects":{"gold":90,"hr":-50}}]},{"id":"ai_steppe_karakhanid_holy_war","ageId":"kingdoms","year":1000,"theme":"steppe","title":"War With Kashgar","description":"The Muslim Karakhanids of Kashgar have warred on your Buddhist kingdom for decades. Your monasteries hold jade and gold enough to hire more soldiers, but the abbots refuse to give it.","options":[{"label":"Seize the monastery treasuries","effects":{"gold":150,"militaryStrengthBonus":8,"controlPenalty":12}},{"label":"Beg aid from Dunhuang and Tibet","effects":{"defenseBonus":0.1}},{"label":"Sue for a costly truce","effects":{"gold":-140,"controlBonus":5}}]},{"id":"ai_mesopotamia_portuguese_pearl_tribute","ageId":"gunpowder","year":1521,"theme":"mesopotamia","title":"Portuguese Sails Off Bahrain","description":"A Portuguese fleet from Hormuz anchors off your pearl banks and demands yearly tribute in exchange for leaving your divers and dhows alone.","options":[{"label":"Pay the tribute in pearls","effects":{"gold":-90}},{"label":"Man the fort and resist","effects":{"hr":-50,"defenseBonus":0.1}}]},{"id":"ai_mesopotamia_shah_and_sultan","ageId":"gunpowder","year":1534,"theme":"mesopotamia","title":"Between Shah and Sultan","description":"Ottoman armies march down the Tigris toward Safavid-held Baghdad, and both sides demand that your tribes declare for them before the summer campaign.","options":[{"label":"Declare for the Sultan","effects":{"controlPenalty":8}},{"label":"Declare for the Shah","effects":{"controlPenalty":8}},{"label":"Fortify and answer neither","effects":{"gold":-100,"defenseBonus":0.08}}]},{"id":"ai_mesopotamia_foreign_gunners","ageId":"gunpowder","year":1598,"theme":"mesopotamia","title":"English Gunners at Court","description":"Two English adventurers arrive offering to train your soldiers in cannon casting and musket drill, but your old cavalry chiefs resent foreign hands on the army.","options":[{"label":"Hire them and build a musket corps","effects":{"gold":-120,"militaryStrengthBonus":0.1,"controlPenalty":6}},{"label":"Send them away with gifts","effects":{"gold":-30,"controlBonus":5}}]},{"id":"ai_mesopotamia_caravan_tolls","ageId":"gunpowder","year":1620,"theme":"mesopotamia","title":"The Aleppo Caravans","description":"Great caravans carrying Indian cloth and spices between Basra and Aleppo now pass beneath your walls along the Euphrates, and merchants complain of desert raiders.","options":[{"label":"Raise the river tolls","effects":{"gold":110}},{"label":"Pay riders to escort them","effects":{"gold":-60,"hr":-20}}]},{"id":"ai_mesopotamia_plague_and_flood","ageId":"gunpowder","year":1831,"theme":"mesopotamia","title":"Plague Behind the Levees","description":"Plague has reached the markets just as the river rises against the levees, and your officials cannot both close the gates and gather workers for the dikes.","options":[{"label":"Seal the city in quarantine","effects":{"gold":-80,"hr":-30}},{"label":"Keep markets open, rebuild levees","effects":{"hr":-90,"defenseBonus":0.05}}]},{"id":"ai_mesopotamia_euphrates_steamers","ageId":"gunpowder","year":1836,"theme":"mesopotamia","title":"Steamers on the Euphrates","description":"British officers haul iron steamboats overland from the coast and ask leave to survey the Euphrates as a fast route to India.","options":[{"label":"Grant passage and sell them coal","effects":{"gold":70,"techPoints":15,"controlPenalty":5}},{"label":"Forbid foreign ships on the river","effects":{"controlBonus":6}}]},{"id":"ai_mesopotamia_telegraph_line","ageId":"gunpowder","year":1865,"theme":"mesopotamia","title":"The Wire to India","description":"Engineers ask to run a telegraph line across your lands toward the Gulf, offering you a station and fees, though tribes fear the poles mark future conquest.","options":[{"label":"Allow the line and guard it","effects":{"techPoints":30,"gold":-50}},{"label":"Demand higher fees first","effects":{"gold":60}}]},{"id":"ai_mesopotamia_french_excavators","ageId":"gunpowder","year":1885,"theme":"mesopotamia","title":"Diggers in the Ancient Mound","description":"A French couple uncovers glazed brick friezes of ancient archers in the old mound and asks permission to ship them to Paris.","options":[{"label":"Let them ship the finds","effects":{"gold":40,"controlPenalty":7}},{"label":"Keep the treasures at home","effects":{"controlBonus":5}}]},{"id":"ai_indic_harappa_salt_bricks","ageId":"information","year":1998,"theme":"indic","title":"Salt Eats the Bricks","description":"Groundwater salts are crumbling Harappa's excavated walls, and the archaeologists say only costly drainage and reburial can save them.","options":[{"label":"Fund drainage and rebury exposed walls","effects":{"gold":-120,"techPoints":20}},{"label":"Open the mound wider for tourists","effects":{"gold":60}}]},{"id":"ai_indic_taxila_foundries_stupas","ageId":"information","year":2010,"theme":"indic","title":"Foundries Beside the Stupas","description":"Heavy industry around Takshashila brings jobs and arms contracts, but heritage experts warn that dust and blasting are cracking the nearby Buddhist monasteries.","options":[{"label":"Expand the works, the army needs them","effects":{"iron":50,"militaryStrengthBonus":0.05}},{"label":"Zone a protected buffer around the ruins","effects":{"gold":-100}}]},{"id":"ai_indic_lothal_maritime_complex","ageId":"information","year":2022,"theme":"indic","title":"A Museum for the Dockyard","description":"Planners want a vast maritime heritage complex at Lothal's ancient dock, but the same budget could dredge working ports along the Gujarat coast.","options":[{"label":"Build the heritage complex","effects":{"gold":-200,"techPoints":10}},{"label":"Dredge the working ports instead","effects":{"gold":-100,"oil":50}}]},{"id":"ai_indic_ujjain_simhastha_water","ageId":"information","year":2016,"theme":"indic","title":"Millions Come to the Kshipra","description":"The Simhastha fair draws tens of millions of pilgrims to Ujjayini's ghats, yet the Kshipra runs too low to bathe in without piping in Narmada water.","options":[{"label":"Pipe in water from the Narmada","effects":{"gold":-150,"controlBonus":10}},{"label":"Limit the crowds with permits","effects":{"gold":40,"controlPenalty":8}}]},{"id":"ai_indic_hastinapura_legend_dig","ageId":"information","year":2020,"theme":"indic","title":"Digging Under Legend","description":"Hastinapura is named an iconic heritage site, and many believers expect the excavators to prove the Mahabharata true.","options":[{"label":"Fund a large, careful excavation","effects":{"gold":-120,"techPoints":25}},{"label":"Build a pilgrim park first","effects":{"gold":-60,"controlBonus":6}}]},{"id":"ai_indic_nalanda_revival","ageId":"information","year":2014,"theme":"indic","title":"Reviving Nalanda","description":"A new Nalanda University opens near Rajagriha, and Asian partners offer money if the old monastic center becomes an international campus.","options":[{"label":"Accept foreign funding and partners","effects":{"gold":100,"controlPenalty":5}},{"label":"Fund it from home alone","effects":{"gold":-180,"techPoints":40}}]},{"id":"ai_indic_brahmaputra_floods","ageId":"information","year":2022,"theme":"indic","title":"The Brahmaputra Rises","description":"Monsoon floods drown thousands of villages across the old lands of Kamarupa, and Kaziranga's rhinos flee toward the highway.","options":[{"label":"Send the army to rescue villages","effects":{"hr":-40,"gold":-100,"controlBonus":10}},{"label":"Raise embankments for next year","effects":{"gold":-150,"defenseBonus":0.1}},{"label":"Leave relief to local councils","effects":{"gold":30,"controlPenalty":10}}]},{"id":"ai_indic_chandraketugarh_terracottas","ageId":"information","year":2005,"theme":"indic","title":"Terracottas on the Black Market","description":"Farmers near Chandraketugarh dig up terracotta figures and sell them to dealers abroad, while the site still lacks a full excavation.","options":[{"label":"Buy the finds from the farmers","effects":{"gold":-80}},{"label":"Police the fields and arrest dealers","effects":{"hr":-20,"controlPenalty":5}},{"label":"Launch a full state excavation","effects":{"gold":-150,"techPoints":30}}]},{"id":"ai_americas_french_at_guanabara","ageId":"gunpowder","year":1555,"theme":"americas","title":"Frenchmen in the Bay","description":"French ships have anchored in Guanabara Bay, offering iron tools and muskets for brazilwood and warriors against the Portuguese and their allies.","options":[{"label":"Arm your warriors with French guns","effects":{"militaryStrengthBonus":0.1,"controlPenalty":5}},{"label":"Trade brazilwood for iron only","effects":{"iron":50,"hr":-20}},{"label":"Keep all strangers at a distance","effects":{"controlBonus":5}}]},{"id":"ai_americas_governors_feast","ageId":"gunpowder","year":1503,"theme":"americas","title":"The Governor's Visit","description":"The Spanish governor Ovando is marching to Jaragua with horsemen, asking you to gather your caciques for a feast in his honor.","options":[{"label":"Host the feast with all chiefs","effects":{"hr":-60}},{"label":"Send the chiefs into the mountains","effects":{"controlPenalty":8,"defenseBonus":0.1}}]},{"id":"ai_americas_neutral_island_treaty","ageId":"gunpowder","year":1660,"theme":"americas","title":"A Treaty for Dominica","description":"English and French envoys propose leaving Dominica to the Kalinago if your canoes stop raiding their sugar islands.","options":[{"label":"Accept and end the raids","effects":{"controlBonus":8,"gold":-40}},{"label":"Keep raiding the plantations","effects":{"gold":70}}]},{"id":"ai_americas_quesada_on_the_savanna","ageId":"gunpowder","year":1537,"theme":"americas","title":"Strangers on the Savanna","description":"Bearded men led by Jiménez de Quesada have climbed onto the high savanna, asking where the emeralds and gold of Bacatá come from.","options":[{"label":"Hide the treasure and abandon Bacatá","effects":{"gold":50,"controlPenalty":10}},{"label":"Fight them at the city's fences","effects":{"hr":-70,"defenseBonus":0.1}},{"label":"Offer gifts to buy time","effects":{"gold":-80}}]},{"id":"ai_americas_sea_otter_traders","ageId":"gunpowder","year":1791,"theme":"americas","title":"The Fur Traders Return","description":"An American ship that once humiliated you has returned to trade for sea otter pelts, its deck lined with muskets and cloth.","options":[{"label":"Trade pelts for muskets","effects":{"militaryStrengthBonus":0.08,"hr":-15}},{"label":"Attack the ship to restore your honor","effects":{"controlBonus":10,"hr":-40}}]},{"id":"ai_americas_jesuit_mission_calos","ageId":"gunpowder","year":1567,"theme":"americas","title":"Priests at Calos","description":"Spanish Jesuits have built a mission and blockhouse beside your town, promising friendship if your people abandon their old rites.","options":[{"label":"Let the priests preach","effects":{"controlPenalty":8}},{"label":"Burn the mission and expel them","effects":{"controlBonus":6,"hr":-30}}]},{"id":"ai_americas_false_inca_bohorquez","ageId":"gunpowder","year":1658,"theme":"americas","title":"A Spaniard Claims Inca Blood","description":"Pedro Bohórquez, a Spanish adventurer calling himself the heir of the Incas, asks the valley to crown him and rise against Spanish rule.","options":[{"label":"Crown him and rebel","effects":{"militaryStrengthBonus":0.1,"controlPenalty":12}},{"label":"Use him, but guard the passes","effects":{"defenseBonus":0.08,"gold":-60}},{"label":"Hand him to the governor","effects":{"controlPenalty":6}}]},{"id":"ai_americas_zapotec_spanish_alliance","ageId":"gunpowder","year":1521,"theme":"americas","title":"After Tenochtitlan Falls","description":"The Mexica capital has fallen to Cortés, and his captains are riding south toward the Zapotec valleys, asking for submission and tribute.","options":[{"label":"Ally with the Spaniards","effects":{"gold":-70}},{"label":"Retreat to the mountain fortresses","effects":{"defenseBonus":0.1,"hr":-30}}]},{"id":"ai_sinic_three_gorges_dam","ageId":"information","year":1994,"theme":"sinic","title":"Damming the Great River","description":"Engineers propose a vast dam across the Yangtze gorges to tame floods and light a million homes. Over a million people would have to leave villages their families have farmed for centuries.","options":[{"label":"Build the dam and relocate the villages","effects":{"gold":-300,"techPoints":80,"controlPenalty":10}},{"label":"Build smaller dams on the tributaries","effects":{"gold":-120,"techPoints":25}},{"label":"Leave the river as it is","effects":{"gold":40}}]},{"id":"ai_sinic_southern_factory_zone","ageId":"information","year":1992,"theme":"sinic","title":"Factories of the Pearl River","description":"Foreign investors offer to fill the Pearl River delta with factories if you loosen the rules on trade and land. Workers would pour in from the countryside faster than housing can be built.","options":[{"label":"Open a special economic zone","effects":{"gold":200,"hr":-60,"controlPenalty":8}},{"label":"Allow only state-owned joint ventures","effects":{"gold":90,"controlBonus":5}}]},{"id":"ai_sinic_sichuan_earthquake","ageId":"information","year":2008,"theme":"sinic","title":"The Mountains Shake","description":"A great earthquake tears through the Sichuan hills, flattening schools and towns. Grieving parents ask why so many classrooms collapsed while other buildings stood.","options":[{"label":"Send the army and rebuild at once","effects":{"gold":-250,"hr":-50,"controlBonus":8}},{"label":"Investigate the shoddy school builders","effects":{"gold":-80,"controlPenalty":6,"defenseBonus":0.08}},{"label":"Leave rebuilding to the provinces","effects":{"gold":-40,"controlPenalty":12}}]},{"id":"ai_sinic_oracle_bone_heritage","ageId":"information","year":2006,"theme":"sinic","title":"Ruins of the Oracle Bones","description":"International heritage experts want to list the ancient ruins of Yin, home of the oracle bones. The listing would bring tourists but forbid the factories planned on the site.","options":[{"label":"Protect the ruins and seek the listing","effects":{"gold":-100,"techPoints":15}},{"label":"Let the industrial park go ahead","effects":{"gold":150}}]},{"id":"ai_sinic_online_marketplace","ageId":"information","year":1999,"theme":"sinic","title":"Merchants Go Online","description":"A former English teacher and his friends start an internet marketplace from a small apartment. Bankers call it a fad, but local workshops are already selling to buyers overseas.","options":[{"label":"Back the startups with cheap loans","effects":{"gold":-150,"techPoints":60}},{"label":"Tax the new trade like any other","effects":{"gold":80,"techPoints":10}},{"label":"Regulate the internet tightly","effects":{"controlBonus":8,"techPoints":-20}}]},{"id":"ai_sinic_southern_railway","ageId":"information","year":2021,"theme":"sinic","title":"Rails to the South","description":"A new railway would tunnel through the Yunnan mountains to Laos and beyond. Neighbors welcome the trade but worry about the debts their governments must carry for it.","options":[{"label":"Fund the railway through loans","effects":{"gold":-200,"controlBonus":5}},{"label":"Share costs and ownership with neighbors","effects":{"gold":-80}},{"label":"Upgrade the old mountain roads instead","effects":{"gold":-40}}]},{"id":"ai_sinic_barbecue_craze","ageId":"information","year":2023,"theme":"sinic","title":"The Barbecue Craze","description":"Videos of the town's cheap skewer stalls go viral, and students arrive by the trainload. Hotels are full, prices are rising, and residents complain about the crowds.","options":[{"label":"Add trains and cap hotel prices","effects":{"gold":-60,"controlBonus":6}},{"label":"Let the market cash in","effects":{"gold":120,"controlPenalty":5}}]},{"id":"ai_sinic_freight_trains_west","ageId":"information","year":2013,"theme":"sinic","title":"Freight Trains to Europe","description":"Old Silk Road cities in the west want regular freight trains running across Central Asia to Europe. The trains are slower than planes, costlier than ships, and need heavy subsidies.","options":[{"label":"Subsidize the westward freight line","effects":{"gold":-180,"iron":30}},{"label":"Keep trade on the coastal ports","effects":{"gold":60,"controlPenalty":4}}]},{"id":"ai_maghreb_ransom_of_alcacer","ageId":"gunpowder","year":1578,"theme":"maghreb","title":"Captives of Three Kings","description":"After the Portuguese army is shattered at Alcácer Quibir, thousands of noble captives fill your camps. Lisbon's families beg to buy them back, while your commanders want them kept as leverage.","options":[{"label":"Sell them back at high ransom","effects":{"gold":180}},{"label":"Free some as a gesture to Europe","effects":{"gold":-40}},{"label":"Draft the captive gunners","effects":{"militaryStrengthBonus":0.08,"controlPenalty":5}}]},{"id":"ai_maghreb_musketeers_at_the_gates","ageId":"gunpowder","year":1591,"theme":"maghreb","title":"Musketeers on the Niger","description":"Moroccan musketeers who broke the Songhay at Tondibi now march up the river. The city's merchants and scholars debate whether to open the gates or trust the flood plains and walls.","options":[{"label":"Submit and pay tribute","effects":{"gold":-120,"controlBonus":6}},{"label":"Hold the walls and resist","effects":{"hr":-60,"defenseBonus":0.1}}]},{"id":"ai_maghreb_turkish_musketeers","ageId":"gunpowder","year":1575,"theme":"maghreb","title":"Guns from the Ottomans","description":"Envoys returning from Tripoli offer Turkish musketeers and firearms for your army. They come dear, and your old cavalry nobles resent soldiers who answer only to the throne.","options":[{"label":"Hire the musketeers","effects":{"gold":-150,"militaryStrengthBonus":0.12,"controlPenalty":4}},{"label":"Buy only a few guns","effects":{"gold":-50,"iron":-20,"militaryStrengthBonus":0.04}},{"label":"Trust the cavalry lords","effects":{"controlBonus":5,"techPoints":-10}}]},{"id":"ai_maghreb_siege_of_constantine","ageId":"gunpowder","year":1837,"theme":"maghreb","title":"French Guns Below the Rock","description":"A French army has returned to besiege the city on its gorge after failing the year before. Their siege artillery is heavier now, and the defenders are short of powder.","options":[{"label":"Fight on from the walls","effects":{"hr":-80,"defenseBonus":0.1}},{"label":"Negotiate terms of surrender","effects":{"gold":-60,"controlPenalty":10}}]},{"id":"ai_maghreb_ottoman_tripoli","ageId":"gunpowder","year":1551,"theme":"maghreb","title":"The Sultan's New Province","description":"Ottoman corsairs have driven the Knights of Saint John out of Tripoli, and their governor demands that the eastern tribes and towns recognize the Sultan.","options":[{"label":"Accept Ottoman suzerainty","effects":{"gold":-70}},{"label":"Stay aloof in the hills","effects":{"controlBonus":6}}]},{"id":"ai_maghreb_fezzan_caravan_tax","ageId":"gunpowder","year":1560,"theme":"maghreb","title":"Toll on the Caravans","description":"Caravans between Bornu and Tripoli pass your oases loaded with slaves, ivory and cloth. A new ruling house at Murzuq is competing for the same traffic with lower tolls.","options":[{"label":"Raise the tolls","effects":{"gold":110}},{"label":"Cut tolls to keep caravans","effects":{"gold":-40}},{"label":"Send riders to escort them","effects":{"hr":-30,"gold":60}}]},{"id":"ai_maghreb_char_bouba_war","ageId":"gunpowder","year":1660,"theme":"maghreb","title":"Warriors Against Scholars","description":"The Char Bouba war divides the desert: Arab warrior clans fight the Berber scholarly lineages. Both sides demand your caravan towns choose, and both threaten the salt roads.","options":[{"label":"Side with the warrior clans","effects":{"militaryStrengthBonus":0.06,"techPoints":-15}},{"label":"Shelter the scholar families","effects":{"techPoints":30}},{"label":"Pay both sides to stay away","effects":{"gold":-90,"controlBonus":4}}]},{"id":"ai_maghreb_corsair_licenses","ageId":"gunpowder","year":1620,"theme":"maghreb","title":"Licenses for the Corsairs","description":"Corsair captains of Algiers bring rich prizes and European captives home each season. European fleets now threaten to bombard the harbor unless the raids are curbed.","options":[{"label":"Grant more corsair licenses","effects":{"gold":140}},{"label":"Sign a truce with the Europeans","effects":{"controlPenalty":6}},{"label":"Fortify the harbor instead","effects":{"gold":-100,"defenseBonus":0.1}}]},{"id":"ai_maghreb_goats_on_the_green_mountain","ageId":"stone","year":-4800,"theme":"maghreb","title":"Goats in the Cave","description":"Families sheltering in the great caves of the Green Mountain now pen sheep and goats beside their hearths, but the flocks strip the hillside shrubs.","options":[{"label":"Raise larger flocks on the slopes","effects":{"gold":50,"controlPenalty":4}},{"label":"Keep hunting the wild Barbary sheep","effects":{"hr":15,"gold":-20}}]},{"id":"ai_maghreb_painted_rock_shelters","ageId":"stone","year":-4000,"theme":"maghreb","title":"Paintings on the Rock","description":"Your painters cover the shelters of the Acacus with cattle, dancers and masked figures, and herders travel far to see them.","options":[{"label":"Feed the painters through the dry season","effects":{"gold":-40,"controlBonus":8}},{"label":"Send the painters back to the herds","effects":{"gold":30,"controlPenalty":4}}]},{"id":"ai_maghreb_snail_shell_mounds","ageId":"stone","year":-4700,"theme":"maghreb","title":"The Snail Mounds","description":"Your camps sit on mounds of land snail shells left by generations, yet some families now want to herd sheep and leave the old sites.","options":[{"label":"Keep the old camps and gathering","effects":{"defenseBonus":0.05,"gold":-20}},{"label":"Take up flocks and move with them","effects":{"hr":20,"controlPenalty":5}}]},{"id":"ai_maghreb_ivory_across_the_strait","ageId":"stone","year":-2500,"theme":"maghreb","title":"Ivory Across the Strait","description":"Boatmen from the northern shore cross the strait seeking elephant tusks, and offer fine pottery and copper trinkets in return.","options":[{"label":"Hunt elephants for the traders","effects":{"gold":70,"hr":-15}},{"label":"Trade a little, learn their crafts","effects":{"techPoints":15,"gold":-20}},{"label":"Turn the strangers away","effects":{"defenseBonus":0.05}}]},{"id":"ai_maghreb_stone_walled_villages","ageId":"stone","year":-2100,"theme":"maghreb","title":"Walls of Dry Stone","description":"Herders settling along the cliffs begin to ring their compounds with dry stone walls, though hauling the stone takes hands from the cattle.","options":[{"label":"Raise walls around every compound","effects":{"defenseBonus":0.1,"hr":-20}},{"label":"Keep the people with the herds","effects":{"gold":40}}]},{"id":"ai_maghreb_the_drying_pastures","ageId":"stone","year":-3000,"theme":"maghreb","title":"The Pastures Wither","description":"The rains fail year after year, the lakes shrink to salt pans, and your elders argue whether to drive the cattle south.","options":[{"label":"Drive the herds south to wetter land","effects":{"hr":20,"controlPenalty":6}},{"label":"Dig deeper wells and stay","effects":{"gold":-50,"controlBonus":5}}]},{"id":"ai_maghreb_bone_harpoons","ageId":"stone","year":-4500,"theme":"maghreb","title":"Harpoons of Bone","description":"Your fishers carve barbed bone harpoons and take great catfish and perch from the flooded channels, but the floods rise without warning.","options":[{"label":"Build camps close to the water","effects":{"gold":50}},{"label":"Camp on high ground, fish less","effects":{"defenseBonus":0.05,"gold":-20}}]},{"id":"ai_maghreb_the_shrinking_lake","ageId":"stone","year":-4000,"theme":"maghreb","title":"The Great Lake Shrinks","description":"The vast lake your ancestors fished pulls back from its old shores, leaving dunes where canoes once floated.","options":[{"label":"Follow the shore with the canoes","effects":{"hr":15,"controlPenalty":5}},{"label":"Turn to herding on the new grass","effects":{"gold":-30,"techPoints":15}}]},{"id":"ai_israelite_rebuild_city_walls","ageId":"gunpowder","year":1537,"theme":"israelite","title":"Walls for the Holy City","description":"Raiders strip the countryside, and your engineers urge a full stone circuit with gun-ready gates around Jerusalem. The quarries and masons will cost you dearly.","options":[{"label":"Raise the full circuit of walls","effects":{"gold":-150,"defenseBonus":0.1}},{"label":"Repair only the gates and towers","effects":{"gold":-50,"defenseBonus":0.05}}]},{"id":"ai_israelite_safed_printing_press","ageId":"gunpowder","year":1577,"theme":"israelite","title":"A Press in Safed","description":"Scholars in the hills of Galilee ask for a Hebrew printing press of their own, so the works of their mystics need not travel to Venice to be set in type.","options":[{"label":"Fund a local Hebrew press","effects":{"gold":-80,"techPoints":40}},{"label":"Keep buying books from Venice","effects":{"gold":-30,"techPoints":15}}]},{"id":"ai_israelite_tiberias_silk","ageId":"gunpowder","year":1564,"theme":"israelite","title":"Mulberries by the Lake","description":"A wealthy merchant family offers to rebuild ruined Tiberias, plant mulberry groves and weave silk, if you grant them the town and its taxes.","options":[{"label":"Grant them Tiberias","effects":{"gold":-60,"techPoints":10,"controlBonus":5}},{"label":"Keep the town's taxes yourself","effects":{"gold":30,"controlPenalty":3}}]},{"id":"ai_israelite_messianic_claimant","ageId":"gunpowder","year":1665,"theme":"israelite","title":"A Messiah Proclaimed","description":"A charismatic preacher from Smyrna is hailed as the Messiah, and your subjects sell their homes to follow him. Foreign courts watch nervously how you will respond.","options":[{"label":"Receive him with honor","effects":{"controlBonus":8}},{"label":"Have the rabbis denounce him","effects":{"controlPenalty":8}},{"label":"Wait and say nothing","effects":{"controlPenalty":4,"gold":-20}}]},{"id":"ai_israelite_french_at_the_coast","ageId":"gunpowder","year":1799,"theme":"israelite","title":"A General at Acre","description":"A French army marches up the coast from Egypt and besieges the port of Acre. British ships offer guns and gunners, at a price.","options":[{"label":"Hold the coast with British help","effects":{"gold":-60,"defenseBonus":0.1}},{"label":"Open talks with the French","effects":{"controlPenalty":6}}]},{"id":"ai_israelite_quarter_outside_walls","ageId":"gunpowder","year":1860,"theme":"israelite","title":"Beyond the Old Walls","description":"Jerusalem is crowded and plagued by disease. A philanthropist offers to build almshouses and a windmill outside the walls, but few dare sleep beyond the gates at night.","options":[{"label":"Build the new quarter outside","effects":{"gold":-100,"hr":40,"controlPenalty":3}},{"label":"Keep everyone inside the walls","effects":{"gold":20,"controlPenalty":6}}]},{"id":"ai_israelite_farming_colonies","ageId":"gunpowder","year":1882,"theme":"israelite","title":"Settlers from the North","description":"Young families fleeing pogroms arrive by ship at Jaffa, eager to drain swamps and found farming villages. They have little money and less experience.","options":[{"label":"Grant them land and seed","effects":{"hr":60,"gold":-90}},{"label":"Admit only a few each year","effects":{"hr":20,"controlPenalty":4}}]},{"id":"ai_israelite_jaffa_railway","ageId":"gunpowder","year":1892,"theme":"israelite","title":"Rails to Jerusalem","description":"Pilgrims spend days on the rough road from Jaffa to Jerusalem. You can lay a railway yourself, or let foreign investors build it for a concession.","options":[{"label":"Build the line with royal funds","effects":{"gold":-150,"iron":-40,"techPoints":35}},{"label":"Sell the concession to foreigners","effects":{"gold":50,"techPoints":15,"controlPenalty":5}}]},{"id":"ai_pacific_talasea_obsidian","ageId":"bronze","year":-1400,"theme":"pacific","title":"Obsidian from Talasea","description":"Canoes arrive carrying glassy obsidian from the volcanic shores of New Britain, far to the south. Every village wants its sharp blades, and the traders want shell valuables in return.","options":[{"label":"Send our own canoes to the source","effects":{"hr":-25,"gold":90}},{"label":"Trade through middlemen at our shore","effects":{"gold":40}},{"label":"Rely on local chert instead","effects":{"techPoints":-10,"controlBonus":4}}]},{"id":"ai_pacific_dentate_stamped_pottery","ageId":"bronze","year":-1450,"theme":"pacific","title":"The Stamped Faces","description":"Your potters press toothed stamps into wet clay, building intricate faces and bands that mark a household's lineage. The finest pots take weeks and the best clay lies far up the coast.","options":[{"label":"Honor the master potters with gifts","effects":{"gold":-60,"techPoints":20,"controlBonus":4}},{"label":"Make plain pots for daily cooking","effects":{"gold":40,"controlPenalty":5}}]},{"id":"ai_pacific_voyage_beyond_horizon","ageId":"bronze","year":-1100,"theme":"pacific","title":"Beyond the Last Island","description":"Your navigators say the swells and birds point to land past the Solomons, where no one has ever lived. Outfitting double canoes would strip the village of its strongest paddlers.","options":[{"label":"Launch the voyage with pigs and taro","effects":{"hr":-40,"gold":-50,"techPoints":30}},{"label":"Send one small scouting canoe","effects":{"hr":-10}},{"label":"Keep the people close to home","effects":{"controlBonus":5,"techPoints":-10}}]},{"id":"ai_pacific_kuk_swamp_ditches","ageId":"bronze","year":-1800,"theme":"pacific","title":"Choked Garden Ditches","description":"The drainage ditches that keep the swamp gardens dry are silting up after heavy rains. Clearing them means weeks of digging when families would rather plant.","options":[{"label":"Call every clan to dig together","effects":{"hr":-30,"controlBonus":8}},{"label":"Let each family clear its own plot","effects":{"gold":30,"controlPenalty":6}}]},{"id":"ai_pacific_cleared_slopes","ageId":"bronze","year":-1600,"theme":"pacific","title":"The Bare Hillsides","description":"Generations of burning forest for taro and banana gardens have left the valley slopes open to grass, and soil now washes down into the swamp.","options":[{"label":"Forbid new clearing on the slopes","effects":{"gold":-40,"controlPenalty":5,"defenseBonus":0.05}},{"label":"Mound and till the soil to hold it","effects":{"hr":-25,"techPoints":20}},{"label":"Keep burning, the land is wide","effects":{"gold":60,"controlPenalty":4}}]},{"id":"ai_pacific_shells_from_coast","ageId":"bronze","year":-1200,"theme":"pacific","title":"Shells from the Sea","description":"Marine shells passed hand to hand from the distant coast reach your valley, prized as bride wealth. Rival big men are bidding pigs to control the flow.","options":[{"label":"Outbid them with your herds","effects":{"gold":-70,"controlBonus":5}},{"label":"Seize the trail with your warriors","effects":{"hr":-30,"militaryStrengthBonus":10}},{"label":"Let the shells go to others","effects":{"gold":30,"controlPenalty":5}}]},{"id":"ai_pacific_landfall_marianas","ageId":"bronze","year":-1500,"theme":"pacific","title":"A New Shore","description":"After the longest open-sea crossing anyone remembers, your canoes have reached an uninhabited island of limestone and reef. The settlers must choose where to build first.","options":[{"label":"Settle by the lagoon to fish","effects":{"gold":60}},{"label":"Build on high ground inland","effects":{"hr":-20,"defenseBonus":0.1}}]},{"id":"ai_pacific_first_fiji_gardens","ageId":"bronze","year":-900,"theme":"pacific","title":"Gardens on Strange Soil","description":"The first settlers in these islands find fat birds and turtles easy to catch, but the yams and taro they brought struggle in the new ground.","options":[{"label":"Hunt freely while the game lasts","effects":{"gold":70,"controlPenalty":6}},{"label":"Put every hand to the gardens","effects":{"hr":-25,"controlBonus":7}},{"label":"Send canoes home for more cuttings","effects":{"gold":-50}}]},{"id":"ai_sinic_salt_iron_monopoly","ageId":"classical","year":-685,"theme":"sinic","title":"Salt and Iron","description":"Your minister Guan Zhong proposes that the state take control of salt and iron. It would fill your treasury, but the merchant families of Qi will resent it.","options":[{"label":"Seize salt and iron for the state","effects":{"gold":150,"iron":40,"controlPenalty":8}},{"label":"Leave the trade to private merchants","effects":{"gold":40,"iron":-20}}]},{"id":"ai_sinic_brushwood_and_gall","ageId":"classical","year":-490,"theme":"sinic","title":"Brushwood and Gall","description":"Since your defeat by Wu, you sleep on brushwood and taste bitter gall each day. Your ministers counsel patience, while your officers crave revenge.","options":[{"label":"Rebuild quietly and send tribute to Wu","effects":{"gold":-100,"hr":40,"controlBonus":5}},{"label":"Strike Wu before you are ready","effects":{"militaryStrengthBonus":50,"hr":-60,"controlPenalty":5}}]},{"id":"ai_sinic_weight_of_cauldrons","ageId":"classical","year":-606,"theme":"sinic","title":"The Weight of Cauldrons","description":"Your army stands at the Zhou border, and the royal envoy has come to greet you. You may ask him how heavy the nine sacred cauldrons of Zhou are.","options":[{"label":"Ask the weight of the cauldrons openly","effects":{"militaryStrengthBonus":40}},{"label":"Accept the envoy's rebuke and withdraw","effects":{"controlPenalty":4}}]},{"id":"ai_sinic_jixia_academy","ageId":"classical","year":-340,"theme":"sinic","title":"Scholars at Jixia Gate","description":"Thinkers from every state gather by the Jixia Gate of Linzi, debating rule and virtue. They ask for stipends and houses, and they criticize your court freely.","options":[{"label":"Grant stipends and grand residences","effects":{"gold":-120,"techPoints":45}},{"label":"Keep the debaters at arm's length","effects":{"controlBonus":6,"techPoints":-10}}]},{"id":"ai_sinic_emperor_of_the_south","ageId":"classical","year":-179,"theme":"sinic","title":"Two Emperors, One Sky","description":"The Han envoy Lu Jia returns with a letter from the new emperor. He asks you to give up your imperial title and rule Nanyue as a loyal king.","options":[{"label":"Renounce the title and submit in name","effects":{"controlPenalty":5}},{"label":"Remain Emperor of the South","effects":{"controlBonus":8}}]},{"id":"ai_sinic_seal_of_dian","ageId":"classical","year":-109,"theme":"sinic","title":"The Golden Seal","description":"Han armies have crushed your neighbors and now stand at the shores of the Dian lake. Their general offers a golden seal and the title of king, if you submit.","options":[{"label":"Accept the Han seal and submit","effects":{"controlPenalty":10}},{"label":"Resist with the hill peoples","effects":{"hr":-50,"copper":-40,"defenseBonus":0.1}}]},{"id":"ai_sinic_dujiangyan_weir","ageId":"classical","year":-256,"theme":"sinic","title":"Taming the Min River","description":"Engineers propose splitting the Min River at Dujiangyan to end the floods and water the Chengdu plain. The work would take years of conscripted labor.","options":[{"label":"Build the great weir","effects":{"gold":-150,"hr":-40,"techPoints":35}},{"label":"Repair the old dikes only","effects":{"gold":-40,"controlPenalty":4}}]},{"id":"ai_sinic_fall_of_haojing","ageId":"classical","year":-771,"theme":"sinic","title":"Haojing in Flames","description":"Rong warriors, allied with the Marquis of Shen, have sacked Haojing and slain the king. The surviving nobles argue over rebuilding or moving the court east to Luoyi.","options":[{"label":"Move the court east to Luoyi","effects":{"defenseBonus":0.1,"controlPenalty":10}},{"label":"Rebuild the walls of Haojing","effects":{"gold":-150,"hr":-50,"defenseBonus":0.08}}]},{"id":"ai_nile_fall_of_soba","ageId":"gunpowder","year":1504,"theme":"nile","title":"Funj Riders at Soba","description":"Funj horsemen and Abdallab allies close in on the old Christian capital. Its churches are crumbling, and many townsfolk would rather bargain than fight.","options":[{"label":"Man the walls and resist","effects":{"hr":-60,"defenseBonus":0.1}},{"label":"Submit and pay tribute","effects":{"gold":-70,"controlPenalty":6}}]},{"id":"ai_nile_portuguese_musketeers","ageId":"gunpowder","year":1541,"theme":"nile","title":"Four Hundred Musketeers","description":"Imam Ahmad's armies, armed with Ottoman matchlocks, have burned churches across the highlands. A small Portuguese force has landed at Massawa offering its guns, at a price.","options":[{"label":"Welcome the Portuguese guns","effects":{"militaryStrengthBonus":0.1,"gold":-100}},{"label":"Fight on from the mountain strongholds","effects":{"defenseBonus":0.1,"hr":-70}}]},{"id":"ai_nile_portuguese_raids_coast","ageId":"gunpowder","year":1506,"theme":"nile","title":"Sails Off the Coast","description":"Portuguese fleets have sacked Barawa and demand tribute from the Somali ports. Your merchants fear for the Indian Ocean trade that feeds the city.","options":[{"label":"Pay tribute to keep trading","effects":{"gold":-80}},{"label":"Build coastal forts and resist","effects":{"defenseBonus":0.1,"gold":-60,"hr":-30}}]},{"id":"ai_nile_jesuit_faith","ageId":"gunpowder","year":1622,"theme":"nile","title":"The Jesuits at Court","description":"Jesuit priests urge you to embrace the Roman faith and promise Portuguese friendship. The monks and nobles of the old church warn that the land will rise against you.","options":[{"label":"Embrace the Roman faith","effects":{"techPoints":15,"controlPenalty":12}},{"label":"Keep the ancestral church","effects":{"controlBonus":8}}]},{"id":"ai_nile_siwa_annexation","ageId":"gunpowder","year":1820,"theme":"nile","title":"Troops Reach the Oasis","description":"An Egyptian column with cannon has crossed the desert to Siwa demanding taxes on its dates. The oasis clans are split between paying and fighting.","options":[{"label":"Accept the governor and pay","effects":{"gold":-50,"controlPenalty":5}},{"label":"Rise against the garrison","effects":{"hr":-40,"defenseBonus":0.08,"controlPenalty":10}}]},{"id":"ai_nile_cotton_boom","ageId":"gunpowder","year":1863,"theme":"nile","title":"The Cotton Fever","description":"War in America has cut off its cotton, and European mills pay any price for Egyptian fibre. Landowners want to plough grain fields under for cotton.","options":[{"label":"Plant cotton on every field","effects":{"gold":200,"hr":-50}},{"label":"Keep the grain fields","effects":{"gold":40,"controlBonus":5}}]},{"id":"ai_nile_mahdist_uprising","ageId":"gunpowder","year":1883,"theme":"nile","title":"The Mahdi Calls","description":"A holy man in Kordofan proclaims himself the Mahdi and his followers have crushed an Egyptian army. Envoys arrive asking you to join his cause against the Turks.","options":[{"label":"Join the Mahdi's revolt","effects":{"militaryStrengthBonus":0.1,"controlPenalty":10}},{"label":"Stay loyal to Khartoum","effects":{"gold":60,"controlPenalty":6}}]},{"id":"ai_korea_muryeong_tomb","ageId":"kingdoms","year":525,"theme":"korea","title":"A Tomb of Southern Bricks","description":"Your late father's tomb could be built in the style of the Liang court, with lotus-stamped bricks and imported grave goods, or in the simpler stone of your ancestors.","options":[{"label":"Build in the Liang style","effects":{"gold":-120,"techPoints":10}},{"label":"Keep the old stone tradition","effects":{"gold":-30,"controlBonus":5}}]},{"id":"ai_korea_move_to_sabi","ageId":"kingdoms","year":538,"theme":"korea","title":"Leaving the Cramped Capital","description":"The hill fortress capital is safe but has no room to grow. The broad plain at Sabi on the river offers space and trade, but the old nobles resist the move.","options":[{"label":"Move the court to Sabi","effects":{"gold":-150,"techPoints":20,"controlPenalty":8}},{"label":"Stay behind the old walls","effects":{"defenseBonus":0.06,"gold":-20}}]},{"id":"ai_korea_monks_to_wa","ageId":"kingdoms","year":552,"theme":"korea","title":"Sutras for the Islands","description":"Envoys from the Wa court across the sea ask for Buddhist images, sutras and monks. Their friendship could bring soldiers, but your best scholars may never return.","options":[{"label":"Send monks, artisans and sutras","effects":{"techPoints":-15}},{"label":"Trade them for troops instead","effects":{"hr":60,"gold":-40}},{"label":"Refuse and keep your learning","effects":{"techPoints":10}}]},{"id":"ai_korea_sui_invasion","ageId":"kingdoms","year":612,"theme":"korea","title":"The Sui Host Approaches","description":"A vast army from the Chinese dynasty marches on your walled capital. Your generals propose a feigned retreat to lure them deep, while ministers urge you to sue for terms.","options":[{"label":"Feign retreat and strike at the river","effects":{"hr":-80,"militaryStrengthBonus":0.1}},{"label":"Strengthen the walls and wait","effects":{"gold":-110,"defenseBonus":0.1}},{"label":"Offer tribute to end the war","effects":{"gold":-180,"controlPenalty":6}}]},{"id":"ai_korea_restoration_army","ageId":"kingdoms","year":661,"theme":"korea","title":"Loyalists in the Hills","description":"After the fall of your allies' capital, scattered loyalists hold mountain forts and beg for your support. Backing them angers the powerful Tang and Silla alliance.","options":[{"label":"Arm the loyalists openly","effects":{"iron":-50,"militaryStrengthBonus":0.06}},{"label":"Send quiet gold only","effects":{"gold":-80}},{"label":"Abandon them to their fate","effects":{"controlPenalty":5}}]},{"id":"ai_korea_khitan_demands","ageId":"kingdoms","year":993,"theme":"korea","title":"The Khitan Envoy's Demand","description":"A Khitan army camps on your northern frontier and demands you cut ties with the Song. A shrewd minister believes clever talks could even win you land.","options":[{"label":"Negotiate and seek border lands","effects":{"controlBonus":8}},{"label":"Meet them in the field","effects":{"hr":-90,"militaryStrengthBonus":0.08}},{"label":"Submit and pay tribute","effects":{"gold":-130}}]},{"id":"ai_korea_island_refuge","ageId":"kingdoms","year":1232,"theme":"korea","title":"Flight to the Island","description":"Mongol horsemen ravage the peninsula but cannot cross the sea. Your court could withdraw to an island fortress, leaving farmers on the mainland to endure alone.","options":[{"label":"Move the court to the island","effects":{"defenseBonus":0.1,"controlPenalty":12}},{"label":"Fight on from mountain fortresses","effects":{"hr":-120,"controlBonus":6}}]},{"id":"ai_korea_metal_type","ageId":"kingdoms","year":1377,"theme":"korea","title":"Letters Cast in Metal","description":"Monks at a local temple have cast movable type in bronze to print Buddhist teachings. Expanding the work would spread learning, but it consumes precious copper.","options":[{"label":"Fund a royal type foundry","effects":{"copper":-50,"gold":-50,"techPoints":40}},{"label":"Leave it to the temple","effects":{"copper":-20,"techPoints":10}},{"label":"Melt the copper for coin","effects":{"gold":70,"controlPenalty":4}}]},{"id":"ai_nile_semna_cataract_forts","ageId":"bronze","year":-1860,"theme":"nile","title":"Forts at the Cataract","description":"Egyptian mud-brick fortresses now guard the Second Cataract, and a boundary stela forbids your boats to pass north except to trade.","options":[{"label":"Trade at their markets under their terms","effects":{"gold":70,"controlPenalty":5}},{"label":"Raid the river convoys from the desert","effects":{"hr":-40,"militaryStrengthBonus":0.05}},{"label":"Build walls of your own upstream","effects":{"gold":-90,"defenseBonus":0.08}}]},{"id":"ai_nile_western_deffufa","ageId":"bronze","year":-1700,"theme":"nile","title":"Raising the Great Deffufa","description":"Your priests ask that the great mud-brick temple at the heart of the city be raised higher, so that every caravan sees the might of your kings.","options":[{"label":"Raise it higher than ever before","effects":{"gold":-100,"controlBonus":8}},{"label":"Spend the bricks on granaries instead","effects":{"gold":-40,"hr":30,"controlPenalty":4}}]},{"id":"ai_nile_hyksos_envoy","ageId":"bronze","year":-1555,"theme":"nile","title":"A Letter from Avaris","description":"The Hyksos king in the delta sends a messenger through the oases, urging you to strike Thebes from the south while he strikes from the north.","options":[{"label":"March north against Thebes","effects":{"hr":-60,"militaryStrengthBonus":0.08,"gold":60}},{"label":"Feast the envoy but send no army","effects":{}}]},{"id":"ai_nile_ships_from_kemet","ageId":"bronze","year":-1470,"theme":"nile","title":"Ships from the North","description":"Five great Egyptian ships beach on your shore, their envoys offering beads, axes and daggers for myrrh, ebony, gold and even living incense trees.","options":[{"label":"Trade freely, trees and all","effects":{"gold":90,"controlPenalty":5}},{"label":"Sell resin but keep the trees","effects":{"gold":40}}]},{"id":"ai_nile_peru_nefer_shipyards","ageId":"bronze","year":-1420,"theme":"nile","title":"The Shipyards of Peru-nefer","description":"The royal dockyard by the city wants Lebanese cedar and foreign craftsmen to build warships for campaigns up the Levantine coast.","options":[{"label":"Import cedar and foreign shipwrights","effects":{"gold":-120,"militaryStrengthBonus":0.1}},{"label":"Build river barges from local acacia","effects":{"gold":-40,"techPoints":15}}]},{"id":"ai_nile_libu_sea_alliance","ageId":"bronze","year":-1208,"theme":"nile","title":"Allies from the Sea","description":"Famine grips your tribes, and northern raiders from the sea offer to join you in seizing the fertile western delta, with your wives and herds following behind.","options":[{"label":"Lead the whole host into Egypt","effects":{"hr":-80,"militaryStrengthBonus":0.1,"controlPenalty":8}},{"label":"Send only raiders, keep families home","effects":{"hr":-30,"gold":50}}]},{"id":"ai_nile_tomb_builders_strike","ageId":"bronze","year":-1157,"theme":"nile","title":"The Rations Are Late","description":"The royal tomb builders have laid down their tools and sat behind the temples, crying that their grain has not come for eighteen days.","options":[{"label":"Open temple granaries to pay them","effects":{"gold":-80,"controlBonus":6}},{"label":"Send the police to drive them back","effects":{"controlPenalty":10,"techPoints":-10}}]},{"id":"ai_nile_libyan_chiefs_delta","ageId":"bronze","year":-943,"theme":"nile","title":"Chiefs of the Ma","description":"Your kin, settled for generations as soldiers in the delta, now hold whole towns, and one of their chiefs at Bubastis eyes the throne itself.","options":[{"label":"Back your kinsman's bid for the crown","effects":{"hr":-50,"controlPenalty":6}},{"label":"Stay herders of the western desert","effects":{"gold":30}}]},{"id":"ai_monsoon_palembang_refinery_raid","ageId":"modern","year":1942,"theme":"monsoon","title":"Paratroopers Over the Refineries","description":"Enemy paratroopers are dropping on the oil refineries outside Palembang. Your engineers can still wreck the installations before they fall, but that will cost years of output.","options":[{"label":"Blow up the refineries","effects":{"oil":-50,"gold":-80,"defenseBonus":0.1}},{"label":"Defend them at all costs","effects":{"hr":-60,"militaryStrengthBonus":40,"oil":50}}]},{"id":"ai_monsoon_balangay_boats_found","ageId":"modern","year":1976,"theme":"monsoon","title":"Ancient Boats in the Mud","description":"Diggers near Butuan have uncovered wooden plank boats centuries old, buried in the riverside mud. Developers want the land cleared; scholars want it protected.","options":[{"label":"Fund a full excavation","effects":{"gold":-90,"techPoints":40}},{"label":"Let construction go ahead","effects":{"gold":70,"controlPenalty":5}}]},{"id":"ai_monsoon_lake_condah_land_return","ageId":"modern","year":1987,"theme":"monsoon","title":"The Lake Condah Lands","description":"After long campaigning, the Gunditjmara are offered the return of the old mission lands near Lake Condah, where their ancestors built stone eel traps. Farmers nearby protest the transfer.","options":[{"label":"Return the land","effects":{"controlBonus":8,"gold":-60}},{"label":"Offer cash compensation instead","effects":{"gold":-120,"controlPenalty":6}}]},{"id":"ai_monsoon_oc_eo_excavation","ageId":"modern","year":1944,"theme":"monsoon","title":"The Mound at Oc Eo","description":"An archaeologist asks for laborers to dig a mound in the Mekong delta, where Roman coins and Indian seals point to a lost Funan port. The war needs those same hands.","options":[{"label":"Lend the laborers","effects":{"hr":-30,"techPoints":35}},{"label":"Keep the men for the war effort","effects":{"militaryStrengthBonus":25}}]},{"id":"ai_monsoon_cham_refugees","ageId":"modern","year":1979,"theme":"monsoon","title":"Cham Refugees at the Border","description":"Cham Muslim families who survived years of persecution are fleeing across the border, seeking shelter. Taking them in strains your stores; turning them away shames you abroad.","options":[{"label":"Open the camps","effects":{"gold":-100,"hr":40}},{"label":"Close the border","effects":{"controlBonus":5}},{"label":"Pass them to a third country","effects":{"gold":-40}}]},{"id":"ai_monsoon_tondo_foreshore_relocation","ageId":"modern","year":1974,"theme":"monsoon","title":"The Tondo Foreshore","description":"Planners want to clear the crowded shanties on the Tondo foreshore for a port expansion. Organized residents vow to resist eviction.","options":[{"label":"Clear the shanties for the port","effects":{"gold":150,"controlPenalty":10}},{"label":"Upgrade homes in place","effects":{"gold":-120,"controlBonus":7}}]},{"id":"ai_monsoon_revolutionary_capital","ageId":"modern","year":1946,"theme":"monsoon","title":"A Capital in the Heartland","description":"With enemy troops holding the coast, the young republic moves its government inland to the old Mataram heartland around Yogyakarta. The city must feed and shelter it.","options":[{"label":"Host the government","effects":{"gold":-80,"controlBonus":10,"defenseBonus":0.08}},{"label":"Keep the court's autonomy","effects":{"gold":50,"controlPenalty":8}}]},{"id":"ai_monsoon_hung_temple_oath","ageId":"modern","year":1954,"theme":"monsoon","title":"Oath at the Hung Temple","description":"Soldiers marching home pause at the temple of the Hung Kings, where your leader tells them the founders built the country and they must keep it. Restoring the shrine would cost scarce funds.","options":[{"label":"Restore the temple","effects":{"gold":-70,"controlBonus":9}},{"label":"Spend the money on rebuilding","effects":{"gold":-30,"hr":30,"controlPenalty":3}}]},{"id":"ai_japan_tribute_to_jin","ageId":"classical","year":266,"theme":"japan","title":"Envoys Across the Sea","description":"Your court prepares a mission to the new Jin court in China, as Himiko once sent envoys to Wei. Pearls, jade and fine cloth are expected as tribute.","options":[{"label":"Send rich tribute and many attendants","effects":{"gold":-100}},{"label":"Send a small, modest mission","effects":{"gold":-30}},{"label":"Keep the treasure at home","effects":{"gold":40}}]},{"id":"ai_japan_peninsula_iron","ageId":"classical","year":250,"theme":"japan","title":"Iron From the Peninsula","description":"Iron ingots from the southern Korean peninsula are prized by every chieftain in Wa. Traders demand high prices, and rivals compete for the same boats.","options":[{"label":"Pay the traders their price","effects":{"gold":-80,"iron":50}},{"label":"Send warriors to guard the sea lanes","effects":{"hr":-40,"iron":40,"militaryStrengthBonus":20}},{"label":"Make do with stone and bronze","effects":{"techPoints":-10,"gold":30}}]},{"id":"ai_japan_great_keyhole_mound","ageId":"classical","year":260,"theme":"japan","title":"A Mound for the Queen","description":"The priests of Makimuku call for a vast keyhole-shaped tomb to honor the late queen. It would take thousands of laborers through many seasons.","options":[{"label":"Raise the greatest mound ever seen","effects":{"hr":-60,"gold":-50,"controlBonus":12}},{"label":"Build a modest round mound","effects":{"hr":-20,"controlBonus":4}},{"label":"Keep the laborers in the rice fields","effects":{"gold":40,"controlPenalty":6}}]},{"id":"ai_japan_bronze_bells","ageId":"classical","year":-100,"theme":"japan","title":"The Bronze Bells","description":"Villages cast great bronze bells for rice rituals and bury them on hillsides. Your smiths say the metal would make far better spearheads and mirrors.","options":[{"label":"Melt the bells for weapons","effects":{"copper":50,"militaryStrengthBonus":15,"controlPenalty":5}},{"label":"Cast larger bells for the rites","effects":{"copper":-30,"controlBonus":8}}]},{"id":"ai_japan_rice_reaches_north","ageId":"classical","year":-200,"theme":"japan","title":"Rice Reaches the North","description":"Newcomers from the south show your people how to flood paddies and grow rice. The harvests could be rich, but the cold summers often fail.","options":[{"label":"Clear the marshes for paddies","effects":{"hr":-30,"gold":60,"techPoints":15}},{"label":"Keep to hunting, fishing and chestnuts","effects":{"controlBonus":6,"techPoints":-10}}]},{"id":"ai_japan_young_queen_tested","ageId":"classical","year":248,"theme":"japan","title":"The Young Queen","description":"After Himiko's death, a male king failed and the land fell into strife. Now you rule at thirteen, and the chieftains watch for weakness.","options":[{"label":"Shower the chieftains with gifts","effects":{"gold":-60,"controlBonus":8}},{"label":"March warriors through the rebel villages","effects":{"hr":-40,"militaryStrengthBonus":25,"controlPenalty":5}},{"label":"Seek a Chinese envoy's blessing","effects":{"controlBonus":6}}]},{"id":"ai_japan_horses_from_south","ageId":"classical","year":470,"theme":"japan","title":"Horses From the South","description":"Riders from the southern kingdoms bring horses, newly raised in pastures far to the south. Traders at Isawa offer foals in exchange for furs and hawks.","options":[{"label":"Trade furs for breeding stock","effects":{"gold":-70,"militaryStrengthBonus":35}},{"label":"Raid the traders' herds","effects":{"hr":-25,"militaryStrengthBonus":20}},{"label":"Refuse the strange beasts","effects":{"gold":30,"techPoints":-10}}]},{"id":"ai_japan_tombs_creep_north","ageId":"classical","year":480,"theme":"japan","title":"Tombs on the Border","description":"Burial mounds of southern lords now rise ever closer to your valleys, and their settlers clear your hunting forests. Your elders demand an answer.","options":[{"label":"Raid the settlements before they grow","effects":{"hr":-30,"militaryStrengthBonus":25}},{"label":"Trade furs and seek peace","effects":{"controlPenalty":6}},{"label":"Fortify the mountain passes","effects":{"gold":-50,"defenseBonus":0.1}}]},{"id":"ai_americas_highland_outposts","ageId":"kingdoms","year":650,"theme":"americas","title":"Stone Outposts in the Valleys","description":"Your governors want walled administrative centers like Pikillacta, linked by roads, to store tribute and host feasts that bind distant valley lords to Huari.","options":[{"label":"Build the walled centers","effects":{"gold":-140,"controlBonus":12}},{"label":"Rely on feasts and gifts alone","effects":{"gold":-60,"controlPenalty":5}}]},{"id":"ai_americas_great_house_timber","ageId":"kingdoms","year":1050,"theme":"americas","title":"Timber for the Great House","description":"Extending the great house needs thousands of pine beams, carried on foot from mountains dozens of miles away across the dry canyon country.","options":[{"label":"Send work parties to the mountains","effects":{"hr":-60,"controlBonus":8,"techPoints":10}},{"label":"Trade turquoise for beams instead","effects":{"gold":-110}}]},{"id":"ai_americas_victory_over_calakmul","ageId":"kingdoms","year":695,"theme":"americas","title":"The Snake Kingdom Falters","description":"Your warriors have beaten Calakmul's king in battle, ending decades of humiliation. Its allies waver, but pressing the war could exhaust Mutal.","options":[{"label":"Strike at Calakmul's allies now","effects":{"hr":-80,"militaryStrengthBonus":0.1,"gold":80}},{"label":"Celebrate with new temples","effects":{"gold":-120,"controlBonus":10}}]},{"id":"ai_americas_war_with_hunza","ageId":"kingdoms","year":1480,"theme":"americas","title":"War With the Zaque","description":"The zaque of Hunza contests your hold on the highlands and their salt and emerald trade. Your nobles urge a campaign north.","options":[{"label":"March against Hunza","effects":{"hr":-90,"militaryStrengthBonus":0.08,"controlBonus":6}},{"label":"Offer gold at Lake Guatavita","effects":{"gold":-100}}]},{"id":"ai_americas_shell_canal","ageId":"kingdoms","year":1000,"theme":"americas","title":"A Canal Across the Island","description":"Your engineers propose cutting a canoe canal across Pine Island so tribute and fish can move without the open Gulf, at great cost in labor.","options":[{"label":"Dig the canal","effects":{"hr":-60,"gold":90,"controlBonus":5}},{"label":"Raise shell mounds for defense","effects":{"gold":-50,"defenseBonus":0.08}}]},{"id":"ai_americas_strangers_tribute","ageId":"kingdoms","year":1497,"theme":"americas","title":"The Strangers Demand Tribute","description":"Bearded strangers from across the sea arrive in Jaragua demanding tribute. They have steel and horses, and they have already crushed other caciques.","options":[{"label":"Pay in cotton and cassava","effects":{"gold":-120}},{"label":"Refuse and fortify the villages","effects":{"hr":-60,"defenseBonus":0.1,"controlBonus":5}}]},{"id":"ai_nile_high_dam_financing","ageId":"modern","year":1958,"theme":"nile","title":"Damming the Nile","description":"Your engineers plan a great dam at Aswan to tame the flood and light your cities, but the West has withdrawn its loans and Moscow offers its own.","options":[{"label":"Accept Soviet loans and engineers","effects":{"gold":-150,"techPoints":50}},{"label":"Delay and seek better Western terms","effects":{"gold":-50,"controlPenalty":5}}]},{"id":"ai_nile_suez_nationalized","ageId":"modern","year":1956,"theme":"nile","title":"The Canal Company","description":"The foreign company running the Suez Canal sends its profits abroad. Seizing it would thrill your people, but London and Paris are already massing ships.","options":[{"label":"Nationalize the canal at once","effects":{"gold":150,"controlBonus":10}},{"label":"Negotiate a larger share of tolls","effects":{"controlPenalty":8}}]},{"id":"ai_nile_gezira_cotton","ageId":"modern","year":1925,"theme":"nile","title":"Cotton Between Rivers","description":"A new dam on the Blue Nile could water the plain near Soba for vast cotton fields, but the tenants would answer to the scheme's managers.","options":[{"label":"Fund the canals and cotton scheme","effects":{"gold":-120,"hr":30,"techPoints":20}},{"label":"Leave the land to its farmers","effects":{"controlBonus":5,"techPoints":-10}}]},{"id":"ai_nile_italian_invasion","ageId":"modern","year":1935,"theme":"nile","title":"Fascist Columns Advance","description":"Italian armies with tanks and gas cross your northern border. Your warriors are brave but poorly armed, and the League of Nations debates slowly.","options":[{"label":"Call every province to arms","effects":{"hr":-80,"militaryStrengthBonus":150,"gold":-100}},{"label":"Appeal to the League in Geneva","effects":{"controlPenalty":10}}]},{"id":"ai_nile_desert_oil","ageId":"modern","year":1959,"theme":"nile","title":"Oil Beneath the Sand","description":"Oil has just been struck in the desert to the west, and foreign companies now ask to drill around the Siwa oasis in return for generous royalties.","options":[{"label":"Grant the foreign concession","effects":{"oil":50,"gold":100,"controlPenalty":6}},{"label":"Fund a state survey instead","effects":{"gold":-100,"oil":50,"techPoints":15}}]},{"id":"ai_nile_ogaden_war","ageId":"modern","year":1977,"theme":"nile","title":"The Ogaden Beckons","description":"Your neighbor is torn by revolution, and the herders of the Ogaden speak your tongue. Your generals swear the region can be taken before anyone intervenes.","options":[{"label":"Send the army across the border","effects":{"militaryStrengthBonus":120,"hr":-60}},{"label":"Restrain the generals","effects":{"controlPenalty":10}}]},{"id":"ai_nile_halfa_resettlement","ageId":"modern","year":1964,"theme":"nile","title":"The Drowned Villages","description":"Rising waters behind the new dam downstream are flooding the old Nubian towns, and thousands of displaced families arrive near Kerma seeking land.","options":[{"label":"Build new villages for them","effects":{"gold":-80,"hr":40,"controlPenalty":4}},{"label":"Send them to distant schemes","effects":{"gold":-30,"controlPenalty":10}}]},{"id":"ai_nile_highland_famine","ageId":"modern","year":1984,"theme":"nile","title":"Famine in the Highlands","description":"The rains have failed again and the northern provinces are starving while rebels hold the roads. Foreign cameras and aid agencies wait at your capital.","options":[{"label":"Open the provinces to foreign aid","effects":{"hr":30,"controlPenalty":8}},{"label":"Resettle the starving to the south","effects":{"hr":-60,"controlBonus":10}}]},{"id":"ai_steppe_karakum_canal","ageId":"modern","year":1954,"theme":"steppe","title":"Canal Across the Karakum","description":"Engineers propose diverting the Amu Darya through hundreds of kilometers of desert to water new cotton fields. The work is vast, and the river downstream will run thinner.","options":[{"label":"Dig the canal at full speed","effects":{"gold":-200,"hr":-40,"techPoints":60}},{"label":"Build a smaller, lined channel","effects":{"gold":-120,"techPoints":30}},{"label":"Leave the river to its course","effects":{"gold":50,"controlPenalty":5}}]},{"id":"ai_steppe_aral_cotton_quota","ageId":"modern","year":1962,"theme":"steppe","title":"White Gold, Shrinking Sea","description":"Planners raise the cotton quota for the lower Amu Darya, and the fields around Kath swallow ever more water. Fishermen on the Aral already see the shore retreating.","options":[{"label":"Meet the quota whatever the cost","effects":{"gold":180,"controlPenalty":8}},{"label":"Quietly underreport and spare water","effects":{"gold":40,"controlPenalty":4}},{"label":"Petition for a lower quota","effects":{"controlBonus":6}}]},{"id":"ai_steppe_basmachi_revolt","ageId":"modern","year":1922,"theme":"steppe","title":"Riders in the Hills","description":"Basmachi bands strike from the valleys around Samarkand, cutting rail lines and rallying villages against the new Soviet order. Repression may fuel them; concessions may embolden them.","options":[{"label":"Send cavalry to crush them","effects":{"militaryStrengthBonus":60,"hr":-30,"controlPenalty":6}},{"label":"Reopen mosques and bazaars","effects":{"gold":-60,"controlBonus":8}},{"label":"Fortify the city and wait","effects":{"gold":-80,"defenseBonus":0.1}}]},{"id":"ai_steppe_virgin_lands","ageId":"modern","year":1954,"theme":"steppe","title":"Plowing the Virgin Lands","description":"Moscow calls for millions of hectares of steppe pasture to be turned into wheat, with volunteers arriving by the trainload. The soil is rich now, but the winds are strong.","options":[{"label":"Plow every hectare offered","effects":{"gold":200,"hr":50,"controlPenalty":7}},{"label":"Plow but plant windbreaks","effects":{"gold":90,"techPoints":20,"hr":-10}},{"label":"Protect the herders' pastures","effects":{"controlBonus":5}}]},{"id":"ai_steppe_lop_nur_test","ageId":"modern","year":1959,"theme":"steppe","title":"Fire at Lop Nur","description":"The dry lakebed near the ruins of Loulan is chosen for a nuclear test site. The program promises power and prestige, but the desert winds carry what the blasts leave behind.","options":[{"label":"Host the test site","effects":{"techPoints":90,"militaryStrengthBonus":100,"hr":-30}},{"label":"Demand compensation for nearby oases","effects":{"gold":80}},{"label":"Evacuate the surrounding villages","effects":{"gold":-90,"controlBonus":5}}]},{"id":"ai_steppe_arkaim_reservoir","ageId":"modern","year":1987,"theme":"steppe","title":"The Valley Before the Flood","description":"Archaeologists have found a ringed Bronze Age settlement at Arkaim, in a valley slated to become a reservoir for irrigation. The dam is nearly ready.","options":[{"label":"Flood the valley as planned","effects":{"gold":120,"techPoints":-20}},{"label":"Cancel the reservoir, make a reserve","effects":{"gold":-100,"techPoints":50}},{"label":"Delay one season for excavation","effects":{"gold":-40,"techPoints":25}}]},{"id":"ai_steppe_mongolian_revolution","ageId":"modern","year":1921,"theme":"steppe","title":"Red Partisans in Urga","description":"Mongol revolutionaries backed by Soviet troops drive out the White Russian warlord and offer a new people's government. Their protection comes with Moscow's advisers.","options":[{"label":"Embrace Soviet protection","effects":{"militaryStrengthBonus":80,"controlPenalty":6}},{"label":"Keep the Bogd Khan as figurehead","effects":{"controlBonus":8}},{"label":"Seek Chinese recognition instead","effects":{}}]},{"id":"ai_steppe_afghan_war","ageId":"modern","year":1980,"theme":"steppe","title":"Columns on the Amu Darya","description":"Soviet columns cross the river and pour south past Balkh, while mujahideen gather in the mountains with foreign weapons. The city must choose whom to shelter.","options":[{"label":"Garrison the city for the Soviets","effects":{"defenseBonus":0.1,"controlPenalty":10}},{"label":"Shelter the mujahideen quietly","effects":{"hr":-40,"militaryStrengthBonus":60}},{"label":"Negotiate a local truce","effects":{"gold":-100,"controlBonus":6}}]},{"id":"ai_japan_flame_pottery","ageId":"stone","year":-3000,"theme":"japan","title":"Flames of Clay","description":"The potters of your village by the great river shape vessels with rims like leaping fire. Each takes days to make, and the hunters ask why clay needs such work.","options":[{"label":"Honor the potters and feed their craft","effects":{"gold":-40,"techPoints":15}},{"label":"Order plain pots for storing nuts","effects":{"gold":30,"controlPenalty":4}}]},{"id":"ai_japan_chestnut_groves","ageId":"stone","year":-3500,"theme":"japan","title":"The Chestnut Groves","description":"Your people have learned that chestnut trees near the village give more each autumn if the forest around them is cleared. But the deer live in that forest.","options":[{"label":"Clear the woods and tend the groves","effects":{"gold":-30,"hr":25}},{"label":"Keep the forest for the hunt","effects":{"militaryStrengthBonus":10,"gold":-10}}]},{"id":"ai_japan_obsidian_crossing","ageId":"stone","year":-4000,"theme":"japan","title":"Black Glass Across Water","description":"The sharpest obsidian comes from an island far across the sea, reached only by dugout canoe. Some of your young men are willing to paddle there.","options":[{"label":"Send the canoes across the sea","effects":{"hr":-15,"gold":60}},{"label":"Buy it from the coastal villages","effects":{"gold":-25}}]},{"id":"ai_japan_green_jade","ageId":"stone","year":-3500,"theme":"japan","title":"Green Stone of Itoigawa","description":"Traders bring polished green jade from a river in the west, hard to work and rare. The elders of Isawa want it to mark who leads.","options":[{"label":"Trade furs for jade for the elders","effects":{"gold":-50,"controlBonus":8}},{"label":"Turn the traders away","effects":{"gold":20}}]},{"id":"ai_japan_rising_sea","ageId":"stone","year":-4000,"theme":"japan","title":"The Sea Comes Inland","description":"The sea has crept up the valleys, drowning old camps and making shallow bays rich with clams. Your people must choose where to live.","options":[{"label":"Move up to the dry terraces","effects":{"gold":-40,"defenseBonus":0.05}},{"label":"Settle the shores and gather shellfish","effects":{"gold":40,"controlPenalty":5}}]},{"id":"ai_japan_clay_figures","ageId":"stone","year":-2500,"theme":"japan","title":"The Broken Figures","description":"The healers shape small clay figures with wide eyes, then break them to carry away sickness. They ask you for food to fund the rites.","options":[{"label":"Give food for the rites","effects":{"gold":-30,"controlBonus":10}},{"label":"Keep the stores for winter","effects":{"gold":20,"controlPenalty":6}}]},{"id":"ai_japan_great_pillars","ageId":"stone","year":-3000,"theme":"japan","title":"Pillars of Chestnut","description":"The village has grown large, and some want to raise a hall on six giant chestnut trunks, seen from far off. Felling and hauling them will take every hand.","options":[{"label":"Raise the great pillars","effects":{"hr":-20,"controlBonus":12}},{"label":"Build more pit houses instead","effects":{"gold":-20,"hr":15}}]},{"id":"ai_japan_bubble_burst","ageId":"information","year":1991,"theme":"japan","title":"The Bubble Bursts","description":"Land and stock prices that seemed eternal collapse together. Banks of the Yamatai sit on loans that will never be repaid.","options":[{"label":"Force banks to write off bad loans","effects":{"gold":-250,"controlBonus":5}},{"label":"Quietly prop up the zombie banks","effects":{"gold":-80,"techPoints":-20,"controlPenalty":6}}]},{"id":"ai_japan_hanshin_earthquake","ageId":"information","year":1995,"theme":"japan","title":"The Great Hanshin Earthquake","description":"Before dawn a quake levels much of the Kansai coast around Kobe. Volunteers pour in faster than the slow official relief.","options":[{"label":"Fund a full rebuild to new codes","effects":{"gold":-200,"defenseBonus":0.1}},{"label":"Lean on volunteers and local funds","effects":{"hr":-60,"controlPenalty":8}}]},{"id":"ai_japan_tohoku_tsunami","ageId":"information","year":2011,"theme":"japan","title":"Wave Over Tohoku","description":"A great earthquake and tsunami strike the northeast coast near Isawa, and a nuclear plant to the south melts down. The nation doubts its reactors.","options":[{"label":"Shut the reactors, import fuel","effects":{"oil":-50,"gold":-100,"controlBonus":6}},{"label":"Restart reactors after inspections","effects":{"gold":60,"controlPenalty":10}}]},{"id":"ai_japan_emptying_villages","ageId":"information","year":2014,"theme":"japan","title":"The Emptying Villages","description":"Young Emishi leave the northern valleys for the capital, and schools close one by one. Whole villages are left to the elderly.","options":[{"label":"Subsidize families to stay rural","effects":{"gold":-150,"hr":40}},{"label":"Admit foreign workers to farms","effects":{"hr":60,"controlPenalty":7}},{"label":"Let the cities absorb them","effects":{"gold":50,"hr":-40}}]},{"id":"ai_japan_asteroid_probe","ageId":"information","year":2003,"theme":"japan","title":"A Probe to an Asteroid","description":"Your space scientists propose a small craft to land on an asteroid and return a sample. Nobody has ever done it, and budgets are tight.","options":[{"label":"Fund the daring mission","effects":{"gold":-180,"techPoints":90}},{"label":"Join a foreign partner's program","effects":{"gold":-60,"techPoints":30}}]},{"id":"ai_japan_three_arrows","ageId":"information","year":2013,"theme":"japan","title":"Three Arrows of Reform","description":"Advisors urge you to end two decades of deflation with cheap money, heavy spending and structural reform at once.","options":[{"label":"Loose every arrow together","effects":{"gold":-220,"techPoints":40,"controlBonus":8}},{"label":"Print money, skip painful reforms","effects":{"gold":120,"controlPenalty":5}}]},{"id":"ai_japan_subway_cult_attack","ageId":"information","year":1995,"theme":"japan","title":"Gas in the Subway","description":"A doomsday cult releases nerve gas on crowded morning trains. The Yamatai demand answers, but many fear police power over religion.","options":[{"label":"Grant police sweeping new powers","effects":{"gold":-80,"controlBonus":10}},{"label":"Prosecute the cult, protect religious freedom","effects":{"gold":-40}}]},{"id":"ai_japan_mobile_internet","ageId":"information","year":1999,"theme":"japan","title":"Internet in Every Pocket","description":"A phone carrier offers mail and web pages on handsets years ahead of the world. You must choose a domestic standard or a global one.","options":[{"label":"Back the homegrown standard","effects":{"techPoints":60,"gold":-100}},{"label":"Adopt open global standards","effects":{"techPoints":25,"gold":-40}}]},{"id":"ai_maghreb_barqa_tribute_treaty","ageId":"kingdoms","year":643,"theme":"maghreb","title":"Terms From Amr's Army","description":"Arab horsemen under Amr ibn al-As have overrun Barqa. Their envoys offer peace for a yearly tribute of thousands of dinars, or war against your crumbling walls.","options":[{"label":"Accept the tribute and keep your towns","effects":{"gold":-150}},{"label":"Man the old walls and resist","effects":{"hr":-80,"defenseBonus":0.08}}]},{"id":"ai_maghreb_foggara_tunnels_dry","ageId":"kingdoms","year":668,"theme":"maghreb","title":"The Foggaras Run Dry","description":"The underground water channels that fed Garama's fields yield less each year, and Arab raiders under Uqba ibn Nafi now press the oases.","options":[{"label":"Dig deeper channels with forced labor","effects":{"hr":-60,"gold":-50,"controlBonus":6}},{"label":"Abandon outer fields and trade for grain","effects":{"gold":-90,"controlPenalty":5}}]},{"id":"ai_maghreb_idris_at_volubilis","ageId":"kingdoms","year":788,"theme":"maghreb","title":"A Fugitive Sharif Arrives","description":"Idris, a descendant of the Prophet fleeing the Abbasids, reaches Volubilis. The Awraba Berbers want to proclaim him imam, which will anger Baghdad.","options":[{"label":"Proclaim Idris and rally the tribes","effects":{"controlBonus":10}},{"label":"Shelter him quietly without a title","effects":{"gold":-40}},{"label":"Send him away to avoid trouble","effects":{"techPoints":-10,"controlPenalty":5}}]},{"id":"ai_maghreb_banu_hilal_arrive","ageId":"kingdoms","year":1052,"theme":"maghreb","title":"The Banu Hilal Come West","description":"Bedouin tribes loosed by the Fatimids pour across Ifriqiya, grazing herds over farmland and plundering towns around Constantine.","options":[{"label":"Pay them to graze elsewhere","effects":{"gold":-120,"controlBonus":5}},{"label":"Fight them in the open plains","effects":{"hr":-100,"militaryStrengthBonus":0.05}},{"label":"Retreat behind Constantine's cliffs","effects":{"defenseBonus":0.1,"controlPenalty":10}}]},{"id":"ai_maghreb_merchant_quarter","ageId":"kingdoms","year":1068,"theme":"maghreb","title":"The Merchants' Town","description":"Muslim traders from the north have built a stone town with twelve mosques beside your royal city. They ask for lower duties on salt and gold.","options":[{"label":"Lower the duties to draw more caravans","effects":{"gold":-60,"techPoints":10}},{"label":"Keep the king's share of every nugget","effects":{"gold":100}}]},{"id":"ai_maghreb_almoravid_pressure","ageId":"kingdoms","year":1055,"theme":"maghreb","title":"Veiled Warriors From Sahara","description":"The Almoravids have taken Awdaghust and now threaten your northern trade routes, demanding that your court embrace their strict Islam.","options":[{"label":"Convert the court and make peace","effects":{"controlPenalty":8}},{"label":"Raise the archers and hold the Sahel","effects":{"hr":-90,"militaryStrengthBonus":0.06}}]},{"id":"ai_maghreb_hummay_conversion","ageId":"kingdoms","year":1085,"theme":"maghreb","title":"The Mai Takes Islam","description":"Scholars at court urge your mai to embrace Islam openly, opening ties to Egypt and the Maghreb, while the old shrines' keepers warn of unrest.","options":[{"label":"Convert and invite Muslim scholars","effects":{"techPoints":25,"controlPenalty":6}},{"label":"Honor both faiths in public","effects":{"gold":-50,"controlBonus":4}}]},{"id":"ai_maghreb_old_mound_abandoned","ageId":"kingdoms","year":1350,"theme":"maghreb","title":"Leaving the Old Mound","description":"Families are deserting the ancient mound for the new Muslim town of Djenné nearby, where river trade and scholars now gather.","options":[{"label":"Move the market to the new town","effects":{"gold":-80,"techPoints":20,"controlBonus":5}},{"label":"Hold the old town with its ancestral rites","effects":{"gold":-30,"controlPenalty":7}}]},{"id":"ai_levant_magan_copper_ships","ageId":"stone","year":-2300,"theme":"levant","title":"Copper for Sumer","description":"Reed boats from the rivers of Sumer beach on your shore, asking for the copper smelted in your mountains and offering grain, wool and oil.","options":[{"label":"Open the mines to the foreign ships","effects":{"copper":50,"gold":40,"controlPenalty":4}},{"label":"Sell only small loads at high prices","effects":{"gold":30}}]},{"id":"ai_levant_manium_akkad","ageId":"stone","year":-2250,"theme":"levant","title":"The King of Akkad","description":"The armies of Akkad cross the sea, and their king boasts he will take your copper mountains and carry your stone home as a trophy.","options":[{"label":"Meet them in open battle","effects":{"hr":-40,"militaryStrengthBonus":20}},{"label":"Retreat to the mountains and wait","effects":{"copper":-50,"defenseBonus":0.1}},{"label":"Send tribute and keep your throne","effects":{"gold":-80,"controlPenalty":8}}]},{"id":"ai_levant_bat_stone_towers","ageId":"stone","year":-2600,"theme":"levant","title":"The Round Towers","description":"Your elders want great round towers of cut stone raised beside the wells and palm groves, a work that will take many seasons of labor.","options":[{"label":"Raise the towers by the wells","effects":{"hr":-30,"defenseBonus":0.1,"controlBonus":5}},{"label":"Keep the hands in the date groves","effects":{"gold":40,"controlPenalty":3}}]},{"id":"ai_levant_van_obsidian","ageId":"stone","year":-4500,"theme":"levant","title":"Black Glass of Van","description":"The volcano above the great lake yields black glass that cuts sharper than any flint, and traders from distant villages come to bargain for it.","options":[{"label":"Guard the quarries and set a price","effects":{"gold":50}},{"label":"Trade it freely along the valleys","effects":{"gold":-20}}]},{"id":"ai_levant_kura_araxes_hearths","ageId":"stone","year":-3300,"theme":"levant","title":"Hearths of the Highland","description":"Herders with burnished black pottery and round houses spread through your valleys, moving flocks between summer pastures and winter villages.","options":[{"label":"Join them on the high pastures","effects":{"hr":20,"controlPenalty":5}},{"label":"Settle them in walled villages","effects":{"gold":-30,"controlBonus":6}}]},{"id":"ai_levant_colchis_arsenic_copper","ageId":"stone","year":-3000,"theme":"levant","title":"The Hard Copper","description":"Your smiths find that certain mountain ores make copper harder and brighter, but the fumes of the furnace sicken the men who tend it.","options":[{"label":"Fire the furnaces day and night","effects":{"copper":50,"techPoints":10,"hr":-20}},{"label":"Work the ore only in small batches","effects":{"techPoints":5,"gold":-20}}]},{"id":"ai_levant_ugarit_coastal_village","ageId":"stone","year":-4000,"theme":"levant","title":"Mound by the Sea","description":"Your village on its mound by the harbor has grown crowded, and families argue whether to clear new fields inland or take to the sea for fish.","options":[{"label":"Clear new fields in the hills","effects":{"gold":30,"controlPenalty":4}},{"label":"Build boats and fish the coast","effects":{"hr":-15,"techPoints":10}}]},{"id":"ai_levant_saba_flood_channels","ageId":"stone","year":-2500,"theme":"levant","title":"Taming the Flash Floods","description":"Rare rains send torrents roaring down the wadis, and your farmers propose earthen walls and channels to spread the water over the fields.","options":[{"label":"Dig the channels across the wadi","effects":{"hr":-25,"gold":50,"techPoints":5}},{"label":"Keep to herding and wild grazing","effects":{"gold":-20,"controlPenalty":3}}]},{"id":"ai_nile_longinus_mission","ageId":"kingdoms","year":580,"theme":"nile","title":"The Missionary From Alexandria","description":"A bishop named Longinus has crossed the deserts to your court, offering baptism and ties to the Miaphysite church of Alexandria. Your priests of the old gods grumble.","options":[{"label":"Accept baptism for the royal house","effects":{"controlPenalty":8}},{"label":"Welcome him but keep the old rites","effects":{"gold":-30}},{"label":"Send him back down the Nile","effects":{"controlBonus":5}}]},{"id":"ai_nile_baqt_treaty","ageId":"kingdoms","year":652,"theme":"nile","title":"Terms at the Cataract","description":"Arab armies from Egypt besieged Dongola and failed to break it. Their commander now proposes a pact: yearly tribute of captives in exchange for grain, cloth and peace.","options":[{"label":"Sign the pact and send the captives","effects":{"hr":-40,"gold":60}},{"label":"Refuse and man the walls","effects":{"defenseBonus":0.1,"hr":-70}}]},{"id":"ai_nile_memphis_quarry","ageId":"kingdoms","year":975,"theme":"nile","title":"Stones of the Old Capital","description":"Builders of the new capital across the river want the ancient temples of Men-nefer for cut stone. The ruins are cheap to haul and endless.","options":[{"label":"Let the masons strip the ruins","effects":{"gold":80,"techPoints":-15}},{"label":"Open new quarries in the hills","effects":{"gold":-90,"techPoints":20}}]},{"id":"ai_nile_great_calamity","ageId":"kingdoms","year":1067,"theme":"nile","title":"The Nile Fails Again","description":"For the third year the flood has stayed low. Granaries are emptying, bread prices soar, and unpaid soldiers loot the markets of the capital.","options":[{"label":"Empty the treasury to buy grain","effects":{"gold":-150,"controlBonus":8}},{"label":"Pay the soldiers first","effects":{"gold":-80,"hr":-60,"militaryStrengthBonus":0.05}},{"label":"Let the provinces fend for themselves","effects":{"hr":-100,"controlPenalty":12}}]},{"id":"ai_nile_shali_fortress","ageId":"kingdoms","year":1203,"theme":"nile","title":"A Fortress of Salt Mud","description":"Desert raiders have thinned the families of Siwa to a few hundred. Elders propose abandoning the scattered villages for one walled hill town built of salt and mud.","options":[{"label":"Build the walled town together","effects":{"gold":-70,"defenseBonus":0.1}},{"label":"Hire Bedouin guards instead","effects":{"gold":-100,"controlPenalty":5}}]},{"id":"ai_nile_rock_churches","ageId":"kingdoms","year":1200,"theme":"nile","title":"Churches Carved From Rock","description":"Your king dreams of a new Jerusalem in the highlands, with churches hewn whole from the living rock. It will take thousands of workers for decades.","options":[{"label":"Carve the holy city","effects":{"hr":-80,"gold":-60,"controlBonus":12}},{"label":"Build a few modest chapels","effects":{"gold":-30,"controlBonus":4}}]},{"id":"ai_nile_persian_merchants","ageId":"kingdoms","year":1000,"theme":"nile","title":"Merchants From Across the Sea","description":"Traders from Persia and Arabia ask to settle in Mogadishu, build a mosque and trade cloth for gum and ivory. Local clans fear losing their grip on the harbor.","options":[{"label":"Grant them a quarter by the harbor","effects":{"gold":120,"controlPenalty":7}},{"label":"Allow trade but no settlement","effects":{"gold":40}}]},{"id":"ai_nile_nomads_at_soba","ageId":"kingdoms","year":1450,"theme":"nile","title":"Herders at the Gates","description":"Arab herding clans push their camels into the pastures around Soba, and the old churches stand half empty. Some chiefs offer service in return for grazing rights.","options":[{"label":"Grant grazing for military service","effects":{"militaryStrengthBonus":0.06,"controlPenalty":10}},{"label":"Drive them from the river lands","effects":{"hr":-60,"controlBonus":6}},{"label":"Tax their herds and look away","effects":{"gold":70}}]},{"id":"ai_mesopotamia_ugarit_palace_visit","ageId":"bronze","year":-1765,"theme":"mesopotamia","title":"A King Asks to Visit","description":"The king of Ugarit has heard of your great palace at Mari and asks, through the court of Aleppo, to come and see it with his own eyes.","options":[{"label":"Host him with a lavish royal welcome","effects":{"gold":-90}},{"label":"Politely delay the visit","effects":{"gold":20}}]},{"id":"ai_mesopotamia_elamite_tin_shipment","ageId":"bronze","year":-1770,"theme":"mesopotamia","title":"Tin From the East","description":"Caravans have brought Elamite tin to Mari, and kings of the west wait to see how you will share it out among them.","options":[{"label":"Gift tin to western allies","effects":{"copper":-40}},{"label":"Sell it at the highest price","effects":{"gold":110,"controlPenalty":5}},{"label":"Keep it for your own bronze smiths","effects":{"gold":-30,"militaryStrengthBonus":0.08}}]},{"id":"ai_mesopotamia_stele_to_susa","ageId":"bronze","year":-1158,"theme":"mesopotamia","title":"Trophies of Babylonia","description":"Your armies have sacked the cities of Babylonia, and among the spoils stand ancient stelae of famous kings. Carrying them home will take men and carts.","options":[{"label":"Haul the stelae to Susa","effects":{"hr":-40,"controlBonus":10}},{"label":"Take only gold and captives","effects":{"gold":120}}]},{"id":"ai_mesopotamia_magan_copper_route","ageId":"bronze","year":-1750,"theme":"mesopotamia","title":"Copper From Magan","description":"Merchants of Ur sail to Dilmun to buy copper shipped from Magan, but they complain of poor quality ingots and threaten to take their silver elsewhere.","options":[{"label":"Inspect and guarantee every ingot","effects":{"gold":-50,"copper":50}},{"label":"Let buyers beware","effects":{"gold":70}}]},{"id":"ai_mesopotamia_temple_of_inzak","ageId":"bronze","year":-1900,"theme":"mesopotamia","title":"The Sacred Spring","description":"Priests of Inzak ask for a new stone temple beside the freshwater spring that sailors believe makes Dilmun blessed.","options":[{"label":"Build the temple in dressed stone","effects":{"gold":-80,"controlBonus":8}},{"label":"Spend the stone on harbor walls","effects":{"gold":-40,"defenseBonus":0.06,"controlPenalty":4}}]},{"id":"ai_mesopotamia_walls_of_kish","ageId":"bronze","year":-1740,"theme":"mesopotamia","title":"The Walls of Kish","description":"Revolts are spreading through the southern cities, and the old walls of Kish stand crumbling. Rebuilding them would demand a season of forced labor.","options":[{"label":"Rebuild the walls with corvée labor","effects":{"hr":-50,"defenseBonus":0.1}},{"label":"Pay hired workers instead","effects":{"gold":-120,"defenseBonus":0.08}},{"label":"Trust the field army","effects":{"controlPenalty":8}}]},{"id":"ai_mesopotamia_new_holy_city","ageId":"bronze","year":-1250,"theme":"mesopotamia","title":"A City for the Gods","description":"Your architects propose a new holy city with a towering ziggurat, uniting the gods of the highlands and the lowlands in one sacred place.","options":[{"label":"Raise the ziggurat and temples","effects":{"gold":-150,"hr":-30,"controlBonus":12}},{"label":"Honor the old shrines of Susa","effects":{"gold":-30,"controlPenalty":5}}]},{"id":"ai_mesopotamia_akkadian_letters","ageId":"bronze","year":-1350,"theme":"mesopotamia","title":"The Language of Kings","description":"From Egypt to Hatti, great kings now write to one another in Akkadian on clay tablets, and every court needs scribes trained in your tongue.","options":[{"label":"Send scribes to foreign courts","effects":{"gold":-60}},{"label":"Charge foreigners to train at home","effects":{"gold":60,"techPoints":-10}}]},{"id":"ai_europe_sirmium_tribute","ageId":"kingdoms","year":580,"theme":"europe","title":"Gold From Constantinople","description":"Imperial envoys offer you yearly gold if your horsemen leave the Danube frontier in peace. Your warriors want Sirmium, the fortress city that guards the river crossing.","options":[{"label":"Accept the emperor's gold","effects":{"gold":150,"controlPenalty":6}},{"label":"Besiege Sirmium","effects":{"hr":-80,"militaryStrengthBonus":0.1}}]},{"id":"ai_europe_columba_at_gates","ageId":"kingdoms","year":565,"theme":"europe","title":"A Monk at Your Gate","description":"An Irish abbot from Iona stands before your fortress asking leave to preach among your people. Your druids warn that his god will not share your hall.","options":[{"label":"Open the gates and hear him","effects":{"techPoints":25,"controlPenalty":5}},{"label":"Keep the gates barred","effects":{"controlBonus":6}}]},{"id":"ai_europe_karmsund_toll","ageId":"kingdoms","year":890,"theme":"europe","title":"The Northern Way","description":"Every ship sailing the coast must pass through the narrow Karmsund strait beneath your hall. Merchants grumble at the toll, and some speak of hiring raiders to break it.","options":[{"label":"Raise the toll on passing ships","effects":{"gold":120}},{"label":"Lower it to draw more traders","effects":{"gold":-40}},{"label":"Build longships to guard the strait","effects":{"gold":-90,"defenseBonus":0.1}}]},{"id":"ai_europe_skara_bishopric","ageId":"kingdoms","year":1020,"theme":"europe","title":"A Bishop for Skara","description":"Missionaries from the Danish and English churches ask to seat a bishop in Skara, bringing scribes and Latin learning. Many chieftains still sacrifice at the old groves.","options":[{"label":"Grant land for a cathedral","effects":{"gold":-80,"techPoints":30,"controlPenalty":5}},{"label":"Let them preach but grant nothing","effects":{"techPoints":10,"controlPenalty":3}}]},{"id":"ai_europe_strangford_longships","ageId":"kingdoms","year":840,"theme":"europe","title":"Longships on the Lough","description":"Norse crews have begun wintering on the loughs of your coast instead of sailing home. They raid by spring and trade silver by summer.","options":[{"label":"Gather the warbands and drive them out","effects":{"hr":-70,"defenseBonus":0.08}},{"label":"Trade with them for silver","effects":{"gold":90,"controlPenalty":7}}]},{"id":"ai_europe_andalusian_exiles","ageId":"kingdoms","year":827,"theme":"europe","title":"Exiles From Al-Andalus","description":"A fleet of Andalusian exiles has landed on Crete and is fortifying a camp near the old ruins of Knossos. The imperial governor sends no help.","options":[{"label":"Arm the villagers and resist","effects":{"hr":-60,"defenseBonus":0.1}},{"label":"Pay them to sail elsewhere","effects":{"gold":-130,"controlPenalty":5}}]},{"id":"ai_europe_venetian_protection","ageId":"kingdoms","year":1396,"theme":"europe","title":"The Lion of Saint Mark","description":"With Ottoman raiders pressing from the east, Venice offers to garrison Scodra and its citadel in return for control of the city and its river trade.","options":[{"label":"Hand the city to Venice","effects":{"defenseBonus":0.1,"gold":60,"controlPenalty":12}},{"label":"Hold Scodra with your own men","effects":{"hr":-60,"gold":-70,"controlBonus":8}}]},{"id":"ai_europe_orvieto_cathedral","ageId":"kingdoms","year":1290,"theme":"europe","title":"A Cathedral on the Rock","description":"The bishop and the pope's court ask you to raise a great cathedral atop your volcanic crag. Masons from Siena are ready, but the work will take generations.","options":[{"label":"Fund the cathedral in full","effects":{"gold":-150,"controlBonus":6}},{"label":"Build a modest church instead","effects":{"gold":-40}}]},{"id":"ai_japan_arquebus_arrival","ageId":"gunpowder","year":1543,"theme":"japan","title":"Guns from the South","description":"Portuguese traders blown off course have sold two arquebuses to a southern lord, and smiths across the islands are eager to learn how they are made.","options":[{"label":"Pay smiths to copy them","effects":{"gold":-100,"iron":-40,"militaryStrengthBonus":0.1}},{"label":"Buy finished guns from traders","effects":{"gold":-160,"militaryStrengthBonus":0.06}},{"label":"Trust the bow and spear","effects":{"gold":30}}]},{"id":"ai_japan_jesuit_mission","ageId":"gunpowder","year":1551,"theme":"japan","title":"The Black-Robed Priests","description":"Jesuit missionaries ask to preach in your lands. Their presence draws Portuguese ships and silk, but converts may come to obey a distant faith before you.","options":[{"label":"Welcome them for the trade","effects":{"gold":70,"techPoints":15,"controlPenalty":6}},{"label":"Send them away politely","effects":{"controlBonus":5}}]},{"id":"ai_japan_sword_hunt","ageId":"gunpowder","year":1588,"theme":"japan","title":"The Sword Hunt","description":"Following the regent's example, your officials propose collecting every sword and gun held by the farmers around Kyoto, fixing them to the soil for good.","options":[{"label":"Confiscate all peasant weapons","effects":{"controlBonus":10,"hr":-30}},{"label":"Let villages keep their arms","effects":{"hr":20,"controlPenalty":6}}]},{"id":"ai_japan_pacific_embassy","ageId":"gunpowder","year":1613,"theme":"japan","title":"An Embassy Across Oceans","description":"A northern lord has built a galleon to carry envoys to New Spain and Rome. Isawa's merchants urge you to send men of your own aboard.","options":[{"label":"Fund envoys for the voyage","effects":{"gold":-120,"techPoints":15}},{"label":"Keep your gold at home","effects":{"gold":20}}]},{"id":"ai_japan_salmon_for_rice","ageId":"gunpowder","year":1669,"theme":"japan","title":"Less Rice for Salmon","description":"Southern traders now give far less rice for each bale of salmon and furs, and the northern chiefs talk openly of war against them.","options":[{"label":"Back the chiefs against the traders","effects":{"hr":-40,"gold":-50,"controlBonus":8}},{"label":"Accept the harsher terms","effects":{"gold":50,"controlPenalty":8}}]},{"id":"ai_japan_dutch_anatomy","ageId":"gunpowder","year":1771,"theme":"japan","title":"A Dutch Anatomy Book","description":"Physicians who watched a dissection found a Dutch anatomy text more accurate than the Chinese classics, and they ask your support to translate it.","options":[{"label":"Sponsor the translation","effects":{"gold":-80,"techPoints":40}},{"label":"Uphold the classical teachings","effects":{"controlBonus":4,"techPoints":-10}}]},{"id":"ai_japan_tenmei_famine","ageId":"gunpowder","year":1783,"theme":"japan","title":"Ash and Cold Summers","description":"Volcanic ash and failed harvests have left the north starving, and crowds gather outside Isawa's rice warehouses demanding grain.","options":[{"label":"Open the granaries","effects":{"gold":-100,"hr":40,"controlBonus":5}},{"label":"Sell the rice at famine prices","effects":{"gold":80,"hr":-50,"controlPenalty":10}}]},{"id":"ai_japan_black_ships","ageId":"gunpowder","year":1854,"theme":"japan","title":"The Black Ships Return","description":"American steam warships have returned to demand open ports and coal for their fleet. Their guns outrange anything on your shores.","options":[{"label":"Sign a treaty of friendship","effects":{"gold":60,"controlPenalty":10}},{"label":"Build coastal batteries","effects":{"gold":-120,"iron":-50,"defenseBonus":0.1}}]},{"id":"ai_indic_harappa_mounds","ageId":"modern","year":1921,"theme":"indic","title":"Bricks Beneath Harappa","description":"Diggers at the mounds of Harappa find seals in an unknown script, but local villagers still dig the ancient bricks for their houses.","options":[{"label":"Fund a full excavation","effects":{"gold":-80,"techPoints":40}},{"label":"Let the quarrying continue","effects":{"gold":50}}]},{"id":"ai_indic_bengal_partition","ageId":"modern","year":1905,"theme":"indic","title":"Bengal Cut in Two","description":"The province of Bengal is split along religious lines, and Bengalis answer with a boycott of foreign cloth and mass protests in the streets.","options":[{"label":"Enforce the partition","effects":{"gold":60,"controlPenalty":10}},{"label":"Reunite the province","effects":{"controlBonus":6}}]},{"id":"ai_indic_digboi_refinery","ageId":"modern","year":1901,"theme":"indic","title":"Oil at Digboi","description":"Crude oil seeps from the jungle floor near Digboi in Assam, and engineers propose a refinery deep in the hills.","options":[{"label":"Build the refinery yourself","effects":{"gold":-150,"oil":50}},{"label":"Grant a foreign company the concession","effects":{"gold":100,"oil":40,"controlPenalty":5}}]},{"id":"ai_indic_temple_entry","ageId":"modern","year":1939,"theme":"indic","title":"The Temple Doors Open","description":"Reformers lead Dalit worshippers into the great Meenakshi temple of Madurai, and the priests threaten to abandon the shrine in protest.","options":[{"label":"Protect the new worshippers","effects":{"gold":-40,"controlBonus":8}},{"label":"Side with the priests","effects":{"hr":10,"controlPenalty":10}}]},{"id":"ai_indic_partition_refugees","ageId":"modern","year":1947,"theme":"indic","title":"Columns Across the Border","description":"A new border slices through Punjab, and millions flee in both directions while trains arrive full of the dead.","options":[{"label":"Open camps for every refugee","effects":{"gold":-200,"hr":60}},{"label":"Seal the border with troops","effects":{"defenseBonus":0.05,"controlPenalty":12}}]},{"id":"ai_indic_bihar_earthquake","ageId":"modern","year":1934,"theme":"indic","title":"The Earth Splits Bihar","description":"A great earthquake levels towns across Bihar, burying fields under sand and leaving whole districts homeless in the winter cold.","options":[{"label":"Rebuild from the treasury","effects":{"gold":-150,"controlBonus":6}},{"label":"Rely on volunteers and charity","effects":{"hr":-30,"controlPenalty":5}}]},{"id":"ai_indic_taxila_finds","ageId":"modern","year":1913,"theme":"indic","title":"Treasures of Taxila","description":"Excavators at Takshashila unearth Gandharan sculpture and coins, and foreign collectors are already offering generous prices for the finest pieces.","options":[{"label":"Found a museum on site","effects":{"gold":-60,"techPoints":30}},{"label":"Sell the finds abroad","effects":{"gold":90}}]},{"id":"ai_indic_odia_province","ageId":"modern","year":1936,"theme":"indic","title":"A Province for Odia","description":"Odia speakers, scattered among neighboring provinces, demand a land of their own drawn around their language and the old heart of Kalinga.","options":[{"label":"Carve out a new province","effects":{"gold":-80,"controlBonus":10}},{"label":"Keep the old boundaries","effects":{"gold":40,"controlPenalty":8}}]},{"id":"ai_sinic_boxer_uprising","ageId":"modern","year":1900,"theme":"sinic","title":"The Boxers Rise","description":"Bands of Boxers from the Shandong countryside tear up railways and attack missionaries, vowing to drive out the foreigners. Foreign legations demand you crush them.","options":[{"label":"Back the Boxers against the foreigners","effects":{"militaryStrengthBonus":80,"gold":-150}},{"label":"Suppress the movement by force","effects":{"controlPenalty":10,"hr":-40}}]},{"id":"ai_sinic_wuchang_uprising","ageId":"modern","year":1911,"theme":"sinic","title":"Mutiny at Wuchang","description":"A bomb goes off by accident in a revolutionary cell in Hubei, and the New Army garrison rises rather than face arrest. Province after province may follow.","options":[{"label":"Join the revolution openly","effects":{"controlPenalty":12,"militaryStrengthBonus":60}},{"label":"Send loyal troops to retake the city","effects":{"gold":-120,"hr":-50,"controlBonus":8}},{"label":"Wait and negotiate with both sides","effects":{"controlPenalty":5}}]},{"id":"ai_sinic_whampoa_academy","ageId":"modern","year":1924,"theme":"sinic","title":"An Academy at Whampoa","description":"Soviet advisers offer money, rifles and instructors to found a military academy on an island near Guangzhou, training officers loyal to the party rather than to warlords.","options":[{"label":"Accept Soviet aid and advisers","effects":{"militaryStrengthBonus":120,"controlPenalty":5}},{"label":"Fund the academy yourself","effects":{"gold":-200,"militaryStrengthBonus":70}},{"label":"Rely on allied warlord armies","effects":{"gold":60,"controlPenalty":8}}]},{"id":"ai_sinic_yinxu_excavation","ageId":"modern","year":1928,"theme":"sinic","title":"Digging the Shang Capital","description":"Scholars of the Academia Sinica ask to excavate the fields near Anyang, where farmers have long sold inscribed oracle bones to dealers. Looters are digging already.","options":[{"label":"Fund a scientific excavation","effects":{"gold":-100,"techPoints":60}},{"label":"Tax the antiquities trade instead","effects":{"gold":80,"controlPenalty":4}}]},{"id":"ai_sinic_xian_incident","ageId":"modern","year":1936,"theme":"sinic","title":"Generals Seize the Leader","description":"Your own generals at Xi'an detain the national leader and demand he stop fighting the Communists and turn against the Japanese invaders.","options":[{"label":"Agree to a united front","effects":{"militaryStrengthBonus":100,"controlPenalty":8}},{"label":"Bomb Xi'an to free him","effects":{"hr":-60,"gold":-100,"controlBonus":6}}]},{"id":"ai_sinic_burma_road","ageId":"modern","year":1938,"theme":"sinic","title":"A Road to Burma","description":"With the coast lost to Japan, you need a lifeline through the Yunnan mountains to British Burma. Hundreds of thousands of laborers could cut it by hand.","options":[{"label":"Conscript laborers to build the road","effects":{"hr":-80,"militaryStrengthBonus":90,"controlPenalty":5}},{"label":"Pay workers and build slowly","effects":{"gold":-180,"militaryStrengthBonus":50}}]},{"id":"ai_sinic_datong_school","ageId":"modern","year":1907,"theme":"sinic","title":"Rebels at the School","description":"Officials report that the Datong school in Shaoxing, led by the poet Qiu Jin, is drilling students and hiding rifles for an uprising.","options":[{"label":"Raid the school and arrest her","effects":{"controlBonus":6,"controlPenalty":6}},{"label":"Watch quietly and gather names","effects":{"gold":-40,"defenseBonus":0.05}}]},{"id":"ai_sinic_special_economic_zone","ageId":"modern","year":1980,"theme":"sinic","title":"A Special Economic Zone","description":"Reformers propose opening a fishing town on the Hong Kong border to foreign capital, low taxes and private factories, as an experiment for the whole south.","options":[{"label":"Open the zone to foreign investors","effects":{"gold":200,"techPoints":40,"controlPenalty":8}},{"label":"Keep the planned economy intact","effects":{"controlBonus":6,"gold":-60}}]},{"id":"ai_americas_oil_expropriation","ageId":"modern","year":1938,"theme":"americas","title":"The Oil Companies Defy Us","description":"Foreign oil companies refuse a court order to raise their workers' wages. The strikers and the whole country now wait to see what you will do.","options":[{"label":"Nationalize the wells outright","effects":{"oil":50,"gold":-60}},{"label":"Negotiate higher royalties instead","effects":{"gold":80,"controlPenalty":6}}]},{"id":"ai_americas_chaco_border_war","ageId":"modern","year":1932,"theme":"americas","title":"War in the Chaco","description":"Rumors of oil beneath the dry Gran Chaco have turned a border quarrel into open war. Your highland conscripts are dying of thirst in the lowland scrub.","options":[{"label":"Send more conscripts to the front","effects":{"hr":-80,"militaryStrengthBonus":150,"gold":-100}},{"label":"Accept international arbitration","effects":{"controlPenalty":8}}]},{"id":"ai_americas_rubber_bust","ageId":"modern","year":1912,"theme":"americas","title":"The Rubber Bubble Bursts","description":"Cheap rubber from Asian plantations has crashed the price of wild Amazon latex. The tappers and river merchants of Marajó face ruin.","options":[{"label":"Subsidize the rubber tappers","effects":{"gold":-100,"controlBonus":6}},{"label":"Turn the land to cattle ranching","effects":{"gold":-40,"hr":-20,"techPoints":20}}]},{"id":"ai_americas_marines_land","ageId":"modern","year":1915,"theme":"americas","title":"Marines in the Harbor","description":"After a president is torn apart by a mob, foreign marines land and seize the customs houses. Peasant rebels in the hills call on you to resist.","options":[{"label":"Cooperate with the occupiers","effects":{"gold":80,"controlPenalty":10}},{"label":"Arm the rebels in the hills","effects":{"militaryStrengthBonus":60,"hr":-40}}]},{"id":"ai_americas_arctic_radar_line","ageId":"modern","year":1955,"theme":"americas","title":"Radar on the Ice","description":"A powerful southern ally wants to build early warning radar stations across your Arctic coast. The work brings wages, but also strangers and noise to the hunting grounds.","options":[{"label":"Allow the radar stations","effects":{"gold":120,"defenseBonus":0.1,"controlPenalty":6}},{"label":"Keep the hunting grounds closed","effects":{"controlBonus":5}}]},{"id":"ai_americas_fishmeal_boom","ageId":"modern","year":1970,"theme":"americas","title":"The Anchovy Fleet","description":"Fishmeal from the cold coastal current has made your ports among the busiest fisheries on Earth. Old fishermen warn that a warm El Niño year could empty the sea.","options":[{"label":"Expand the fleet and factories","effects":{"gold":150,"controlPenalty":5}},{"label":"Impose strict catch quotas","effects":{"gold":-40,"techPoints":15,"controlBonus":4}}]},{"id":"ai_americas_desert_dam","ageId":"modern","year":1911,"theme":"americas","title":"A Dam for the Desert","description":"Engineers propose a great masonry dam upriver to store floodwater for the desert fields. The farmers who dig and share the old canals fear losing their say.","options":[{"label":"Fund the great dam","effects":{"gold":-150,"hr":50}},{"label":"Keep the old canal system","effects":{"gold":30,"controlPenalty":5}}]},{"id":"ai_americas_land_reform","ageId":"modern","year":1969,"theme":"americas","title":"The Land to Those Who Work It","description":"Your officers demand that the great haciendas be broken up and handed to the peasant communities. The estate owners and their foreign buyers threaten to pull their money.","options":[{"label":"Break up the haciendas","effects":{"controlBonus":10,"gold":-100}},{"label":"Protect the great estates","effects":{"gold":60,"controlPenalty":10}}]},{"id":"ai_westafrica_bronze_casting_masters","ageId":"kingdoms","year":1300,"theme":"westafrica","title":"The Casters of Heads","description":"Your casters can shape lifelike heads of kings in copper alloy, but the metal must come south across the desert through costly trade routes.","options":[{"label":"Buy copper for royal portrait heads","effects":{"copper":-50,"gold":-50,"controlBonus":8}},{"label":"Cast in clay and save the metal","effects":{"copper":40,"controlPenalty":4}}]},{"id":"ai_westafrica_glass_bead_furnaces","ageId":"kingdoms","year":1100,"theme":"westafrica","title":"Furnaces of Blue Beads","description":"Your glassmakers melt local sand into prized blue beads that neighbors pay dearly for, but the furnaces devour wood and labor.","options":[{"label":"Expand the bead workshops","effects":{"hr":-40,"gold":110}},{"label":"Keep beads for royal regalia only","effects":{"gold":-30,"controlBonus":7}},{"label":"Share the craft with allied towns","effects":{"techPoints":-15}}]},{"id":"ai_westafrica_mande_gold_traders","ageId":"kingdoms","year":1420,"theme":"westafrica","title":"Traders From the North","description":"Mande merchants arrive seeking gold from your forest fields, offering cloth, salt and brass in return, and they ask to settle in your town.","options":[{"label":"Grant them a quarter of the town","effects":{"gold":120,"controlPenalty":6}},{"label":"Trade only at the market gates","effects":{"gold":50}}]},{"id":"ai_westafrica_gold_dust_monopoly","ageId":"kingdoms","year":1450,"theme":"westafrica","title":"The King's Share of Gold","description":"Your miners bring up nuggets as well as dust. You may claim every nugget for the throne, but the miners grumble at losing their best finds.","options":[{"label":"Claim all nuggets for the stool","effects":{"gold":140,"controlPenalty":8}},{"label":"Let miners keep a fair portion","effects":{"gold":40,"hr":30}}]},{"id":"ai_westafrica_copper_cross_currency","ageId":"kingdoms","year":1200,"theme":"westafrica","title":"Crosses of Copper","description":"Small copper crosses from the southern mines now pass from hand to hand as wealth along the Lualaba lakes, and chiefs hoard them as bride wealth.","options":[{"label":"Mint crosses under royal control","effects":{"copper":-50,"gold":90,"controlBonus":5}},{"label":"Let chiefs trade freely","effects":{"gold":40,"controlPenalty":6}}]},{"id":"ai_westafrica_sacred_kingship_rites","ageId":"kingdoms","year":1450,"theme":"westafrica","title":"The Rites of Kingship","description":"Elders insist the new king must eat apart and never be seen drinking, as befits sacred royal blood. The old chiefs see it as arrogance.","options":[{"label":"Adopt the sacred customs","effects":{"controlBonus":10}},{"label":"Rule as one among the chiefs","effects":{"controlPenalty":7}}]},{"id":"ai_westafrica_foreign_hunter_suitor","ageId":"gunpowder","year":1590,"theme":"westafrica","title":"A Hunter From Afar","description":"A skilled Luba hunter seeks your hand and brings new ways of rule. Your brothers warn that a foreign husband will steal the royal bracelet.","options":[{"label":"Marry the hunter","effects":{"techPoints":25,"militaryStrengthBonus":0.06,"controlPenalty":10}},{"label":"Send him away with gifts","effects":{"gold":-60,"controlBonus":6}}]},{"id":"ai_westafrica_kongo_tribute_demand","ageId":"kingdoms","year":1490,"theme":"westafrica","title":"Tribute to Kongo","description":"The mighty king of Kongo to the north demands tribute of iron tools and slaves, as from a vassal. Refusal may bring his armies.","options":[{"label":"Pay the tribute","effects":{"iron":-50,"hr":-30}},{"label":"Refuse and fortify Kabasa","effects":{"gold":-80,"defenseBonus":0.1}}]},{"id":"ai_mesopotamia_zanj_rising","ageId":"kingdoms","year":869,"theme":"mesopotamia","title":"Revolt in the Salt Marshes","description":"Enslaved laborers who scrape salt crusts from the southern marshes have risen in revolt, and their leader promises freedom to all who join him.","options":[{"label":"Send the army into the marshes","effects":{"hr":-80,"gold":-70,"controlBonus":10}},{"label":"Offer pardons and lighter labor","effects":{"gold":-90,"controlPenalty":5}}]},{"id":"ai_mesopotamia_paper_mill","ageId":"kingdoms","year":794,"theme":"mesopotamia","title":"The Secret of Paper","description":"Craftsmen from the east offer to build a paper mill in your city, promising cheap sheets that could replace costly parchment and papyrus.","options":[{"label":"Fund the mill and its workshops","effects":{"gold":-110,"techPoints":40}},{"label":"Buy paper from eastern traders instead","effects":{"gold":-40,"techPoints":12}}]},{"id":"ai_mesopotamia_qarmatian_preachers","ageId":"kingdoms","year":899,"theme":"mesopotamia","title":"Preachers of a New Order","description":"Qarmatian missionaries win followers among the villages and oases of the Gulf coast, preaching shared property and defiance of distant caliphs.","options":[{"label":"Expel the preachers","effects":{"controlBonus":8,"controlPenalty":4,"hr":-30}},{"label":"Make an alliance with their leaders","effects":{"controlPenalty":8}}]},{"id":"ai_mesopotamia_pearl_season","ageId":"kingdoms","year":1100,"theme":"mesopotamia","title":"The Pearl Season","description":"The summer diving season begins over the oyster banks, and merchants from Basra and India wait in your harbor for the finest pearls.","options":[{"label":"Tax every pearl sold","effects":{"gold":120,"controlPenalty":5}},{"label":"Fund more boats and divers","effects":{"gold":-60,"hr":-20}}]},{"id":"ai_mesopotamia_daylamite_mercenaries","ageId":"kingdoms","year":934,"theme":"mesopotamia","title":"Soldiers From the Mountains","description":"Daylamite foot soldiers, hardy men from the Caspian highlands, offer you their spears, but their captains are ambitious and have seized provinces before.","options":[{"label":"Hire them for your army","effects":{"gold":-100,"militaryStrengthBonus":10,"controlPenalty":6}},{"label":"Send them away","effects":{}}]},{"id":"ai_mesopotamia_mongol_demand","ageId":"kingdoms","year":1257,"theme":"mesopotamia","title":"The Khan Demands Submission","description":"Envoys of the Mongol prince Hulagu arrive with a letter: open your gates and pay tribute, or share the fate of the cities already burned.","options":[{"label":"Submit and pay tribute","effects":{"gold":-150,"controlPenalty":8}},{"label":"Refuse and strengthen the walls","effects":{"gold":-80,"defenseBonus":0.1,"hr":-60}}]},{"id":"ai_mesopotamia_timur_approaches","ageId":"kingdoms","year":1400,"theme":"mesopotamia","title":"The Lame Conqueror Approaches","description":"Timur's army moves into Syria, and refugees speak of towers built from skulls outside towns that resisted him.","options":[{"label":"Send gifts and craftsmen as tribute","effects":{"gold":-120,"techPoints":-15}},{"label":"Gather the levies and hold the river","effects":{"hr":-90,"militaryStrengthBonus":8,"defenseBonus":0.08}}]},{"id":"ai_nile_oracle_of_amun","ageId":"classical","year":-331,"theme":"nile","title":"A Conqueror at the Oracle","description":"A young Macedonian king crosses the desert to Siwa and asks the priests of Amun to greet him as the god's own son.","options":[{"label":"Hail him as the son of Amun","effects":{"gold":60,"controlPenalty":8}},{"label":"Refuse the foreigner's claim","effects":{"controlBonus":6}}]},{"id":"ai_nile_kings_from_the_south","ageId":"classical","year":-728,"theme":"nile","title":"Kings from the South","description":"A Kushite king marches down the Nile claiming to restore the true worship of Amun, and the princes of the delta are divided.","options":[{"label":"Bow to the Kushite pharaoh","effects":{"gold":-50,"controlPenalty":10}},{"label":"Rally the delta princes to resist","effects":{"hr":-60,"militaryStrengthBonus":40,"defenseBonus":0.1}}]},{"id":"ai_nile_canal_to_the_red_sea","ageId":"classical","year":-497,"theme":"nile","title":"The Canal to the Sea","description":"The Persian governor orders the old canal from the Nile to the Red Sea dug out again, demanding laborers and grain from your city.","options":[{"label":"Send diggers and grain","effects":{"hr":-60,"gold":-40,"techPoints":30}},{"label":"Let the work quietly stall","effects":{"gold":40,"controlPenalty":6}}]},{"id":"ai_nile_sabaean_masons","ageId":"classical","year":-700,"theme":"nile","title":"Masons from Saba","description":"Stoneworkers from across the Red Sea offer to raise a temple of fitted ashlar to Almaqah, finer than anything your highlands have seen.","options":[{"label":"Hire them for a great temple","effects":{"gold":-120,"controlBonus":8,"techPoints":20}},{"label":"Build with local hands","effects":{"hr":-30,"controlBonus":3}}]},{"id":"ai_nile_ships_at_opone","ageId":"classical","year":50,"theme":"nile","title":"Ships from Egypt","description":"Greek merchants sailing from Roman Egypt anchor at Opone, eager for cinnamon and tortoiseshell, and ask to trade freely without your agents.","options":[{"label":"Open the market fully","effects":{"gold":120,"controlPenalty":6}},{"label":"Tax every cargo heavily","effects":{"gold":60}}]},{"id":"ai_nile_furnaces_of_the_south","ageId":"classical","year":-300,"theme":"nile","title":"Furnaces of the South","description":"Your smiths smelt iron day and night, but the furnaces devour the acacia groves that shade the riverbanks and feed the herds.","options":[{"label":"Cut the groves to feed the furnaces","effects":{"iron":50,"controlPenalty":5}},{"label":"Limit the cutting","effects":{"iron":40,"gold":-30,"controlBonus":3}}]},{"id":"ai_nile_aksum_on_the_atbara","ageId":"classical","year":350,"theme":"nile","title":"Aksum on the River","description":"The king of Aksum leads his army down to the meeting of the rivers, burning Noba villages and demanding tribute.","options":[{"label":"Pay tribute to Aksum","effects":{"gold":-100}},{"label":"Fortify the riverbanks","effects":{"iron":-40,"hr":-40,"defenseBonus":0.1}}]},{"id":"ai_nile_greeks_seek_land","ageId":"classical","year":-631,"theme":"nile","title":"Settlers from Thera","description":"Greek settlers camped on the coast ask your chiefs to guide them inland to a fertile plateau with a flowing spring.","options":[{"label":"Lead them to the spring","effects":{"gold":50,"controlPenalty":6}},{"label":"Drive them back to the sea","effects":{"hr":-40,"militaryStrengthBonus":30}}]},{"id":"ai_levant_rock_tombs_tourism","ageId":"information","year":2008,"theme":"levant","title":"The Tombs Draw Visitors","description":"The carved tombs of Hegra have won world heritage status, and tour operators want hotels, roads and an airport beside them.","options":[{"label":"Build resorts near the tombs","effects":{"gold":180,"controlPenalty":6}},{"label":"Limit visitors and fund archaeologists","effects":{"gold":-80,"techPoints":30}}]},{"id":"ai_levant_offshore_oil_contract","ageId":"information","year":1994,"theme":"levant","title":"Contract of the Century","description":"Foreign oil companies offer to develop the deep Caspian fields in exchange for a long share of the profits.","options":[{"label":"Sign with the foreign consortium","effects":{"oil":50,"gold":100,"controlPenalty":5}},{"label":"Develop the fields ourselves, slowly","effects":{"gold":-150,"oil":50,"controlBonus":5}}]},{"id":"ai_levant_black_sea_terminal","ageId":"information","year":1999,"theme":"levant","title":"A Pipeline to the Sea","description":"A pipeline from the Caspian could end at the port of Phasis, bringing transit fees and the anger of a powerful northern neighbor.","options":[{"label":"Host the oil terminal","effects":{"gold":150}},{"label":"Decline and keep the peace","effects":{"gold":-40}}]},{"id":"ai_levant_quake_building_codes","ageId":"information","year":1999,"theme":"levant","title":"After the Earthquake","description":"A great earthquake has struck the Marmara region, and the rubble reveals concrete that builders cut with sand and bribes.","options":[{"label":"Enforce strict codes and prosecute builders","effects":{"gold":-120,"defenseBonus":0.1,"controlPenalty":4}},{"label":"Rebuild fast with cheap housing","effects":{"hr":60,"controlPenalty":8}}]},{"id":"ai_levant_falling_water_table","ageId":"information","year":2005,"theme":"levant","title":"The Wells Run Dry","description":"Pumps drilled for thirsty qat fields are draining the aquifer under Maryab faster than the rains can refill it.","options":[{"label":"Ban new wells","effects":{"controlPenalty":7,"gold":-30}},{"label":"Fund drip irrigation and dam repairs","effects":{"gold":-140,"techPoints":25,"controlBonus":4}},{"label":"Let the farmers pump","effects":{"gold":50,"hr":-50}}]},{"id":"ai_levant_drought_exodus","ageId":"information","year":2008,"theme":"levant","title":"Drought on the Plains","description":"A third dry year has withered the wheat, and farming families pour into the cities looking for work.","options":[{"label":"Restore fuel and bread subsidies","effects":{"gold":-160,"controlBonus":6}},{"label":"Keep the market reforms","effects":{"gold":80,"controlPenalty":10}}]},{"id":"ai_levant_jobs_for_citizens","ageId":"information","year":2011,"theme":"levant","title":"Young Men Want Jobs","description":"Protesters in the ports demand work, while foreign laborers fill most private jobs at lower wages.","options":[{"label":"Create state jobs for citizens","effects":{"gold":-200,"controlBonus":8}},{"label":"Impose quotas on foreign hiring","effects":{"gold":-60,"hr":-40,"controlBonus":4}},{"label":"Disperse the protests","effects":{"controlPenalty":9}}]},{"id":"ai_levant_coastal_nuclear_plant","ageId":"information","year":2013,"theme":"levant","title":"A Reactor by the Sea","description":"A foreign partner offers to build a nuclear power plant on the peninsula of Sinope, ending costly fuel imports.","options":[{"label":"Sign the reactor deal","effects":{"gold":-250,"techPoints":80,"controlPenalty":5}},{"label":"Keep importing gas","effects":{"gold":-60}}]},{"id":"ai_eastafrica_punt_incense_ships","ageId":"bronze","year":-1470,"theme":"eastafrica","title":"Ships From the North","description":"Foreign sailors from a great river kingdom beach their ships on your coast, seeking myrrh trees, incense, ebony and live baboons.","options":[{"label":"Trade freely for their beads, axes and goods","effects":{"gold":120,"controlPenalty":5}},{"label":"Demand gifts before they reach the groves","effects":{"gold":60}},{"label":"Send them away empty-handed","effects":{"controlBonus":6}}]},{"id":"ai_eastafrica_myrrh_tree_saplings","ageId":"bronze","year":-1180,"theme":"eastafrica","title":"Selling the Living Trees","description":"The northern traders now ask not for resin but for whole myrrh saplings in baskets, to plant in their own temple gardens.","options":[{"label":"Sell the saplings at a high price","effects":{"gold":100,"techPoints":-10}},{"label":"Sell only resin, keep the trees","effects":{"gold":40}}]},{"id":"ai_eastafrica_obsidian_quarry","ageId":"bronze","year":-1500,"theme":"eastafrica","title":"The Black Glass Quarry","description":"Herders travel far to the volcanic flows of the Rift for obsidian, the sharpest blade stone known, and rival bands now camp at the outcrops.","options":[{"label":"Post warriors at the quarry","effects":{"hr":-30,"defenseBonus":0.08}},{"label":"Share the outcrop for cattle tribute","effects":{"gold":50,"controlPenalty":4}}]},{"id":"ai_eastafrica_herders_from_north","ageId":"bronze","year":-1000,"theme":"eastafrica","title":"Herders on the Grasslands","description":"Cattle herders moving south reach the lake country, and their herds graze the same lands your foragers and fishers have long used.","options":[{"label":"Welcome them and learn herding","effects":{"techPoints":20,"controlPenalty":6}},{"label":"Drive them from the lakeshore","effects":{"hr":-40,"militaryStrengthBonus":5}},{"label":"Trade fish for milk and hides","effects":{"gold":-20}}]},{"id":"ai_eastafrica_painted_hills","ageId":"bronze","year":-1800,"theme":"eastafrica","title":"The Hills That Speak","description":"Elders say the spirits dwell in the painted rock faces, and a new generation wishes to add its own eland and rhino to the cliffs.","options":[{"label":"Gather ochre and bless the painters","effects":{"gold":-40,"controlBonus":8}},{"label":"Keep the sacred walls untouched","effects":{"techPoints":-10}}]},{"id":"ai_eastafrica_dry_waterholes","ageId":"bronze","year":-1200,"theme":"eastafrica","title":"The Waterholes Fail","description":"The rains have not come for two seasons, the pans are cracked, and the game has scattered beyond the known hunting grounds.","options":[{"label":"Split into small bands and follow game","effects":{"controlPenalty":8,"hr":20}},{"label":"Dig deep and store water in ostrich eggshells","effects":{"hr":-25,"techPoints":15}}]},{"id":"ai_eastafrica_limpopo_floodplain","ageId":"bronze","year":-900,"theme":"eastafrica","title":"The River Rises","description":"The Limpopo spills across its floodplain, leaving rich silt behind but drowning camps and driving animals to the sandstone hills.","options":[{"label":"Move the camps onto the hilltop","effects":{"hr":-20,"defenseBonus":0.06}},{"label":"Stay low and gather the new growth","effects":{"gold":50,"hr":-35}}]},{"id":"ai_eastafrica_monsoon_fishers","ageId":"bronze","year":-1100,"theme":"eastafrica","title":"Fishers of the Reef","description":"The seasonal winds bring great shoals to the reef, but rival fishing families quarrel over who may cast nets in the best channels.","options":[{"label":"Divide the channels by decree","effects":{"controlBonus":7}},{"label":"Let the strongest families take them","effects":{"gold":40,"controlPenalty":6}}]},{"id":"ai_indic_harsha_vengeance","ageId":"kingdoms","year":606,"theme":"indic","title":"Harsha Seeks Vengeance","description":"You have struck down the king of Thanesar. His younger brother Harsha now gathers a great army to avenge him, allied with Kamarupa on your eastern flank.","options":[{"label":"Fortify Karnasuvarna and wait","effects":{"gold":-80,"defenseBonus":0.1}},{"label":"March west to strike first","effects":{"hr":-70,"militaryStrengthBonus":0.08}},{"label":"Send envoys to seek terms","effects":{"controlPenalty":8}}]},{"id":"ai_indic_pilgrim_summons","ageId":"kingdoms","year":642,"theme":"indic","title":"The Chinese Pilgrim","description":"A renowned Chinese monk studying at Nalanda could grace your court. Harsha also wants him, and a forceful summons may offend your powerful ally.","options":[{"label":"Demand the monk come at once","effects":{"controlPenalty":6}},{"label":"Send gifts to Nalanda instead","effects":{"gold":-60,"techPoints":20}}]},{"id":"ai_indic_astronomical_compendium","ageId":"kingdoms","year":550,"theme":"indic","title":"Tables of the Heavens","description":"Astronomers of Ujjayini in the circle of Varahamihira ask for funds to compile new planetary tables and calendar rules for the realm.","options":[{"label":"Fund the full compendium","effects":{"gold":-100,"techPoints":40}},{"label":"Use them only for war omens","effects":{"gold":-30,"militaryStrengthBonus":0.05,"controlPenalty":4}}]},{"id":"ai_indic_arab_war_horses","ageId":"kingdoms","year":1290,"theme":"indic","title":"Horses That Die","description":"Arab merchants sell you war horses at enormous prices, yet the animals rarely survive a year in your climate, forcing you to buy again and again.","options":[{"label":"Keep buying horses every year","effects":{"gold":-150,"militaryStrengthBonus":0.1}},{"label":"Rely on elephants and infantry","effects":{"hr":-40,"defenseBonus":0.06}},{"label":"Tax the horse traders' ports","effects":{"gold":80}}]},{"id":"ai_indic_chola_invasion","ageId":"kingdoms","year":993,"theme":"indic","title":"The Cholas Cross Over","description":"Chola armies sent by Rajaraja have crossed the strait, and your ancient capital lies exposed on the open northern plain.","options":[{"label":"Withdraw south to Ruhuna","effects":{"controlPenalty":12,"defenseBonus":0.1}},{"label":"Defend the sacred city","effects":{"hr":-100,"defenseBonus":0.08}},{"label":"Offer tribute to the Chola","effects":{"gold":-150}}]},{"id":"ai_indic_ghaznavid_raids","ageId":"kingdoms","year":1001,"theme":"indic","title":"Mahmud at the Passes","description":"Mahmud of Ghazni leads mounted archers through the mountain passes toward Purushapura, plundering temples and towns as he advances.","options":[{"label":"Meet him in open battle","effects":{"hr":-90,"militaryStrengthBonus":0.08}},{"label":"Call on neighboring kings for aid","effects":{"hr":-40,"defenseBonus":0.1}},{"label":"Buy peace with tribute","effects":{"gold":-140,"controlPenalty":6}}]},{"id":"ai_indic_debal_ultimatum","ageId":"kingdoms","year":711,"theme":"indic","title":"Ultimatum at Debal","description":"An Arab army arrives by land and sea at the port of Debal, demanding punishment of pirates who seized their ships and submission from your realm.","options":[{"label":"Hand over pirates and pay","effects":{"gold":-100,"controlPenalty":5}},{"label":"Defend the walls of Debal","effects":{"hr":-80,"defenseBonus":0.1}},{"label":"Withdraw inland to gather forces","effects":{"controlPenalty":10,"hr":40}}]},{"id":"ai_indic_konark_sun_temple","ageId":"kingdoms","year":1250,"theme":"indic","title":"A Chariot of Stone","description":"Your priests propose a vast temple to the Sun at Konark, carved as a stone chariot, to celebrate victories over the sultans of Bengal.","options":[{"label":"Commit the treasury for years","effects":{"gold":-200,"controlBonus":12,"techPoints":15}},{"label":"Build a modest shrine instead","effects":{"gold":-60,"controlBonus":4}}]},{"id":"ai_sinic_canton_single_port","ageId":"gunpowder","year":1757,"theme":"sinic","title":"One Port for Foreigners","description":"Foreign ships crowd the Pearl River, and the court wants all Western trade confined to this one harbor under licensed merchant houses.","options":[{"label":"Grant the Cohong merchants a monopoly","effects":{"gold":120}},{"label":"Keep other harbors open to trade","effects":{"gold":60,"controlPenalty":8}}]},{"id":"ai_sinic_wokou_coast_raids","ageId":"gunpowder","year":1555,"theme":"sinic","title":"Pirates on the Coast","description":"Wokou raiders burn villages along the Zhejiang shore and vanish back to sea before your garrisons can march.","options":[{"label":"Recruit and drill hardy miners as soldiers","effects":{"gold":-80,"militaryStrengthBonus":0.1}},{"label":"Wall the market towns","effects":{"gold":-100,"defenseBonus":0.1}},{"label":"Ease the sea ban to calm smugglers","effects":{"gold":50,"controlPenalty":6}}]},{"id":"ai_sinic_shaanxi_great_earthquake","ageId":"gunpowder","year":1556,"theme":"sinic","title":"The Earth Splits Open","description":"A great earthquake has collapsed the cave dwellings of the Wei valley, and countless families lie buried beneath the loess.","options":[{"label":"Open the imperial granaries","effects":{"gold":-100,"controlBonus":8}},{"label":"Leave relief to the local gentry","effects":{"hr":-50,"controlPenalty":5}}]},{"id":"ai_sinic_dragon_bones_inscriptions","ageId":"gunpowder","year":1899,"theme":"sinic","title":"Writing on Dragon Bones","description":"Farmers near Anyang sell old bones to apothecaries as medicine, but a scholar has noticed ancient characters carved into them.","options":[{"label":"Buy up the bones for scholars","effects":{"gold":-60,"techPoints":30}},{"label":"Let the medicine trade continue","effects":{"gold":40,"techPoints":-10}}]},{"id":"ai_sinic_sichuan_resettlement","ageId":"gunpowder","year":1694,"theme":"sinic","title":"Empty Fields of Sichuan","description":"Decades of war have left the Sichuan basin half deserted, and migrants from Huguang ask what they will receive for coming west.","options":[{"label":"Grant land and years without tax","effects":{"gold":-80,"hr":60}},{"label":"Settle discharged soldiers instead","effects":{"hr":40,"controlPenalty":5}}]},{"id":"ai_sinic_yunnan_copper_mines","ageId":"gunpowder","year":1740,"theme":"sinic","title":"Copper for the Mints","description":"The mints of the capital hunger for Yunnan copper, and the mine bosses want silver advanced before they dig deeper shafts.","options":[{"label":"Advance official silver to the mines","effects":{"gold":-100,"copper":50}},{"label":"Leave the mines to private hands","effects":{"copper":50,"controlPenalty":4}}]},{"id":"ai_sinic_shandong_boxer_bands","ageId":"gunpowder","year":1899,"theme":"sinic","title":"Fists of Righteous Harmony","description":"Bands of young boxers in Shandong drill in temple yards and threaten mission churches, while foreign envoys demand you crush them.","options":[{"label":"Send troops to disperse them","effects":{"controlPenalty":8}},{"label":"Quietly tolerate the militias","effects":{"hr":50}}]},{"id":"ai_sinic_jingzhou_dike_flood","ageId":"gunpowder","year":1788,"theme":"sinic","title":"The Yangtze Breaks Through","description":"Summer floods have burst the river dikes near Jingzhou and water stands in the city streets.","options":[{"label":"Rebuild the dikes with corvee labor","effects":{"gold":-90,"hr":-40,"controlBonus":6}},{"label":"Patch the breaches and cut costs","effects":{"gold":-30,"controlPenalty":6}}]},{"id":"ai_eastafrica_ibn_battuta_visit","ageId":"kingdoms","year":1331,"theme":"eastafrica","title":"A Traveler From Tangier","description":"The Moroccan traveler Ibn Battuta lands at your port and praises its fine buildings. His account could carry your name across the Muslim world, but custom demands lavish gifts from his hosts.","options":[{"label":"Host him with feasts and gifts","effects":{"gold":-80}},{"label":"Receive him politely, spend nothing more","effects":{"controlPenalty":3}}]},{"id":"ai_eastafrica_failing_rains","ageId":"kingdoms","year":1280,"theme":"eastafrica","title":"The Rains Fail","description":"Years of colder, drier weather have shrunk the harvests in the Limpopo valley. Your people still trade gold and ivory, but granaries are emptying.","options":[{"label":"Trade ivory for grain from afar","effects":{"gold":-90,"controlBonus":6}},{"label":"Send families to resettle elsewhere","effects":{"hr":-50,"controlPenalty":8}},{"label":"Ration grain and hold the hill","effects":{"hr":-30,"controlPenalty":5}}]},{"id":"ai_eastafrica_stone_terraces","ageId":"kingdoms","year":1450,"theme":"eastafrica","title":"Stone Channels on the Escarpment","description":"Your farmers want to extend the stone-lined furrows that carry water from the escarpment streams to the terraced fields. The work will take every spare hand for seasons.","options":[{"label":"Extend the channels and terraces","effects":{"hr":-40,"gold":60,"techPoints":15}},{"label":"Keep hands free for herding and defense","effects":{"defenseBonus":0.06,"gold":-20}}]},{"id":"ai_eastafrica_march_for_salt","ageId":"kingdoms","year":1430,"theme":"eastafrica","title":"The Search for Salt","description":"Salt runs short on the plateau, and your advisers speak of the Dande lands to the north. Conquering them would bring salt and tribute, but the old capital would be left behind.","options":[{"label":"Lead the army north","effects":{"hr":-70,"gold":120,"militaryStrengthBonus":5}},{"label":"Buy salt through trade instead","effects":{"gold":-70}}]},{"id":"ai_eastafrica_control_of_wells","ageId":"kingdoms","year":1400,"theme":"eastafrica","title":"Masters of the Wells","description":"Your governors control the wells and river water of the Shabelle, and herders must pay to water their camels. Some clans now grumble at the tolls.","options":[{"label":"Raise the water tolls","effects":{"gold":100,"controlPenalty":8}},{"label":"Dig new limestone wells for all","effects":{"gold":-110,"controlBonus":10}}]},{"id":"ai_eastafrica_great_ditches","ageId":"kingdoms","year":1400,"theme":"eastafrica","title":"The Great Earthworks","description":"Cattle raiders threaten your grazing lands. Your elders propose cutting deep ditches through the rock around Bigo to enclose the herds and the royal enclosure.","options":[{"label":"Dig the ditches deeper and longer","effects":{"hr":-60,"defenseBonus":0.1}},{"label":"Arm herders to guard the cattle","effects":{"iron":-40,"militaryStrengthBonus":4}}]},{"id":"ai_eastafrica_highland_rice","ageId":"kingdoms","year":1450,"theme":"eastafrica","title":"Rice in the Marshes","description":"Your settlers in the central highlands could drain the marshes around their hills for rice paddies. The Vazimba who fish and hunt there will resist losing their lands.","options":[{"label":"Drain the marshes for rice","effects":{"gold":70,"hr":-30,"controlPenalty":6}},{"label":"Share the marshes with the Vazimba","effects":{"gold":-20}}]},{"id":"ai_eastafrica_beads_at_tsodilo","ageId":"kingdoms","year":900,"theme":"eastafrica","title":"Glass Beads and Shells","description":"Herders and metalworkers camped near the painted hills offer glass beads, seashells and iron for specularite and hides. Their cattle, though, crowd the springs your people rely on.","options":[{"label":"Trade freely with the newcomers","effects":{"gold":50,"iron":30,"controlPenalty":5}},{"label":"Keep the springs for your bands","effects":{"controlBonus":6}}]},{"id":"ai_indic_drying_rivers","ageId":"bronze","year":-1900,"theme":"indic","title":"The Rivers Run Dry","description":"The Ghaggar-Hakra streams that fed your towns are shrinking each year, and farmers are already drifting east toward the Yamuna and Ganga plains.","options":[{"label":"Dig wells and channels to hold them","effects":{"gold":-90,"controlBonus":6}},{"label":"Lead the families east to new land","effects":{"hr":-40,"controlPenalty":5}}]},{"id":"ai_americas_sunken_plaza","ageId":"stone","year":-2600,"theme":"americas","title":"The Sunken Circle","description":"Your people haul stone in woven shicra bags to raise platform mounds around a round sunken plaza, and the work eats the season.","options":[{"label":"Raise another great platform","effects":{"gold":-60,"controlBonus":8}},{"label":"Send the haulers to the cotton fields","effects":{"gold":40,"controlPenalty":4}}]},{"id":"ai_americas_knotted_cords","ageId":"stone","year":-2500,"theme":"americas","title":"Knots in Cotton Cord","description":"Your stewards tie knotted cotton cords to keep count of nets and anchovies traded up from the coast, but only a few can read them.","options":[{"label":"Train more stewards in the knots","effects":{"gold":-30,"techPoints":15}},{"label":"Trust the memory of elders","effects":{"gold":20,"controlPenalty":4}}]},{"id":"ai_americas_taming_llamas","ageId":"stone","year":-3500,"theme":"americas","title":"Herds of the Puna","description":"Hunters around the high lake begin penning wild guanaco and vicuña, and some young ones now follow people instead of fleeing.","options":[{"label":"Pen and breed the tame herds","effects":{"gold":-40,"techPoints":12}},{"label":"Keep hunting the wild herds","effects":{"hr":15,"controlPenalty":3}}]},{"id":"ai_americas_lake_copper","ageId":"stone","year":-3000,"theme":"americas","title":"Copper from the Lakes","description":"Traders bring nuggets of pure copper from the northern lakes, soft enough to hammer cold into points and beads.","options":[{"label":"Hammer spear points for hunters","effects":{"copper":-30,"militaryStrengthBonus":10}},{"label":"Trade copper beads to distant bands","effects":{"copper":-20,"gold":50}}]},{"id":"ai_americas_shell_ring","ageId":"stone","year":-2800,"theme":"americas","title":"The Shell Ring","description":"Years of feasting on oysters and whelks have piled shell around your village, and the elders want to shape it into a great ring.","options":[{"label":"Raise the ring as a high wall","effects":{"hr":-15,"defenseBonus":0.08}},{"label":"Hold a great feast for neighbors","effects":{"gold":-30}}]},{"id":"ai_americas_small_tool_bands","ageId":"stone","year":-2500,"theme":"americas","title":"Eastward Across the Ice","description":"Small bands with fine stone blades and bows push east from the far west, hunting musk ox and seal along the frozen coasts.","options":[{"label":"Follow the musk ox eastward","effects":{"hr":20,"controlPenalty":5}},{"label":"Winter at the known seal grounds","effects":{"gold":-20,"defenseBonus":0.05}}]},{"id":"ai_americas_teosinte_gardens","ageId":"stone","year":-4000,"theme":"americas","title":"The Little Ears","description":"In the valley caves, families tend squash and a wild grass whose tiny ears grow a little larger each year they replant the best seed.","options":[{"label":"Clear gardens for the grass","effects":{"gold":-30,"techPoints":15}},{"label":"Keep foraging acorns and mesquite","effects":{"gold":20,"controlPenalty":3}}]},{"id":"ai_americas_river_pottery","ageId":"stone","year":-4800,"theme":"americas","title":"Fired Clay by the River","description":"Shellfish gatherers along the great river learn to temper clay with crushed shell and fire it into pots, but pots tie families to one shore.","options":[{"label":"Build firing pits at the shell mound","effects":{"gold":-20,"techPoints":12}},{"label":"Stay light and follow the floods","effects":{"hr":10,"controlPenalty":3}}]},{"id":"ai_sinic_banpo_village_ditch","ageId":"stone","year":-4500,"theme":"sinic","title":"The Ditch Around Banpo","description":"Your millet farmers on the Wei River live in round pit houses. The elders want a deep ditch dug around the whole village, but the work would leave the fields short of hands.","options":[{"label":"Dig the ditch around the houses","effects":{"gold":-30,"defenseBonus":0.08}},{"label":"Keep every hand in the millet fields","effects":{"gold":40,"controlPenalty":3}}]},{"id":"ai_sinic_hemudu_stilt_rice","ageId":"stone","year":-4800,"theme":"sinic","title":"Rice in the Marshes","description":"In the wet lowlands south of the bay, your people raise houses on wooden stilts and plant rice in the mud. Clearing more marsh means felling the forests that feed the hunters.","options":[{"label":"Clear the marsh for new paddies","effects":{"hr":20,"gold":-30}},{"label":"Keep the forest for deer and acorns","effects":{"gold":30,"techPoints":-5}}]},{"id":"ai_sinic_liangzhu_jade_cong","ageId":"stone","year":-3000,"theme":"sinic","title":"The Jade Cong","description":"Your craftsmen grind square jade tubes carved with masked faces, and the great families are buried with them. The carvers ask for more workers and more stone from distant hills.","options":[{"label":"Feed the jade workshops","effects":{"gold":-50,"controlBonus":8}},{"label":"Send the workers to build dams","effects":{"defenseBonus":0.06,"controlPenalty":4}}]},{"id":"ai_sinic_eggshell_pottery","ageId":"stone","year":-2500,"theme":"sinic","title":"Eggshell Black Pottery","description":"Your potters on the fast wheel now throw black cups as thin as eggshell. The chiefs want them only for feasts and burials, while traders would carry them far along the coast.","options":[{"label":"Reserve the cups for the chiefs","effects":{"controlBonus":6,"gold":-20}},{"label":"Let the traders carry them away","effects":{"gold":50,"controlPenalty":4}},{"label":"Teach the craft to more apprentices","effects":{"techPoints":12,"gold":-30}}]},{"id":"ai_sinic_shijiahe_earthen_walls","ageId":"stone","year":-2500,"theme":"sinic","title":"Walls of Rammed Earth","description":"The towns of the middle Yangzi raise great earthen walls and moats around their rice fields. Your neighbors are building theirs, and your people ask whether you will match them.","options":[{"label":"Raise a wall of rammed earth","effects":{"gold":-60,"defenseBonus":0.1}},{"label":"Seek alliance with the walled towns","effects":{"controlPenalty":3}}]},{"id":"ai_sinic_chengdu_plain_floods","ageId":"stone","year":-2300,"theme":"sinic","title":"Floods on the Plain","description":"Rivers pouring from the western mountains flood the Chengdu plain each summer. Your people can bank the villages with earth or move to higher ground and leave the rich soil.","options":[{"label":"Bank the villages with earthen walls","effects":{"gold":-40,"defenseBonus":0.07}},{"label":"Move the people to higher ground","effects":{"hr":-15,"controlBonus":5}}]},{"id":"ai_sinic_northern_jade_traders","ageId":"stone","year":-2600,"theme":"sinic","title":"Strangers Bearing Jade","description":"Traders from the north come over the mountain passes with jade rings and tubes. They want your shells and rice, and some of your young men want to follow them back.","options":[{"label":"Trade freely with the northerners","effects":{"gold":40,"hr":-10}},{"label":"Turn them back at the passes","effects":{"defenseBonus":0.05}}]},{"id":"ai_sinic_cracked_bones","ageId":"stone","year":-2200,"theme":"sinic","title":"Reading the Cracked Bones","description":"Your diviners heat the shoulder blades of oxen and read the cracks to learn the will of the ancestors. The chiefs want every war and harvest decided this way.","options":[{"label":"Let the diviners guide every decision","effects":{"controlBonus":10,"gold":-30}},{"label":"Keep the bones for great matters only","effects":{"techPoints":8,"controlPenalty":4}}]},{"id":"ai_indic_envoys_of_alexander","ageId":"classical","year":-326,"theme":"indic","title":"Envoys at Takshashila","description":"A Macedonian king nears the Indus, and your rival Porus waits beyond the Jhelum. Alexander's envoys demand submission, elephants and supplies.","options":[{"label":"Submit and send elephants and silver","effects":{"gold":-120,"controlPenalty":5}},{"label":"Refuse and fortify Takshashila","effects":{"defenseBonus":0.1,"hr":-40}}]},{"id":"ai_indic_bamboo_grove_grant","ageId":"classical","year":-528,"theme":"indic","title":"The Bamboo Grove","description":"A wandering teacher from the Shakyas draws crowds at Rajagriha. Your ministers ask whether to give his monks your royal bamboo grove.","options":[{"label":"Grant Veluvana to the sangha","effects":{"gold":-60,"techPoints":25,"controlBonus":5}},{"label":"Keep the grove for the court","effects":{"gold":40,"controlPenalty":3}}]},{"id":"ai_indic_physician_from_magadha","ageId":"classical","year":-500,"theme":"indic","title":"A Physician from Magadha","description":"Jaundice wracks you, and only Jivaka, Bimbisara's physician, is said to cure it. His remedy is ghee, which you despise.","options":[{"label":"Summon Jivaka and swallow the cure","effects":{"gold":-50}},{"label":"Trust Ujjayini's own healers","effects":{"gold":20,"controlPenalty":6}}]},{"id":"ai_indic_nanda_canal","ageId":"classical","year":-160,"theme":"indic","title":"The Nanda Canal","description":"An old canal dug by a Nanda king ends short of Tosali. Extending it would water new fields but drain the treasury saved for war.","options":[{"label":"Extend the canal into the city","effects":{"gold":-150,"controlBonus":10}},{"label":"March on Magadha instead","effects":{"militaryStrengthBonus":40,"hr":-50}}]},{"id":"ai_indic_sudarshana_dam","ageId":"classical","year":150,"theme":"indic","title":"The Broken Dam","description":"A storm has burst the Sudarshana lake dam near Girinagara. Your ministers urge forced labor and new taxes; you could pay from the treasury instead.","options":[{"label":"Rebuild from the treasury alone","effects":{"gold":-200,"controlBonus":12}},{"label":"Levy taxes and forced labor","effects":{"gold":-40,"hr":-40,"controlPenalty":8}},{"label":"Let the lake run dry","effects":{"gold":30,"controlPenalty":12}}]},{"id":"ai_indic_yavana_pearl_trade","ageId":"classical","year":50,"theme":"indic","title":"Yavana Gold for Pearls","description":"Roman traders pay in gold for Pandya pearls and pepper. Your divers warn the pearl beds cannot bear endless harvest.","options":[{"label":"Open the pearl beds to the Yavanas","effects":{"gold":150,"controlPenalty":5}},{"label":"Limit the harvest and raise prices","effects":{"gold":50}},{"label":"Hire Yavana guards for the palace","effects":{"gold":-80,"defenseBonus":0.1}}]},{"id":"ai_indic_mahinda_arrives","ageId":"classical","year":-247,"theme":"indic","title":"A Monk on Mihintale","description":"Mahinda, son of the Mauryan emperor Ashoka, preaches the Buddha's teaching near Anuradhapura. Embracing it would bind you closely to Pataliputra.","options":[{"label":"Welcome him and build a monastery","effects":{"gold":-100}},{"label":"Honor him but keep the old shrines","effects":{"controlBonus":5}}]},{"id":"ai_indic_nahapana_silver","ageId":"classical","year":124,"theme":"indic","title":"Nahapana's Silver","description":"Your armies have driven the Kshaharata satraps from Nashik, seizing hoards of Nahapana's coins. Restriking them is quick; melting them down is costly.","options":[{"label":"Restrike them with Satavahana marks","effects":{"gold":100,"controlPenalty":4}},{"label":"Melt and mint fresh coins","effects":{"gold":-30,"controlBonus":8}},{"label":"Grant the silver to Nashik's monks","effects":{"gold":-50,"controlBonus":6}}]},{"id":"ai_steppe_siege_of_bactra","ageId":"classical","year":-206,"theme":"steppe","title":"Antiochus at the Walls","description":"Antiochus III has besieged Bactra for two years. His envoys hint at peace if you surrender your war elephants and accept him as overlord in name.","options":[{"label":"Give the elephants and keep your crown","effects":{"controlBonus":5}},{"label":"Hold the walls whatever the cost","effects":{"hr":-80,"defenseBonus":0.1}}]},{"id":"ai_steppe_spitamenes_resistance","ageId":"classical","year":-329,"theme":"steppe","title":"The Macedonian Garrisons","description":"Alexander's garrisons hold Marakanda and his men build forts along the Jaxartes. The Sogdian nobles look to you, and the Massagetae horsemen offer to ride with you for plunder.","options":[{"label":"Raise the revolt with the Massagetae","effects":{"militaryStrengthBonus":50,"gold":-80,"controlPenalty":8}},{"label":"Feign submission and gather strength","effects":{"controlPenalty":4}}]},{"id":"ai_steppe_amage_rides_to_chersonesos","ageId":"classical","year":-200,"theme":"steppe","title":"A Plea From Chersonesos","description":"The Greeks of Chersonesos beg your help against a Scythian king who raids their fields. Your husband the king ignores them, but the decision now rests in your hands.","options":[{"label":"Lead a picked band in a night raid","effects":{"hr":-40,"gold":60}},{"label":"Demand tribute before sending riders","effects":{"gold":90}}]},{"id":"ai_steppe_han_princess_wusun","ageId":"classical","year":-105,"theme":"steppe","title":"A Bride From Chang'an","description":"The Han emperor offers a princess in marriage to bind the Wusun against the Xiongnu. The Xiongnu, hearing of it, send a bride of their own.","options":[{"label":"Make the Han princess your chief wife","effects":{}},{"label":"Honor both brides equally","effects":{"controlPenalty":5}},{"label":"Refuse the Han and keep old ties","effects":{"gold":-50,"defenseBonus":0.08}}]},{"id":"ai_steppe_loulan_between_empires","ageId":"classical","year":-77,"theme":"steppe","title":"Caught Between Two Empires","description":"Han envoys accuse Loulan of sheltering Xiongnu agents and ambushing Chinese caravans. They demand a royal hostage and a garrison by the salt lake.","options":[{"label":"Send a prince and admit the garrison","effects":{"controlPenalty":8,"gold":80}},{"label":"Keep secret ties with the Xiongnu","effects":{"gold":40}}]},{"id":"ai_steppe_silkworms_in_headdress","ageId":"classical","year":440,"theme":"steppe","title":"Eggs in a Headdress","description":"A princess from the east arrives to wed your king, and whispers spread that she hid silkworm eggs in her headdress. The eastern court forbids their export on pain of death.","options":[{"label":"Plant mulberries and breed the worms","effects":{"gold":-70,"techPoints":40}},{"label":"Return the eggs quietly to keep peace","effects":{"gold":-30}}]},{"id":"ai_steppe_tanshihuai_refuses_title","ageId":"classical","year":166,"theme":"steppe","title":"The Han Offer a Seal","description":"After years of your raids, the Han court offers you a royal seal and a marriage alliance if you stop. Your chiefs grow rich from plunder and watch your answer closely.","options":[{"label":"Accept the seal and the bride","effects":{"controlPenalty":10}},{"label":"Refuse and raid the frontier again","effects":{"gold":120,"hr":-50,"controlBonus":6}}]},{"id":"ai_mesopotamia_sack_of_susa","ageId":"classical","year":-647,"theme":"mesopotamia","title":"Assyria Marches on Susa","description":"Ashurbanipal's army has crossed the Karun and burns the temples of Susa. Your nobles beg you to save the royal tombs before the Assyrians defile them.","options":[{"label":"Pay tribute and surrender the rebel princes","effects":{"gold":-150,"controlPenalty":8}},{"label":"Fall back into the Zagros highlands","effects":{"hr":-40,"defenseBonus":0.1}},{"label":"Stand and fight before the walls","effects":{"hr":-80,"militaryStrengthBonus":40}}]},{"id":"ai_mesopotamia_cyrus_revolt","ageId":"classical","year":-550,"theme":"mesopotamia","title":"The King of Anshan Rises","description":"Cyrus of Anshan has raised the Persians against his Median overlord Astyages. Envoys from both camps wait at your gate for an answer.","options":[{"label":"March with Cyrus against the Medes","effects":{"hr":-50}},{"label":"Stay loyal to Astyages","effects":{"gold":60,"controlPenalty":6}}]},{"id":"ai_mesopotamia_tribute_to_assyria","ageId":"classical","year":-709,"theme":"mesopotamia","title":"Gifts for the Assyrian King","description":"News reaches the island that Sargon II has crushed Babylon. Your elders ask whether to send gifts across the Gulf before Assyria turns its eyes south.","options":[{"label":"Send bronze, wood and pearls to Assyria","effects":{"gold":-90,"copper":-30}},{"label":"Trust the sea to keep you safe","effects":{"defenseBonus":0.05,"controlPenalty":5}}]},{"id":"ai_mesopotamia_greek_ships_tylos","ageId":"classical","year":-324,"theme":"mesopotamia","title":"Greek Ships in Harbor","description":"Ships sent by Alexander to survey the Gulf anchor off your island. Their captain sketches your cotton fields and asks for water, pilots and maps.","options":[{"label":"Welcome them and share your pilots","effects":{"techPoints":30,"controlPenalty":4}},{"label":"Close the harbor to foreigners","effects":{"gold":-40,"defenseBonus":0.08}}]},{"id":"ai_mesopotamia_aramaic_scribes","ageId":"classical","year":-500,"theme":"mesopotamia","title":"The Old Script Fades","description":"Persian officials now write in Aramaic on leather, and young scribes abandon the clay tablet. The temple masters warn that cuneiform learning will die with them.","options":[{"label":"Train scribes in Aramaic for the satrapy","effects":{"gold":-60,"controlPenalty":4}},{"label":"Fund the temple schools of cuneiform","effects":{"gold":-80,"techPoints":30}}]},{"id":"ai_mesopotamia_fort_downriver","ageId":"classical","year":-300,"theme":"mesopotamia","title":"A Macedonian Fort Upriver","description":"Seleucid soldiers are building a fortress on the Euphrates cliffs near your old mounds. Caravans now stop there, and its commander wants grain from your fields.","options":[{"label":"Sell grain to the garrison","effects":{"gold":80,"controlPenalty":6}},{"label":"Tax the caravans before they reach it","effects":{"gold":50}},{"label":"Refuse and wall your village","effects":{"gold":-50,"defenseBonus":0.07}}]},{"id":"ai_mesopotamia_alliance_with_babylon","ageId":"classical","year":-710,"theme":"mesopotamia","title":"Merodach-baladan Asks for Aid","description":"The Chaldean king of Babylon begs your help as Sargon II marches south. Your uncle's army once beat the Assyrians at Der, but the cost was heavy.","options":[{"label":"Send archers and chariots to Babylon","effects":{"hr":-60,"militaryStrengthBonus":30}},{"label":"Take his gold but keep your army home","effects":{"gold":100}}]},{"id":"ai_mesopotamia_fortress_of_sargon","ageId":"classical","year":-717,"theme":"mesopotamia","title":"The Fortress of Sargon","description":"You have ordered a new capital raised on empty land north of Nineveh, with palace walls lined in carved stone. The old cities grumble at the endless levies.","options":[{"label":"Press on with deported labor","effects":{"gold":-150,"defenseBonus":0.1,"controlPenalty":7}},{"label":"Slow the work and ease the levies","effects":{"gold":-50,"controlBonus":6}}]},{"id":"ai_steppe_sacred_drink_gonur","ageId":"bronze","year":-1950,"theme":"steppe","title":"The Sacred Drink","description":"Priests in Gonur's walled temples press ephedra and poppy into a holy drink. They ask for more land and storerooms to prepare it for every festival.","options":[{"label":"Grant the temples land and storerooms","effects":{"gold":-70,"controlBonus":6}},{"label":"Keep the rites small and frugal","effects":{"gold":40,"controlPenalty":4}}]},{"id":"ai_israelite_soviet_aliyah","ageId":"information","year":1990,"theme":"israelite","title":"A Million New Arrivals","description":"As the Soviet Union opens its gates, hundreds of thousands of immigrants land in your country within months. Many are engineers and doctors, and all of them need homes.","options":[{"label":"Build caravan towns and fund housing","effects":{"gold":-200,"hr":60,"techPoints":30}},{"label":"Let them find their own way","effects":{"hr":50,"controlPenalty":8}}]},{"id":"ai_israelite_scud_restraint","ageId":"information","year":1991,"theme":"israelite","title":"Missiles From Iraq","description":"Iraqi Scud missiles fall on your cities while your allies fight a war you were asked to stay out of. Your generals want to strike back.","options":[{"label":"Hold back and trust your allies","effects":{"controlPenalty":6}},{"label":"Send the air force to retaliate","effects":{"militaryStrengthBonus":0.08,"hr":-30}}]},{"id":"ai_israelite_ethiopian_airlift","ageId":"information","year":1991,"theme":"israelite","title":"Airlift From Addis Ababa","description":"Rebels close in on Addis Ababa, and thousands of Ethiopian Jews wait at the embassy. The collapsing regime asks for money to let them fly.","options":[{"label":"Pay and fly them out at once","effects":{"gold":-150,"hr":30}},{"label":"Negotiate slowly through the Americans","effects":{"controlPenalty":7}}]},{"id":"ai_israelite_venture_fund","ageId":"information","year":1993,"theme":"israelite","title":"Seeding the Startups","description":"Your advisers propose a state fund to match foreign investors in young tech companies. It could build an industry, or lose public money on dreamers.","options":[{"label":"Launch the state venture fund","effects":{"gold":-200,"techPoints":80}},{"label":"Leave it to the market","effects":{"gold":50,"techPoints":15}}]},{"id":"ai_israelite_oslo_talks","ageId":"information","year":1993,"theme":"israelite","title":"Secret Talks in Oslo","description":"Quiet meetings in Norway have produced a draft accord with your old enemies. Signing it may bring peace, but many at home call it betrayal.","options":[{"label":"Sign the accord publicly","effects":{"controlPenalty":10}},{"label":"Reject the draft and stand firm","effects":{"defenseBonus":0.05}}]},{"id":"ai_israelite_offshore_gas","ageId":"information","year":2010,"theme":"israelite","title":"Gas Beneath the Sea","description":"Drillers find a huge gas field far off your coast. The question now is who pays to bring it up, and who keeps the profits.","options":[{"label":"Develop it as a state project","effects":{"gold":-250,"oil":50}},{"label":"Grant rights to private partners","effects":{"oil":50,"gold":60,"controlPenalty":5}}]},{"id":"ai_israelite_rocket_interceptors","ageId":"information","year":2012,"theme":"israelite","title":"Rockets Over the City","description":"Rockets now reach as far as Jerusalem. The new interceptor system has proven itself in battle, but every missile it fires costs a fortune.","options":[{"label":"Deploy interceptor batteries","effects":{"gold":-200,"defenseBonus":0.1}},{"label":"Build more shelters instead","effects":{"gold":-60,"defenseBonus":0.05,"hr":-20}}]},{"id":"ai_israelite_jerusalem_light_rail","ageId":"information","year":2011,"theme":"israelite","title":"A Railway Through Jerusalem","description":"A light rail line is ready to cross Jerusalem, linking neighborhoods that rarely meet. Its route draws protests at home and criticism abroad.","options":[{"label":"Open the line as planned","effects":{"gold":-180,"controlBonus":8}},{"label":"Expand bus service instead","effects":{"gold":-50,"controlBonus":3}}]},{"id":"ai_levant_pilgrim_road_fort","ageId":"gunpowder","year":1744,"theme":"levant","title":"A Fort on the Pilgrim Road","description":"Pilgrim caravans to Mecca stop at Hegra's wells, and raiders strike them there each season. Your engineers propose a stone fort with a cistern and a garrison.","options":[{"label":"Build the fort and cistern","effects":{"gold":-120,"defenseBonus":0.1,"controlBonus":5}},{"label":"Pay the tribes for safe passage","effects":{"gold":-60,"controlPenalty":5}}]},{"id":"ai_levant_coffee_monopoly","ageId":"gunpowder","year":1660,"theme":"levant","title":"The Coffee Merchants Arrive","description":"Dutch and English factors crowd the Red Sea ports, desperate for highland coffee. They ask to buy beans freely and to carry away living seedlings.","options":[{"label":"Keep the monopoly, sell only roasted beans","effects":{"gold":100}},{"label":"Open the trade to foreign factors","effects":{"gold":160,"controlPenalty":6}}]},{"id":"ai_levant_portuguese_forts","ageId":"gunpowder","year":1650,"theme":"levant","title":"The Portuguese Forts Weaken","description":"The Portuguese garrisons on your coast are short of men and ships. Your tribal levies are eager to storm the harbor forts, but the walls are strong.","options":[{"label":"Storm the forts","effects":{"hr":-80,"gold":-40,"controlBonus":12}},{"label":"Besiege them and demand terms","effects":{"gold":-50}}]},{"id":"ai_levant_arabic_press","ageId":"gunpowder","year":1727,"theme":"levant","title":"A Press for Arabic Letters","description":"A learned convert asks your license to print books in Arabic script. The guild of scribes warns that thousands of copyists will lose their living.","options":[{"label":"License the press","effects":{"gold":-80,"techPoints":40,"controlPenalty":5}},{"label":"Protect the scribes","effects":{"controlBonus":5,"techPoints":-10}}]},{"id":"ai_levant_sinope_batteries","ageId":"gunpowder","year":1853,"theme":"levant","title":"Steamships off Sinope","description":"Russian steam warships with shell guns patrol the Black Sea. Your squadron sheltering in Sinope harbor has old wooden hulls and weak shore batteries.","options":[{"label":"Buy modern shore guns","effects":{"gold":-150,"iron":-40,"defenseBonus":0.1}},{"label":"Withdraw the fleet to safer waters","effects":{"controlPenalty":8,"hr":30}}]},{"id":"ai_levant_angora_goats","ageId":"gunpowder","year":1838,"theme":"levant","title":"Foreigners Want Angora Goats","description":"European mills pay high prices for the silky mohair of your highland goats. Now their agents offer gold for live breeding stock to raise abroad.","options":[{"label":"Forbid export of live goats","effects":{"gold":50}},{"label":"Sell the breeding stock","effects":{"gold":150,"controlPenalty":5}}]},{"id":"ai_levant_desert_preacher","ageId":"gunpowder","year":1744,"theme":"levant","title":"A Preacher Seeks Protection","description":"A stern preacher, expelled from his town for condemning shrines and saint worship, asks for your protection. His followers would fight fiercely for a ruler who backs him.","options":[{"label":"Shelter him and join his cause","effects":{"controlBonus":10,"hr":40}},{"label":"Send him away","effects":{"controlPenalty":5}}]},{"id":"ai_levant_shirvan_silk","ageId":"gunpowder","year":1562,"theme":"levant","title":"English Traders Seek Silk","description":"An English merchant has crossed Russia and the Caspian to buy your raw silk. Years of war with the Ottomans have choked the western caravans, but the shah distrusts these strangers.","options":[{"label":"Grant the English trading privileges","effects":{"gold":90,"controlPenalty":4}},{"label":"Send him home empty-handed","effects":{"gold":-30}}]},{"id":"ai_indic_diu_fort","ageId":"gunpowder","year":1535,"theme":"indic","title":"A Fort at Diu","description":"Mughal armies press on Gujarat, and the Portuguese offer their cannon and ships if you let them build a fortress at Diu.","options":[{"label":"Grant the Portuguese their fort","effects":{"defenseBonus":0.1,"controlPenalty":8}},{"label":"Refuse and hire Ottoman gunners","effects":{"gold":-120,"militaryStrengthBonus":0.08}}]},{"id":"ai_indic_brahmaputra_fleet","ageId":"gunpowder","year":1671,"theme":"indic","title":"Boats on the Brahmaputra","description":"A great Mughal fleet is rowing up the Brahmaputra toward Guwahati. Your generals urge you to fight them in the river narrows.","options":[{"label":"Fortify the narrows and fight","effects":{"hr":-60,"defenseBonus":0.1}},{"label":"Offer tribute to buy peace","effects":{"gold":-100}}]},{"id":"ai_indic_stone_observatory","ageId":"gunpowder","year":1725,"theme":"indic","title":"Instruments of Stone","description":"Astronomers in Ujjain propose giant masonry instruments to correct the old tables, arguing that brass astrolabes are too small to be trusted.","options":[{"label":"Build the stone observatory","effects":{"gold":-120,"techPoints":50}},{"label":"Keep using brass astrolabes","effects":{"gold":-30,"techPoints":15}}]},{"id":"ai_indic_muslin_weavers","ageId":"gunpowder","year":1765,"theme":"indic","title":"The Weavers' Complaint","description":"Muslin weavers say Company agents force advances on them and buy their cloth below its worth. They beg you to intervene.","options":[{"label":"Protest to the Company","effects":{"gold":-40,"controlBonus":8}},{"label":"Accept the contract system","effects":{"gold":90,"controlPenalty":10}}]},{"id":"ai_indic_saltpetre_trade","ageId":"gunpowder","year":1650,"theme":"indic","title":"Saltpetre of Bihar","description":"Dutch and English factors at Patna bid high for the saltpetre your villages boil, the very powder your own gunners need.","options":[{"label":"Sell to the foreign factories","effects":{"gold":120}},{"label":"Reserve it for your powder mills","effects":{"gold":-50,"militaryStrengthBonus":0.1}}]},{"id":"ai_indic_temple_hall","ageId":"gunpowder","year":1636,"theme":"indic","title":"A Hall for the Goddess","description":"Priests of the great temple ask for a new pillared hall for the festival of Meenakshi, while your treasurers eye the temple lands instead.","options":[{"label":"Fund the grand pillared hall","effects":{"gold":-150,"controlBonus":12}},{"label":"Levy the temple estates","effects":{"gold":80,"controlPenalty":8}}]},{"id":"ai_indic_indus_crossing","ageId":"gunpowder","year":1581,"theme":"indic","title":"Guarding the Indus Crossing","description":"Raiders from the hills keep slipping across the Indus ferry near Attock. You can wall the crossing in stone or pay the tribal chiefs to keep the road.","options":[{"label":"Build a stone fort at the ferry","effects":{"gold":-140,"defenseBonus":0.1}},{"label":"Pay the chiefs to guard the road","effects":{"gold":-60,"controlPenalty":5}}]},{"id":"ai_indic_baked_brick_city","ageId":"stone","year":-2600,"theme":"indic","title":"Bricks of One Measure","description":"Harappa's builders fire bricks to a single proportion and lay covered drains beneath the streets. The kilns devour timber from the riverbanks, and the work never ends.","options":[{"label":"Fire bricks for walls and drains","effects":{"gold":-60,"defenseBonus":0.1}},{"label":"Build with sun-dried mud instead","effects":{"gold":30,"controlPenalty":4}}]},{"id":"ai_indic_ships_to_agade","ageId":"stone","year":-2300,"theme":"indic","title":"Ships for Distant Akkad","description":"Traders of Meluhha sail along the coast to the Gulf, carrying carnelian and timber to the quays of distant kings. The voyage enriches some households and drains the workshops of skilled hands.","options":[{"label":"Send the bead-makers' wares abroad","effects":{"gold":80,"hr":-15}},{"label":"Keep the carnelian for your own lords","effects":{"controlBonus":6,"gold":-20}},{"label":"Welcome foreign merchants to your ports","effects":{"controlPenalty":5}}]},{"id":"ai_indic_lothal_basin","ageId":"stone","year":-2400,"theme":"indic","title":"The Great Brick Basin","description":"Lothal's elders propose a vast brick basin beside the town, linked to the river so boats may load at any tide. It will take a whole season of labor.","options":[{"label":"Dig the basin and line it","effects":{"hr":-30,"gold":90}},{"label":"Beach the boats on the mudflats","effects":{"gold":20}}]},{"id":"ai_indic_polished_axes","ageId":"stone","year":-3000,"theme":"indic","title":"Polished Stone Axes","description":"Hill farmers near the Taxila valley grind stone axes smooth and sharp, clearing scrub for wheat and barley. The quarries lie in lands your herders also claim.","options":[{"label":"Clear the hillsides for new fields","effects":{"hr":25,"controlPenalty":5}},{"label":"Trade axes to the herders for peace","effects":{"gold":-30}}]},{"id":"ai_indic_marsh_rice","ageId":"stone","year":-3000,"theme":"indic","title":"Rice of the Marshes","description":"Your villagers tend wild rice in the lakeside marshes of the Ganges plain, and some begin sowing it on purpose. The new fields need ditches and patience.","options":[{"label":"Dig channels and sow the rice","effects":{"hr":-20,"gold":70}},{"label":"Keep hunting and gathering by the lakes","effects":{"militaryStrengthBonus":10,"techPoints":-5}}]},{"id":"ai_indic_river_floods","ageId":"stone","year":-2500,"theme":"indic","title":"The River Bank Village","description":"Your people settle on a high bank where the rivers meet, making tools of bone and antler. The floods bring rich silt but sometimes sweep huts away.","options":[{"label":"Raise the mounds higher each year","effects":{"hr":-20,"defenseBonus":0.08}},{"label":"Farm the silt and rebuild after floods","effects":{"gold":50,"controlPenalty":6}}]},{"id":"ai_indic_weights_and_seals","ageId":"stone","year":-2500,"theme":"indic","title":"Cubes of Chert","description":"Merchants quarrel over measures, and your scribes offer polished chert weights of fixed size and carved seals to mark every bale. Enforcing them means inspectors in every market.","options":[{"label":"Impose one set of weights everywhere","effects":{"controlBonus":10,"gold":-50}},{"label":"Let each town keep its customs","effects":{"gold":30,"controlPenalty":7}}]},{"id":"ai_indic_cattle_pen_fires","ageId":"stone","year":-2400,"theme":"indic","title":"Fires of the Cattle Pens","description":"Deccan herders pile dung in great cattle pens and burn it in towering fires, leaving mounds of ash. The rite binds the clans, but it costs a season's fuel.","options":[{"label":"Hold the great burning together","effects":{"controlBonus":8,"gold":-40}},{"label":"Spread the dung on the millet fields","effects":{"gold":40,"controlPenalty":5}}]}];

export const AI_DRAWS = CARDS.map(({ id, ageId, year, theme, title, description, options }) => ({
  id,
  family: `ai_${theme}`,
  weight: AI_CARD_WEIGHT,
  once: true,
  theme,
  requires: { all: [{ fact: 'ageIndex', min: getAgeIndex(ageId), max: getAgeIndex(ageId) }, { fact: 'ageTechs', min: eventTechsNeeded(ageIdOfYear(year), year) }] },
  build: () => ({ title, description, options })
}));
